class CompleteRowInitialBuildTests(unittest.TestCase):
    """R448, roadmap Session 124: an initial build around rows that are already complete.

    A re-downloaded DKEntries template that carries a lineup Ben already entered
    refused EVERY write on an initial build: `run_slate` made each row a
    requirement, the allocator gave the complete row a lineup, and the writer
    refused it (`already complete and immutable`) with no review-grade file. The
    complete row is FIXED instead: left in the file untouched, counted through
    `fixed_portfolio_exposure` (R61), and its lineup held out of its contest for
    F-3; the requirements cover the blank and partial rows only.

    Driven on the vendored 2026-06-03 template (18 reserved rows, three contests)
    through `run_slate` directly, the candidates the baseline core builds,
    caps opened and the gates the fixture cannot evidence assumed, so a failure
    here is the item's and not a cap's. Every write lands in a temp root. A
    template with a complete row is the vendored one with row 5157463016 filled
    from the certified build, which is the Verification's shape.
    """

    _SALARY = REPO / "data" / "archive" / "2026-06-03" / "DKSalaries_2026-06-03.csv"
    _ENTRIES = REPO / "data" / "archive" / "2026-06-03" / "DKEntries_2026-06-03.csv"
    _OPEN = {"max_player_exposure_pct": 1.0, "max_pitcher_exposure_pct": 1.0,
             "max_primary_stack_exposure_pct": 1.0, "max_team_exposure_pct": 1.0,
             "max_consensus_cluster_share_pct": 1.0, "max_sp_pair_repetition": 999,
             "max_shared_players": 9}
    _UNEVIDENCED = ["odds_gate_passed", "weather_gate_passed",
                    "pitcher_audit_gate_passed", "lineup_gate_passed"]
    HELD_ID, HELD_CONTEST = "5157463016", "191020573"
    PARTIAL_ID = "5157463351"  # a blank row in the held row's contest

    @classmethod
    def setUpClass(cls):
        import shutil
        from mlb_engine.intake.slate_intake_manager import parse_dk_salary_csv
        from mlb_engine.pipeline import baseline as bl
        cls._tmp = tempfile.TemporaryDirectory()
        cls.base = Path(cls._tmp.name)
        cls.salary = cls.base / "DKSalaries.csv"
        # `copyfile`, not `copy`: the tracked archive fixtures are read-only on
        # this host and `copy` carries the bit (CLAUDE.local.md).
        shutil.copyfile(cls._SALARY, cls.salary)
        cls.blank = cls.base / "DKEntries_blank.csv"
        shutil.copyfile(cls._ENTRIES, cls.blank)
        cls.frame = pd.DataFrame([{
            "Player_ID": sp.player_id, "Name": sp.name, "Team": sp.team,
            "Opponent": sp.opponent, "Position": sp.raw["Roster Position"],
            "Salary": sp.salary, "Game_ID": sp.game_id,
            "Floor": 12.0 if "P" in sp.positions else 5.0,
            "Ceiling": 25.0 if "P" in sp.positions else 12.0,
            "Excluded": False, "Locked": False,
        } for sp in parse_dk_salary_csv(str(cls.salary))])
        core = bl.build_baseline(cls.salary, cls.frame,
                                 requirements=bl.requirements_from_entries(cls.blank),
                                 budget_s=120)
        assert core.status == "covered", core.summary()
        cls.core = core
        cls.cands = core.allocator_candidates(cls.frame, 18)
        # The held row is filled from the certified build: the lineup an ordinary
        # build seats in that row of the blank template (ordered slots P P C 1B
        # 2B 3B SS OF OF OF). A lineup the allocator ranks into that contest, so
        # a naive filter that tells it nothing about the held row seats it again.
        from mlb_engine.entries import upload_manifest as um
        original, um.REPO_ROOT = um.REPO_ROOT, cls.base
        try:
            with contextlib.redirect_stdout(io.StringIO()):
                certified = run_slate(
                    runs_root=cls.base / "runs_certified", salary_csv=cls.salary,
                    entries_csv=cls.blank, projections_override=cls.frame,
                    candidates_override=list(cls.cands),
                    portfolio_controls_override=dict(cls._OPEN), approve=True,
                    assume_gates=cls._UNEVIDENCED, requested_n=18)
        finally:
            um.REPO_ROOT = original
        assert certified["passed"], certified.get("errors")
        from mlb_engine.entries.dk_entries_manager import parse_dk_entry_rows
        cls.held_roster = list({r.entry_id: r for r in parse_dk_entry_rows(
            str(certified["output_path"]))}[cls.HELD_ID].roster_cells)

    @classmethod
    def tearDownClass(cls):
        cls._tmp.cleanup()

    def setUp(self):
        from mlb_engine.entries import upload_manifest as um
        self.um = um
        self.root = Path(tempfile.mkdtemp(dir=self.base))
        self._original_root = um.REPO_ROOT
        um.REPO_ROOT = self.root
        self.addCleanup(self._restore)

    def _restore(self):
        self.um.REPO_ROOT = self._original_root

    # -- fixtures --------------------------------------------------------- #

    def _template(self, name, filled=None, partial=None):
        """The vendored blank template with ``filled`` ``{entry_id: roster}``
        complete and ``partial`` ``{entry_id: roster[:5]}`` half-entered."""
        with self.blank.open(newline="", encoding="utf-8-sig") as handle:
            rows = list(csv.reader(handle))
        for row in rows:
            if row and row[0] in (filled or {}):
                row[4:14] = list(filled[row[0]])
            elif row and row[0] in (partial or {}):
                row[4:9] = list(partial[row[0]][:5])
        path = self.root / name
        with path.open("w", newline="", encoding="utf-8") as handle:
            csv.writer(handle).writerows(rows)
        return path

    def _one_complete(self, name="DKEntries_one_complete.csv", partial=False):
        return self._template(
            name, filled={self.HELD_ID: self.held_roster},
            partial=({self.PARTIAL_ID: list(self.core.candidates[1].roster)}
                     if partial else None))

    def _run(self, entries, *, approve=True, candidates=None, tag="r"):
        with contextlib.redirect_stdout(io.StringIO()):
            return run_slate(
                runs_root=self.root / f"runs_{tag}", salary_csv=self.salary,
                entries_csv=entries, projections_override=self.frame,
                candidates_override=list(candidates if candidates is not None
                                         else self.cands),
                portfolio_controls_override=dict(self._OPEN), approve=approve,
                assume_gates=self._UNEVIDENCED, requested_n=18)

    @staticmethod
    def _rows(path):
        from mlb_engine.entries.dk_entries_manager import parse_dk_entry_rows
        return {r.entry_id: r for r in parse_dk_entry_rows(str(path))}

    # -- the item --------------------------------------------------------- #

    def test_one_complete_row_is_built_around_and_left_untouched(self):
        """The Verification's shape: 17 rows delivered around the held one, its
        bytes unchanged, and its lineup not seated again in its contest (F-3)."""
        entries = self._one_complete()
        result = self._run(entries)
        self.assertTrue(result["passed"], result.get("errors"))
        self.assertTrue(result["workflow_valid"])
        built = self._rows(result["output_path"])
        held_in = self._rows(entries)[self.HELD_ID]
        self.assertEqual(len(built), 18)
        self.assertTrue(all(r.is_complete for r in built.values()),
                        "17 built rows and the held one: every reserved row full")
        self.assertEqual(built[self.HELD_ID].roster_cells, held_in.roster_cells,
                         "the held row is the same ordered lineup, slot for slot")
        same_contest = [r for r in built.values()
                        if r.contest_id == self.HELD_CONTEST and r.entry_id != self.HELD_ID]
        self.assertTrue(same_contest)
        self.assertNotIn(held_in.lineup_signature,
                         {r.lineup_signature for r in same_contest},
                         "F-3: the held lineup is not seated twice in its contest")

    def test_the_held_row_is_counted_by_the_allocator_at_the_files_denominator(self):
        """R61's two denominators on an initial build: the solve is handed 17 rows
        and the validator grades 18, so the allocator is told about the held one."""
        result = self._run(self._one_complete())
        self.assertTrue(result["passed"], result.get("errors"))
        report = self._allocation(result).get("fixed_exposure_report") or {}
        self.assertEqual(report.get("untouchable_row_count"), 1, report)
        self.assertEqual(report.get("solve_entry_count"), 17, report)
        self.assertEqual(report.get("entry_denominator"), 18, report)

    def _allocation(self, result):
        diag = json.loads((Path(result["run_dir"]) / "final" / "diagnostics.json")
                          .read_text(encoding="utf-8"))
        return diag.get("allocation") or {}

    def test_without_the_fixed_row_seam_the_held_lineup_is_seated_twice(self):
        """The negative control for the naive fix (requirements over the blank
        rows, nothing told to the allocator): a blank row in the held row's
        contest takes the held lineup, and the export validator refuses the file
        for it. The seam, not the filter, is what keeps F-3."""
        with unittest.mock.patch.object(epi, "fixed_portfolio_exposure",
                                        lambda *a, **k: None):
            result = self._run(self._one_complete(), tag="naive")
        self.assertFalse(result["passed"], "the held lineup was seated twice")
        self.assertTrue(any("duplicate roster" in str(e) for e in result["errors"]),
                        result["errors"])

    def test_a_blank_template_builds_exactly_as_before(self):
        """No complete row: no fixed-exposure report and no extra read, so the
        blank path is untouched (GOLD is the pin; this is the direct one)."""
        result = self._run(self.blank, tag="blank")
        self.assertTrue(result["passed"], result.get("errors"))
        self.assertNotIn("fixed_exposure_report", self._allocation(result))
        built = self._rows(result["output_path"])
        self.assertEqual(len(built), 18)
        self.assertTrue(all(r.is_complete for r in built.values()))

    def test_a_partial_row_beside_a_held_row_is_still_refilled(self):
        """Only COMPLETE rows are fixed. A half-entered row is refilled by the
        build as it always was."""
        entries = self._one_complete(partial=True)
        before = self._rows(entries)
        self.assertFalse(before[self.PARTIAL_ID].is_complete)
        self.assertFalse(before[self.PARTIAL_ID].is_blank)
        result = self._run(entries, tag="partial")
        self.assertTrue(result["passed"], result.get("errors"))
        built = self._rows(result["output_path"])
        self.assertTrue(built[self.PARTIAL_ID].is_complete)
        self.assertEqual(built[self.HELD_ID].roster_cells,
                         before[self.HELD_ID].roster_cells)

    def test_a_template_with_every_row_complete_is_refused_by_name(self):
        """Nothing is left to fill, so there is nothing to build: refused up
        front with the reason, never at the writer as `already complete and
        immutable`. A refinement of a delivered file is a late swap."""
        filled = {}
        per_contest = {}
        for row in self._rows(self.blank).values():
            slot = per_contest.setdefault(row.contest_id, 0)
            filled[row.entry_id] = list(self.core.candidates[slot].roster)
            per_contest[row.contest_id] = slot + 1
        entries = self._template("DKEntries_all_complete.csv", filled=filled)
        self.assertTrue(all(r.is_complete for r in self._rows(entries).values()))
        result = self._run(entries, tag="all")
        self.assertFalse(result["passed"])
        text = " ".join(str(e) for e in result["errors"])
        self.assertIn("every reserved row is already complete", text)
        self.assertIn("18 of 18", text)
        self.assertNotIn("already complete and immutable", text)
        self.assertIsNone(result.get("output_path"))

    def test_the_review_leg_names_the_rows_it_holds(self):
        """`approve=False` is the read the operator takes before approving; it
        says which complete rows the build will leave alone."""
        result = self._run(self._one_complete(), approve=False, tag="review")
        self.assertEqual(result["status"], "plan_pending_approval", result.get("errors"))
        self.assertEqual(result["held_complete_entry_ids"], [self.HELD_ID])

    def test_an_empty_template_is_not_reported_as_complete(self):
        """No reserved rows at all is a different failure from every row being
        full: it still fails the entry-grid gate, and says nothing about rows
        being complete."""
        with self.blank.open(newline="", encoding="utf-8-sig") as handle:
            header = next(csv.reader(handle))
        empty = self.root / "DKEntries_empty.csv"
        with empty.open("w", newline="", encoding="utf-8") as handle:
            csv.writer(handle).writerow(header)
        result = self._run(empty, tag="empty")
        self.assertFalse(result["passed"])
        text = " ".join(str(e) for e in result["errors"])
        self.assertIn("entry_grid_gate_passed", text)
        self.assertNotIn("already complete", text)

    def test_the_fixed_exposure_read_happens_only_when_a_row_is_held(self):
        """A blank template computes nothing extra (the R28 precedent: the build
        stays byte-identical by construction); a held row costs one read."""
        real = epi.fixed_portfolio_exposure
        calls: list = []

        def spy(*args, **kwargs):
            calls.append(args)
            return real(*args, **kwargs)
        with unittest.mock.patch.object(epi, "fixed_portfolio_exposure", spy):
            self._run(self.blank, tag="spy_blank")
            self.assertEqual(calls, [], "a blank template reads no fixed rows")
            self._run(self._one_complete(), tag="spy_held")
        self.assertEqual(len(calls), 1)

    def test_a_contest_whose_rows_are_all_complete_is_held_whole(self):
        """Every row of one contest already holds a lineup and the others are
        blank: the contest has no requirement left but keeps its posture, its
        place in the manifest and its F-3 signatures, and the build fills the
        rest around it."""
        rows = self._rows(self.blank)
        small = [r.entry_id for r in rows.values() if r.contest_id == "191047506"]
        self.assertEqual(len(small), 4)
        filled = {eid: list(self.core.candidates[i].roster)
                  for i, eid in enumerate(small)}
        entries = self._template("DKEntries_whole_contest.csv", filled=filled)
        result = self._run(entries, tag="whole")
        self.assertTrue(result["passed"], result.get("errors"))
        built = self._rows(result["output_path"])
        held_in = self._rows(entries)
        self.assertEqual(len(built), 18)
        for eid in small:
            self.assertEqual(built[eid].roster_cells, held_in[eid].roster_cells)
        self.assertEqual(sorted(result["held_complete_entry_ids"]), sorted(small))

    # -- the baseline reads the same rows ---------------------------------- #

    def test_the_baseline_requirements_fill_blank_and_partial_rows_and_hold_complete_ones(self):
        from mlb_engine.pipeline import baseline as bl
        entries = self._one_complete(partial=True)
        reqs = {r.contest_id: r for r in bl.initial_build_requirements(entries)}
        held = reqs[self.HELD_CONTEST]
        self.assertNotIn(self.HELD_ID, held.fillable_entry_ids)
        self.assertIn(self.PARTIAL_ID, held.fillable_entry_ids,
                      "`run_slate` refills a partial row, so the baseline covers it")
        self.assertEqual(len(held.held_signatures), 1)
        self.assertEqual(held.partial_entry_ids, ())
        self.assertEqual(sum(len(r.fillable_entry_ids) for r in reqs.values()), 17)

    def test_the_baseline_on_a_one_complete_template_publishes_every_row(self):
        """The R389(b) door on a re-downloaded template: the core seeds F-3 from
        the held lineup, and the file its candidates export through `run_slate`
        covers all 18 rows with the held one untouched."""
        from mlb_engine.intake.live_data_adapters import build_slate_pool
        pool = build_slate_pool(str(self.salary), {"games": []},
                                declared_pitchers={p: "declared_probable_sp" for p in
                                                   ClassicBaselineFirstTests._DECLARED},
                                stale_platoon_policy="warn")
        # The held lineup has to be legal under THIS pool (declared pitchers
        # only; a held row the validator judges illegal blocks, which is this
        # item's stated limit), so it is the baseline's own seat in the held row
        # on the blank template, filled in the way the other tests fill theirs.
        with contextlib.redirect_stdout(io.StringIO()):
            first = epi.run_baseline(
                runs_root=str(self.root / "runs_baseline_blank"), salary_csv=self.salary,
                entries_csv=self.blank, pool=pool, requested_n=18,
                deadline=time.monotonic() + 120.0)
        self.assertTrue(first["result"]["passed"], first["result"].get("errors"))
        seats = self._rows(first["result"]["output_path"])
        # One complete row and one half-entered row in the same contest: the
        # baseline fills the half-entered one because `run_slate` does.
        entries = self._template(
            "DKEntries_baseline_one_complete.csv",
            filled={self.HELD_ID: list(seats[self.HELD_ID].roster_cells)},
            partial={self.PARTIAL_ID: list(seats[self.PARTIAL_ID].roster_cells)})
        with contextlib.redirect_stdout(io.StringIO()):
            out = epi.run_baseline(
                runs_root=str(self.root / "runs_baseline"), salary_csv=self.salary,
                entries_csv=entries, pool=pool, requested_n=18,
                deadline=time.monotonic() + 120.0)
        self.assertEqual(out["status"], "allocated", out.get("core"))
        contest = out["core"]["by_contest"][0]
        self.assertEqual((contest["fillable"], contest["held"], contest["partial"]),
                         (6, 1, 0), "5 blank + 1 half-entered row to fill, 1 held")
        result = out["result"]
        self.assertTrue(result["passed"], result.get("errors"))
        built = self._rows(result["output_path"])
        self.assertEqual(len(built), 18)
        held_in = self._rows(entries)[self.HELD_ID]
        self.assertEqual(built[self.HELD_ID].roster_cells, held_in.roster_cells)
        others = {r.lineup_signature for r in built.values()
                  if r.contest_id == self.HELD_CONTEST and r.entry_id != self.HELD_ID}
        self.assertNotIn(held_in.lineup_signature, others)


class ClassicBaselineFirstTests(unittest.TestCase):
    """R389(b), roadmap Session 11: baseline-first Classic.

    `run_classic` publishes the core's entry-mapped baseline BEFORE any
    research: exported through `run_slate`, re-read on its exact bytes,
    presented and kept in `_LAST_USABLE`, under `review_grade_baseline`, as
    ``DKEntries_<tag>_BASELINE_<run>.csv`` in its own manifest lineage.

    Driven on the vendored 2026-06-03 slate (2 games, 18 reserved rows, three
    contests) through the real exit door: `_main_recording_refusals` with
    `main` swapped for the `run_classic` call (LastUsableArtifactTests'
    pattern). Every write lands in a temp root (`mod.REPO` and
    `upload_manifest.REPO_ROOT`); research reads a temp copy of the vendored
    reference data. Faked only: the injected crashes and, where the test is
    about presentation and not the enhanced engine, the enhanced `run_slate`
    (the baseline's own call always runs for real).

    Reproduced first at 88aacc6: a crash after research (then in
    `resolve_leverage`, and at `run_slate` entry) exited 1 with no file.
    """

    _SALARY = REPO / "data" / "archive" / "2026-06-03" / "DKSalaries_2026-06-03.csv"
    _ENTRIES = REPO / "data" / "archive" / "2026-06-03" / "DKEntries_2026-06-03.csv"
    _DECLARED = ["43205901", "43206001", "43206000", "43205902",
                 "43206010", "43206009", "43206002", "43206013"]
    _AS_OF = "2026-06-03T12:00:00-04:00"
    _OPEN = {"max_player_exposure_pct": 1.0, "max_pitcher_exposure_pct": 1.0,
             "max_primary_stack_exposure_pct": 1.0, "max_team_exposure_pct": 1.0,
             "max_consensus_cluster_share_pct": 1.0, "max_sp_pair_repetition": 999,
             "max_shared_players": 9}
    _REFUSAL = {"passed": False, "run_id": "enhanced_r1", "workflow_valid": False,
                "errors": ["failed post-export gate: portfolio_caps_passed"],
                "feasibility": {"passed": False, "checks": []}}

    @classmethod
    def setUpClass(cls):
        import shutil
        cls._tmp = tempfile.TemporaryDirectory()
        cls.base = Path(cls._tmp.name)
        cls.reference = cls.base / "reference"
        shutil.copytree(REPO / "data" / "reference", cls.reference)
        cls._full_build = None

    @classmethod
    def _full(cls):
        """Fact 2 and fact 3 share one real build, made on first use: the
        baseline, then an enhanced file that certifies because its caps are
        opened by --controls-override (about 25s here, most of it the bank)."""
        if cls._full_build is None:
            cls._full_build = cls._build_in(cls.base / "full",
                                            controls_override=dict(cls._OPEN))
        return cls._full_build

    @classmethod
    def tearDownClass(cls):
        cls._tmp.cleanup()

    # -- the harness ------------------------------------------------------ #

    @classmethod
    def _module(cls):
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "build_slate_r389b", REPO / "skills" / "generate-lineups" / "scripts"
            / "build_slate.py")
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        return mod

    @classmethod
    def _args(cls, **overrides):
        base = dict(
            date="2026-06-03", entries=None, controls_override=None,
            projections=None, lineups=None, odds=None, postures=None,
            deliver_by=None, _governor=None, max_seconds=300.0,
            declare_pitcher=list(cls._DECLARED), ignore_pool_blockers=True,
            assume_gates="lineup_gate_passed", rotowire=False, enrichment=True,
            reference_dir=str(cls.reference), reference_max_age_days=14.0,
            past_slate_replay=True, leverage=None,
            max_opposing_hitters_per_sp=None, ownership_pred=None,
            feed_max_age_minutes=90.0, bundle=None, tbd_fallback=None,
            brief=None, bank_max_candidates=None)
        base.update(overrides)
        return types.SimpleNamespace(**base)

    @classmethod
    def _build_in(cls, root, *, patches=(), fake_enhanced=None, via_exit_door=True,
                  slate=None, **arg_overrides):
        """One build in ``root``. Returns a dict: code, brief, err, out, mod,
        calls (every run_slate kwargs), root. ``fake_enhanced`` is a list of
        results the ENHANCED run_slate calls return in turn; the baseline's
        call always runs for real. ``slate`` is None for the vendored
        2026-06-03 slate every other test drives, or ``(date, salary_csv,
        entries_csv)`` for another one (R476's 2026-06-28)."""
        import shutil
        from mlb_engine.entries import upload_manifest as um
        root = Path(root)
        date, salary_csv, entries_csv = slate or ("2026-06-03", cls._SALARY, cls._ENTRIES)
        (root / "slate").mkdir(parents=True, exist_ok=True)
        shutil.copy(salary_csv, root / "slate" / "DKSalaries.csv")
        mod = cls._module()
        mod.REPO = root
        arg_overrides.setdefault("date", date)
        args = cls._args(**arg_overrides)
        calls: list = []
        stash: dict = {}
        real_run_slate = epi.run_slate

        def spy_run_slate(**kw):
            calls.append(dict(kw))
            if fake_enhanced is not None and not kw.get("delivery_lineage"):
                enhanced = [c for c in calls if not c.get("delivery_lineage")]
                return dict(fake_enhanced[min(len(enhanced), len(fake_enhanced)) - 1])
            return real_run_slate(**kw)

        def main():
            code, brief = mod.run_classic(
                args, root / "slate", salary_csv, entries_csv, {"games": []},
                _build_deadline(float(args.max_seconds)))
            stash["brief"] = brief
            return code

        out, err = io.StringIO(), io.StringIO()
        env = {k: v for k, v in os.environ.items() if k != "THE_ODDS_API_KEY"}
        with contextlib.ExitStack() as stack:
            stack.enter_context(unittest.mock.patch.dict(os.environ, env, clear=True))
            stack.enter_context(unittest.mock.patch.object(um, "REPO_ROOT", root))
            stack.enter_context(unittest.mock.patch.object(epi, "run_slate", spy_run_slate))
            stack.enter_context(unittest.mock.patch.object(mod, "main", main))
            stack.enter_context(unittest.mock.patch.object(
                sys, "argv", ["build_slate.py", "--date", date]))
            for target, name, value in patches:
                stack.enter_context(unittest.mock.patch.object(
                    mod if target == "mod" else target, name, value))
            stack.enter_context(contextlib.redirect_stdout(out))
            stack.enter_context(contextlib.redirect_stderr(err))
            if via_exit_door:
                code = mod._main_recording_refusals()
            else:
                try:
                    code = main()
                except Exception as exc:  # noqa: BLE001
                    code = exc
        text = out.getvalue()
        brief = stash.get("brief")
        if brief is None and "{" in text:
            brief = json.loads(text[text.rfind("\n{") + 1 if "\n{" in text else text.find("{"):])
        return {"code": code, "brief": brief or {}, "err": err.getvalue(),
                "out": text, "mod": mod, "calls": calls, "root": root}

    @staticmethod
    def _rows(root):
        path = Path(root) / "outputs" / "2026-06-03" / "upload_manifest.json"
        return json.loads(path.read_text(encoding="utf-8"))["deliveries"]

    @staticmethod
    def _file_lines(err):
        return [line for line in err.splitlines() if line.startswith("FILE  ")]

    def _preflight(self, path, *extra, salary=None, as_of=None):
        from tools import preflight_upload
        out = io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
            code = preflight_upload.main([
                "--entries", str(path), "--salary", str(salary or self._SALARY),
                "--json", "--as-of", as_of or self._AS_OF, *extra])
        return code, json.loads(out.getvalue())

    @staticmethod
    def _crash(message):
        def boom(*_a, **_k):
            raise RuntimeError(message)
        return boom

    # -- the row's three facts -------------------------------------------- #

    def test_a_crash_after_the_baseline_delivers_the_baseline(self):
        """Fact 1. A crash in research, and at the enhanced solve's entry, exits
        7 with the baseline presented first and last; at 88aacc6 both exited 1
        with no file."""
        for label, patches, fake in (
                ("research", [("mod", "resolve_reference_data",
                               self._crash("injected in resolve_reference_data"))], None),
                ("enhanced run_slate entry", [], "raise")):
            with self.subTest(crash=label):
                root = Path(tempfile.mkdtemp(dir=self.base))
                if fake == "raise":
                    real = epi.run_slate

                    def raising(**kw):
                        if kw.get("delivery_lineage"):
                            return real(**kw)
                        raise RuntimeError("injected at run_slate entry")
                    patches = [(epi, "run_slate", raising)]
                    build = self._build_in(root, patches=patches)
                else:
                    build = self._build_in(root, patches=patches)
                self.assertEqual(build["code"], 7, build["err"][-800:])
                files = self._file_lines(build["err"])
                self.assertGreaterEqual(len(files), 2)
                self.assertIn("_BASELINE_", files[0])
                self.assertIn("_BASELINE_", files[-1])
                self.assertLess(build["err"].index(files[-1]),
                                build["err"].index("LATER FAILURE"))
                brief = build["brief"]
                self.assertEqual(brief["status"], "delivered_after_failure")
                path = Path(brief["delivered_path"])
                self.assertIn("_BASELINE_", path.name)
                self.assertEqual(brief["delivered_sha256"],
                                 hashlib.sha256(path.read_bytes()).hexdigest())
                self.assertEqual(brief["label"], "review_grade_baseline")
                self.assertTrue(brief["baseline"]["current"])
                records = sorted((root / "data" / "deliveries").rglob("*.json"))
                refusal = [json.loads(p.read_text()) for p in records]
                refusal = [r for r in refusal if r.get("kind") == "refusal"]
                self.assertEqual(refusal[-1]["exit_code"], 7)
                self.assertEqual(refusal[-1]["refusal"]["last_usable_artifact"]["sha256"],
                                 brief["delivered_sha256"])

    def test_the_enhanced_file_supersedes_nothing_ben_holds(self):
        """Fact 2. The enhanced delivery records after the baseline, and the
        baseline row stays live in its own lineage; preflight passes on both
        files' exact bytes after both are recorded."""
        full = self._full()
        self.assertEqual(full["code"], 0, full["err"][-800:])
        rows = self._rows(full["root"])
        baseline = [r for r in rows if r.get("lineage") == "baseline"]
        enhanced = [r for r in rows if not r.get("lineage")]
        self.assertEqual(len(baseline), 1)
        self.assertEqual(len(enhanced), 1)
        self.assertLess(rows.index(baseline[0]), rows.index(enhanced[0]),
                        "the baseline must record before the enhanced file")
        self.assertNotEqual(baseline[0]["status"], "superseded")
        self.assertNotIn("superseded_by", baseline[0])
        self.assertEqual(baseline[0]["certification"], "review_grade_baseline")
        self.assertEqual(enhanced[0]["certification"], "certified")
        root = full["root"]
        b_path = root / baseline[0]["delivered_file"]
        e_path = root / enhanced[0]["delivered_file"]
        self.assertNotEqual(b_path, e_path)
        with unittest.mock.patch.object(
                __import__("mlb_engine.entries.upload_manifest",
                           fromlist=["REPO_ROOT"]), "REPO_ROOT", root):
            b_code, b_rep = self._preflight(b_path)
            e_code, e_rep = self._preflight(e_path)
        self.assertEqual((b_code, b_rep["verdict"]), (0, "review_ready"), b_rep["failures"])
        self.assertIn("R389(b)", b_rep["verdict_note"])
        self.assertEqual((e_code, e_rep["verdict"]), (0, "upload_ready"), e_rep["failures"])
        # [B2] Declared pitchers reach preflight through the brief bound to
        # the baseline's own sha, beside the file.
        self.assertIn(f"build_brief_{b_path.stem[len('DKEntries_'):]}.json",
                      b_rep["info"]["declared_pitchers_source"])
        brief = full["brief"]
        self.assertFalse(brief["baseline"]["current"])
        self.assertIn("_BASELINE_", self._file_lines(full["err"])[0])
        self.assertNotIn("_BASELINE_", self._file_lines(full["err"])[-1])

    def test_the_baseline_is_essential_valid_on_its_exact_bytes(self):
        """Fact 3. The presented bytes are the recorded bytes and the run's
        immutable export; every V post-export gate passed on them; the
        independent re-read passes; 18 of 18 rows; no lineup twice in a
        contest (F-3)."""
        block = self._full()["brief"]["baseline"]
        self.assertEqual(block["status"], "delivered")
        path = Path(block["path"])
        data = path.read_bytes()
        sha = hashlib.sha256(data).hexdigest()
        self.assertEqual(block["sha256"], sha)
        row = [r for r in self._rows(self._full()["root"]) if r.get("lineage")][0]
        self.assertEqual(row["sha256"], sha)
        run_export = Path(block["run_path"])
        self.assertEqual(run_export.name, "DKEntries.csv")
        self.assertEqual(run_export.parent.name, "final")
        self.assertEqual(hashlib.sha256(run_export.read_bytes()).hexdigest(), sha)
        json.dumps(block)  # main() writes the brief without default=str
        self.assertEqual(block["later_failures"], [])
        essential = block["essential_valid"]
        self.assertIs(essential["essential_valid"], True)
        self.assertEqual(essential["failed"], [])
        self.assertIs(essential["bytes_match_record"], True)
        self.assertEqual(block["coverage"], {"reserved": 18, "filled": 18})
        verdict = self._full()["mod"].verify_classic(self._SALARY, path)
        self.assertTrue(verdict["passed"], verdict["failures"])
        by_contest = defaultdict(list)
        for entry in parse_dk_entry_rows(str(path)):
            by_contest[entry.contest_id].append(entry.lineup_signature)
        self.assertEqual(sum(len(v) for v in by_contest.values()), 18)
        for cid, sigs in by_contest.items():
            self.assertEqual(len(sigs), len(set(sigs)), f"a lineup twice in {cid}")

    # -- R476: the baseline on a pool that carries a negative-APPG arm -------- #

    # The tracked 2026-06-28 salary file: 998 rows, 11 games, 8 SP rows at a
    # negative season AvgPointsPerGame (the premise check's list). Declared here
    # beside eight positive arms, so the pool holds every one of them.
    _SALARY_0628 = REPO / "data" / "archive" / "2026-06-28" / "DKSalaries_2026-06-28.csv"
    _ENTRIES_0628 = REPO / "data" / "archive" / "2026-06-28" / "DKEntries_2026-06-28.csv"
    _POSITIVE_0628 = ["43434243", "43434244", "43433708", "43434247",
                      "43433709", "43434249", "43434250", "43433710"]
    _NEGATIVE_0628 = {"43433715": -1.15, "43434336": -4.55, "43434353": -17.3,
                      "43434399": -1.62, "43434434": -3.8, "43434442": -3.8,
                      "43434445": -2.38, "43434457": -1.9}

    @classmethod
    def _blanked_entries_0628(cls):
        """The tracked entries file with every roster cell cleared: the archive
        holds the lineups Ben entered, and a filled row is complete and
        immutable to the baseline, which reserves only blank ones (38 rows)."""
        path = cls.base / "DKEntries_2026-06-28_blank.csv"
        if not path.exists():
            with cls._ENTRIES_0628.open(encoding="utf-8-sig", newline="") as fh:
                rows = list(csv.reader(fh))
            for row in rows[1:]:
                if row and row[0]:
                    row[4:14] = [""] * 10
            with path.open("w", encoding="utf-8", newline="") as fh:
                csv.writer(fh).writerows(rows)
        return path

    def test_a_negative_appg_arm_does_not_cost_the_2026_06_28_baseline(self):
        """R476. At a47c219 this build's baseline was `status: error` (`Base
        contains negative values`) and nothing was published before research.
        Now the eight negative arms stay in the pool at Base 0.0, the baseline
        covers all 38 reserved rows, the record names them, and an injected
        enhancement refusal still names the baseline as the current file."""
        entries = self._blanked_entries_0628()
        build = self._build_in(
            Path(tempfile.mkdtemp(dir=self.base)),
            slate=("2026-06-28", self._SALARY_0628, entries),
            declare_pitcher=self._POSITIVE_0628 + sorted(self._NEGATIVE_0628),
            fake_enhanced=[self._REFUSAL])
        self.assertEqual(build["code"], 3, build["err"][-800:])
        payload = build["brief"]
        block = payload["baseline"]
        self.assertEqual(block["status"], "delivered", block)
        self.assertEqual(block["coverage"], {"reserved": 38, "filled": 38})
        self.assertTrue(block["current"])
        # The count and the original values, on the brief's baseline block
        # and on the baseline's own bound brief file.
        clipped = block["projection"]["negative_appg_clipped"]
        self.assertEqual(clipped["n"], 8)
        self.assertEqual(clipped["ids"], sorted(self._NEGATIVE_0628))
        self.assertEqual(clipped["original"], self._NEGATIVE_0628)
        path = Path(block["path"])
        bound = json.loads(sorted(path.parent.glob("build_brief_*_BASELINE_*.json"))[-1]
                           .read_text(encoding="utf-8"))
        self.assertEqual(bound["baseline"]["projection"]["negative_appg_clipped"]["n"], 8)
        # The refusal names it: the last usable artifact is the baseline's bytes.
        sha = hashlib.sha256(path.read_bytes()).hexdigest()
        self.assertEqual(block["sha256"], sha)
        records = [json.loads(p.read_text()) for p in
                   sorted((build["root"] / "data" / "deliveries").rglob("*.json"))]
        refusal = [r for r in records if r.get("kind") == "refusal"][-1]
        self.assertEqual(refusal["refusal"]["last_usable_artifact"]["sha256"], sha)
        # Both referees pass on the exact bytes, with a distinct lineup per
        # contest (F-3), at the time the review replayed it.
        verdict = build["mod"].verify_classic(self._SALARY_0628, path)
        self.assertTrue(verdict["passed"], verdict["failures"])
        from mlb_engine.entries import upload_manifest as um
        with unittest.mock.patch.object(um, "REPO_ROOT", build["root"]):
            code, report = self._preflight(path, salary=self._SALARY_0628,
                                           as_of="2026-06-28T17:00:00Z")
        self.assertEqual((code, report["verdict"]), (0, "review_ready"), report["failures"])
        by_contest = defaultdict(list)
        for entry in parse_dk_entry_rows(str(path)):
            by_contest[entry.contest_id].append(entry.lineup_signature)
        self.assertEqual(sum(len(v) for v in by_contest.values()), 38)
        for cid, sigs in by_contest.items():
            self.assertEqual(len(sigs), len(set(sigs)), f"a lineup twice in {cid}")

    # -- where it runs and what it is handed -------------------------------- #

    def test_the_baseline_runs_after_leverage_and_before_research(self):
        order: list = []
        mod_calls = {}

        def tracer(name, real):
            def wrapped(*a, **k):
                order.append(name)
                return real(*a, **k)
            return wrapped
        mod = self._module()
        mod_calls["resolve_leverage"] = mod.resolve_leverage
        mod_calls["publish_baseline"] = mod.publish_baseline
        stop = self._crash("stop after the first research call")
        build = self._build_in(
            Path(tempfile.mkdtemp(dir=self.base)), via_exit_door=False,
            patches=[("mod", "resolve_leverage", tracer("leverage", mod.resolve_leverage)),
                     (epi, "run_baseline", tracer("baseline", epi.run_baseline)),
                     ("mod", "resolve_reference_data",
                      lambda *a, **k: (order.append("research"), stop())[1])])
        self.assertIsInstance(build["code"], RuntimeError)
        self.assertEqual(order, ["leverage", "baseline", "research"])

    def test_the_baseline_call_is_approved_unenriched_labelled_and_opened(self):
        never = {"distinct_lineups_per_contest", "max_player_exposure_pct"}
        cores: list = []
        from mlb_engine.pipeline import baseline as bl
        real_core = bl.build_baseline

        def core_spy(*a, **k):
            cores.append(dict(k))
            return real_core(*a, **k)
        build = self._build_in(
            Path(tempfile.mkdtemp(dir=self.base)), via_exit_door=False,
            fake_enhanced=[self._REFUSAL],
            controls_override={"max_player_exposure_pct": 0.9},
            max_opposing_hitters_per_sp=1, _never_relax=never,
            patches=[(bl, "build_baseline", core_spy),
                     ("mod", "resolve_reference_data",
                      self._crash("stop before research"))])
        baseline_calls = [c for c in build["calls"] if c.get("delivery_lineage")]
        self.assertEqual(len(baseline_calls), 1, build["err"][-600:])
        kw = baseline_calls[0]
        self.assertIs(kw["approve"], True)
        self.assertIs(kw["light_satellite"], True)
        self.assertTrue(kw["candidates_override"])
        for key in ("savant_batting_csv", "savant_pitching_csv", "fangraphs_pitching_csv",
                    "f4_by_player_id", "f1_by_player_id", "f5_by_player_id"):
            self.assertIsNone(kw[key], key)
        for key in ("leverage", "weather_game_caps", "input_confidence_facts",
                    "sleeve_implied_total_by_team"):
            self.assertNotIn(key, kw)
        self.assertEqual(kw["certification_label"], "review_grade_baseline")
        self.assertEqual(kw["delivery_lineage"], "baseline")
        self.assertEqual(set(kw["never_relax_controls"]), never)
        controls = kw["portfolio_controls_override"]
        self.assertEqual(controls["max_player_exposure_pct"], 0.9, "never-relax held")
        self.assertEqual(controls["max_shared_players"], 9)
        self.assertEqual(controls["max_opposing_hitters_per_sp"], 1)
        self.assertEqual(cores[0]["max_opposing_hitters_per_sp"], 1)
        moves = {m["control"]: m for m in kw["control_moves"]}
        self.assertNotIn("max_player_exposure_pct", moves)
        self.assertEqual(moves["max_shared_players"]["by"], "baseline")
        self.assertIn("odds_gate_passed", kw["assume_gates"])
        self.assertIn("weather_gate_passed", kw["assume_gates"])
        self.assertIn("lineup_gate_passed", kw["assume_gates"])
        self.assertEqual(kw["source_metadata"]["pool_report"]["kept"],
                         len(kw["projection_rows"]))

    def test_the_engine_s_baseline_call_carries_the_allowance_and_approves(self):
        """BuildContractCheckpointTests pins build_slate to one approve=True
        run_slate call; the baseline's call lives in EP `run_baseline`, and is
        pinned here the same way: approve=True, and the controls the export
        validator grades carry the allowance."""
        tree = ast.parse((REPO / "mlb_engine" / "pipeline"
                          / "execution_pipeline.py").read_text(encoding="utf-8"))
        fn = next(n for n in ast.walk(tree)
                  if isinstance(n, ast.FunctionDef) and n.name == "run_baseline")
        calls = [n for n in ast.walk(fn) if isinstance(n, ast.Call)
                 and getattr(n.func, "id", None) == "run_slate"]
        self.assertEqual(len(calls), 1)
        kws = {kw.arg: kw.value for kw in calls[0].keywords}
        self.assertIs(kws["approve"].value, True)
        self.assertIn("portfolio_controls_override", kws)
        build_calls = [n for n in ast.walk(fn) if isinstance(n, ast.Call)
                       and getattr(n.func, "attr", None) == "build_baseline"]
        self.assertIn("max_opposing_hitters_per_sp",
                      [kw.arg for kw in build_calls[0].keywords])

    def test_the_window_is_a_share_of_the_build_s_own_deadline(self):
        from mlb_engine.pipeline import baseline as bl
        seen: list = []
        real_core = bl.build_baseline

        def core_spy(*a, **k):
            seen.append((time.monotonic(), k["deadline"]))
            return real_core(*a, **k)
        t0 = time.monotonic()
        self._build_in(Path(tempfile.mkdtemp(dir=self.base)), via_exit_door=False,
                       max_seconds=200.0, fake_enhanced=[self._REFUSAL],
                       patches=[(bl, "build_baseline", core_spy),
                                ("mod", "resolve_reference_data",
                                 self._crash("stop before research"))])
        called_at, window_end = seen[0]
        left = (t0 + 200.0) - called_at
        self.assertAlmostEqual(window_end - called_at, bl.BASELINE_WINDOW_SHARE * left,
                               delta=2.0)
        self.assertLess(window_end - called_at, 0.5 * left)

