def _load_build_slate_module(name="_bs_thin_bank"):
    """The build_slate script as a module, for tests that call its functions."""
    import importlib.util
    path = REPO / "skills" / "generate-lineups" / "scripts" / "build_slate.py"
    spec = importlib.util.spec_from_file_location(name, path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class ReplayDeliveryTests(unittest.TestCase):
    """R283, roadmap Session 128 (a): a `--past-slate-replay` build is never recorded
    and never promoted.

    The 2026-08-16 guard appended `_replay` to the STAGED filenames and nothing
    else, so the delivered mirror and the manifest were reachable from a replay:
    on 2026-09-01 a replay of the played 1920_1g_sd Showdown slate overwrote
    `outputs/2026-08-30/DKEntries_showdown_1920_1g_sd.csv` and superseded its
    manifest row. Reproduced at 4821d93 through the real `main()` for both
    contest types (the premise check's `repro.py`); the Showdown leg is in
    `test_showdown.ReplayDeliveryTests`.

    This is the Classic leg. A delivered file is PLANTED where the engine's own
    mirror would write it (`DKEntries_<tag>.csv`) and a replay with perturbed
    controls, so its bytes differ, is run through the real `main()`; the plant,
    the manifest and the tracked records must be exactly as they were, and the
    run itself must still have happened (its immutable `runs/` export exists).
    """

    _DATE = "2026-06-03"
    _SALARY = REPO / "data" / "archive" / "2026-06-03" / "DKSalaries_2026-06-03.csv"
    _ENTRIES = REPO / "data" / "archive" / "2026-06-03" / "DKEntries_2026-06-03.csv"

    @classmethod
    def setUpClass(cls):
        cls._tmp = tempfile.TemporaryDirectory()
        cls.base = Path(cls._tmp.name)
        cls.reference = cls.base / "reference"
        shutil.copytree(REPO / "data" / "reference", cls.reference)
        # Writable copies: the tracked archive fixtures are READ-ONLY on some hosts.
        cls.salary = cls.base / "DKSalaries.csv"
        cls.entries = cls.base / "DKEntries.csv"
        shutil.copyfile(cls._SALARY, cls.salary)
        shutil.copyfile(cls._ENTRIES, cls.entries)

    @classmethod
    def tearDownClass(cls):
        cls._tmp.cleanup()

    @staticmethod
    def _snapshot(root, date):
        """Every byte a replay must leave alone: the delivered CSVs, the manifest
        text, and the tracked delivery records."""
        out = root / "outputs" / date
        csvs = {p.name: p.read_bytes() for p in sorted(out.glob("*.csv"))} if out.exists() else {}
        manifest = out / "upload_manifest.json"
        records = root / "data" / "deliveries"
        return {
            "csv": csvs,
            "manifest": manifest.read_text(encoding="utf-8") if manifest.exists() else None,
            "records": {str(p.relative_to(records)): p.read_bytes()
                        for p in sorted(records.rglob("*.json"))} if records.exists() else {},
        }

    def _plant(self, root):
        """The played slate's delivery, recorded through the one front door under
        the name Classic's mirror gives it."""
        from mlb_engine.entries import upload_manifest as um
        tag = epi._slate_tag(self.salary)
        dest = root / "outputs" / self._DATE / f"DKEntries_{tag}.csv"
        with unittest.mock.patch.object(um, "REPO_ROOT", root):
            out = um.deliver(
                date=self._DATE, dest=dest,
                write=lambda p: Path(p).write_bytes(b"the delivered file Ben holds\n"),
                contest_type="classic", slate_tag=tag, contest_ids=["1"], entries=1,
                run_id="20260603T000000Z_planted", status="candidate",
                certification="certified")
        self.assertTrue(out["recorded"], out["error"])
        return dest

    def _replay(self, root, controls):
        from mlb_engine.entries import upload_manifest as um
        mod = ClassicBaselineFirstTests._module()
        argv = ["build_slate.py", "--salary", str(self.salary), "--entries", str(self.entries),
                "--date", self._DATE, "--past-slate-replay", "--ignore-pool-blockers",
                "--assume-gates", "lineup_gate_passed", "--no-rotowire",
                "--max-seconds", "300", "--reference-dir", str(self.reference),
                "--controls-override", json.dumps(controls)]
        for pid in ClassicBaselineFirstTests._DECLARED:
            argv += ["--declare-pitcher", pid]

        def no_feed(*_a, **_k):
            raise OSError("no egress in a test")

        env = {k: v for k, v in os.environ.items() if k != "THE_ODDS_API_KEY"}
        out, err = io.StringIO(), io.StringIO()
        with contextlib.ExitStack() as stack:
            stack.enter_context(unittest.mock.patch.dict(os.environ, env, clear=True))
            for target, name, value in ((mod, "REPO", root), (um, "REPO_ROOT", root),
                                        (mod, "fetch_lineups", no_feed), (sys, "argv", argv)):
                stack.enter_context(unittest.mock.patch.object(target, name, value))
            stack.enter_context(contextlib.redirect_stdout(out))
            stack.enter_context(contextlib.redirect_stderr(err))
            code = mod._main_recording_refusals()
        return code, out.getvalue(), err.getvalue()

    def test_a_classic_replay_with_other_bytes_leaves_the_delivery_and_the_manifest_alone(self):
        root = self.base / "classic"
        root.mkdir()
        planted = self._plant(root)
        planted_bytes = planted.read_bytes()
        before = self._snapshot(root, self._DATE)
        # Caps opened as the existing Classic harness opens them, and one moved
        # so the replay's bytes cannot equal anything already delivered.
        controls = dict(ClassicBaselineFirstTests._OPEN, max_shared_players=7)
        code, out, err = self._replay(root, controls)
        self.assertEqual(code, 0, err[-1200:])
        finals = sorted((root / "runs").glob("*/final/DKEntries.csv"))
        self.assertTrue(finals, "the replay did not build: no immutable export under runs/")
        replay_sha = hashlib.sha256(finals[-1].read_bytes()).hexdigest()
        self.assertNotEqual(replay_sha, hashlib.sha256(planted_bytes).hexdigest(),
                            "the replay's bytes must differ from the plant or the test is vacuous")
        after = self._snapshot(root, self._DATE)
        self.assertEqual(planted.read_bytes(), planted_bytes, "the delivered file was overwritten")
        self.assertEqual(sorted(after["csv"]), sorted(before["csv"]),
                         "a replay wrote a delivery file under outputs/")
        self.assertEqual(after["csv"], before["csv"])
        self.assertEqual(after["manifest"], before["manifest"],
                         "a replay recorded or superseded a manifest row")
        self.assertEqual(after["records"], before["records"],
                         "a replay wrote a tracked delivery record")
        # The presented file is the immutable run export, and it says it is a replay.
        file_lines = [ln for ln in err.splitlines() if ln.startswith("FILE  ")]
        self.assertTrue(file_lines, err[-800:])
        for line in file_lines:
            self.assertIn("REPLAY", line)
            self.assertNotIn("outputs", line.split("sha256=")[0])
        brief = json.loads(out[out.rfind("\n{") + 1:] if "\n{" in out else out[out.find("{"):])
        self.assertEqual(Path(brief["delivered_path"]), finals[-1])
        self.assertTrue(brief.get("replay"))

    def test_the_two_mirrors_do_nothing_for_a_replay_result_and_say_so(self):
        """`mirror_to_outputs` and `mirror_review_grade` are the only writers of a
        Classic delivery; a replay result gets neither, under a key of its own
        (`mirror_skipped` would read as a later failure, exit 7)."""
        root = self.base / "mirrors"
        root.mkdir()
        run_export = root / "runs" / "r1" / "final" / "DKEntries.csv"
        run_export.parent.mkdir(parents=True)
        shutil.copyfile(self.entries, run_export)
        from mlb_engine.entries import upload_manifest as um
        with unittest.mock.patch.object(um, "REPO_ROOT", root):
            certified = {"passed": True, "output_path": str(run_export), "run_id": "r1",
                         "replay": True}
            self.assertIsNone(epi.mirror_to_outputs(certified, self.salary))
            self.assertTrue(certified["replay_not_mirrored"]["why"])
            self.assertNotIn("mirror_skipped", certified)
            self.assertNotIn("manifest_recorded", certified)
            refused = {"passed": False, "run_id": "r1", "replay": True,
                       "review_grade_export": {"path": str(run_export),
                                               "failing_gates": ["portfolio_caps_passed"]}}
            self.assertIsNone(epi.mirror_review_grade(refused, self.salary))
            self.assertTrue(refused["review_grade_export"]["not_mirrored"]["why"])
            self.assertNotIn("manifest_recorded", refused["review_grade_export"])
        self.assertFalse((root / "outputs").exists(), "a mirror wrote under outputs/")

    def test_a_result_without_the_replay_flag_still_mirrors(self):
        """The negative control: the same certified result with no flag delivers."""
        root = self.base / "mirrors_live"
        root.mkdir()
        run_export = root / "runs" / "r2" / "final" / "DKEntries.csv"
        run_export.parent.mkdir(parents=True)
        shutil.copyfile(self.entries, run_export)
        from mlb_engine.entries import upload_manifest as um
        with unittest.mock.patch.object(um, "REPO_ROOT", root):
            certified = {"passed": True, "output_path": str(run_export), "run_id": "r2",
                         "certification_label": "certified"}
            delivered = epi.mirror_to_outputs(certified, self.salary)
        self.assertTrue(delivered and Path(delivered).is_file(), delivered)
        self.assertNotIn("replay_not_mirrored", certified)


class ThinBankRecoveryTests(unittest.TestCase):
    """R390. A thin sliced bank that covers every reserved row produces a file
    inside the deadline instead of exit 10, and exit 10 stays the answer while a
    re-run can still add a slice.

    Drives `run_classic` on the sliced door with only `run_slate` and the bank
    faked, so the governor's consult, the coverage check, the label and the
    brief are the production path. The bank is a `time_budget`-stopped,
    unexhausted slice with fewer candidates than twice the entries, which is
    the only shape the exit-10 branch fires on (R415 sends a capped bank to the
    solve)."""

    _SALARY = DeadlineGovernorWiringTests._SALARY
    _SLOTS = DeadlineGovernorWiringTests._SLOTS
    setUp = DeadlineGovernorWiringTests.setUp
    _legal_ids = DeadlineGovernorWiringTests._legal_ids
    _entries_csv = DeadlineGovernorWiringTests._entries_csv
    _delivered_csv = DeadlineGovernorWiringTests._delivered_csv
    _REFUSAL = DeadlineGovernorWiringTests._REFUSAL
    _run = DeadlineGovernorWiringTests._run

    def _delivered(self):
        return {"passed": True, "run_id": "r1", "workflow_valid": True,
                "selection_certified": True, "allocation_certified": True,
                "delivered_path": str(self._delivered_csv()),
                "candidate_reuse": {"cap_applied": 1, "cap_source": "engine_default"}}

    def _thin(self, minutes_out, *, lineups=3, deadline=None, governed=True,
              overrides=None, reuse_of=None, extra_args=None):
        """Run with a thin sliced bank of ``lineups`` distinct candidates."""
        import contextlib
        import mlb_engine.pipeline.execution_pipeline as epi
        from mlb_engine.optimize import bank_cache
        ids = self._legal_ids()
        bank = [{"candidate_id": f"c{i}", "player_ids": ids[:-1] + [f"x{i}"],
                 "sp_ids": [ids[0], ids[1]], "primary_stack": "", "objective": 100.0 - i}
                for i in range(lineups)]
        report = {"stop_reason": "time_budget", "job_list_exhausted": False,
                  "jobs_attempted": 12, "jobs_total": 96, "total_candidates": lineups,
                  "max_candidates": 12, "built_this_slice": lineups,
                  "time_budget_s": 5.0}
        patches = [(bank_cache, "extend_bank", lambda *a, **k: dict(report)),
                   (bank_cache.BankCache, "as_candidates",
                    lambda self_, *a, **k: [dict(c) for c in bank]),
                   (epi, "build_sleeve_jobs", lambda *a, **k: {"attempted": False}),
                   (epi, "build_consensus_limited_jobs",
                    lambda *a, **k: {"attempted": False, "reason": "test"})]
        originals = [(o, n, getattr(o, n)) for o, n, _ in patches]
        for owner, name, fake in patches:
            setattr(owner, name, fake)
        try:
            capture = {}
            args_over = {"bank_max_candidates": 12, "controls_override": {
                "classic_sleeves": False, "classic_tail_seats": False,
                **(overrides or {})}}
            if not governed:
                args_over["_governor"] = None
            args_over.update(extra_args or {})
            code, brief, calls, err = self._run(
                minutes_out, refusal=reuse_of or self._delivered(),
                args_overrides=args_over, capture=capture,
                deadline=deadline or _build_deadline(60))
        finally:
            for owner, name, original in originals:
                setattr(owner, name, original)
        return code, brief, calls, err, capture

    def _printed(self, capture):
        text = capture["out"].getvalue()
        return json.loads(text[text.index("{"):text.rindex("}") + 1])

    def test_a_coverable_thin_bank_is_delivered_inside_the_governor_window(self):
        """The acceptance: two minutes from the deliver-by, a three-lineup bank
        against two reserved rows produces a file, in one solve, labelled."""
        code, brief, calls, err, _cap = self._thin(2)
        self.assertEqual(code, 0, err[-800:])
        self.assertEqual(len(calls), 1, "the thin bank was not solved exactly once")
        self.assertEqual(self.labels, ["review_grade_bank_thin_delivered"])
        self.assertEqual(brief["label"], "review_grade_bank_thin_delivered")
        self.assertEqual(brief["status"], "bank_thin_delivered")
        self.assertNotEqual(brief["status"], "certified")
        thin = brief["thin_bank"]
        self.assertEqual(thin["triggers"], ["governor_window"])
        self.assertTrue(thin["covers"])
        self.assertEqual(thin["coverage"]["floors"][0]["floor"],
                         "distinct_lineups_per_contest")
        self.assertEqual((thin["coverage"]["floors"][0]["have"],
                          thin["coverage"]["floors"][0]["need"]), (3, 2))
        self.assertEqual(brief["thin_bank"]["candidate_reuse"]["cap_source"],
                         "engine_default")
        self.assertIn("REVIEW-GRADE", brief["label_note"])
        self.assertTrue(brief["verification"]["passed"])
        self.assertIn("DELIVERING", err)

    def test_outside_the_window_with_a_rerun_to_spend_it_still_exits_10(self):
        """Exit 10 is the bank-growth remedy and it stays the answer while a
        re-run can add a slice: sixty minutes out, twenty seconds per call."""
        code, _brief, calls, _err, cap = self._thin(60)
        self.assertEqual(code, 10)
        self.assertEqual(calls, [], "a build that asked for a re-run solved anyway")
        payload = self._printed(cap)
        self.assertEqual(payload["status"], "partial")
        self.assertTrue(payload["thin_bank"]["covers"])
        self.assertEqual(payload["thin_bank"]["triggers"], [])
        self.assertFalse(payload["thin_bank"]["deliver"])
        # The governor was consulted before the return, and it says so.
        self.assertIn("deadline", payload)
        self.assertEqual(payload["deadline"]["rungs_walked"], [])
        # R285. The partial carries the job facts the supervisor's exit-10 log
        # read from a `solve` it does not have, and the typed remedy.
        # The merged report sums the stack-size slices (each fake call says 12
        # of 96), so the ratio is the fake's and the counts are not None.
        attempted = payload["bank_exploration"]["jobs_attempted"]
        total = payload["bank_exploration"]["jobs_total"]
        self.assertTrue(attempted and total)
        self.assertEqual(attempted * 96, total * 12)
        self.assertEqual(payload["refusal_facts"]["remedy"], "grow_bank")
        self.assertEqual(payload["refusal_facts"]["class"], "badly_shaped")

    def test_a_bank_short_of_the_largest_contest_is_not_delivered_at_any_clock(self):
        """F-3 never relaxes: two rows in one contest need two distinct
        lineups, and a one-lineup bank cannot seat them however near the lock."""
        code, _brief, calls, _err, cap = self._thin(2, lineups=1)
        self.assertEqual(code, 10)
        self.assertEqual(calls, [])
        thin = self._printed(cap)["thin_bank"]
        self.assertFalse(thin["covers"])
        self.assertFalse(thin["deliver"])
        self.assertEqual(thin["triggers"], ["governor_window"])
        self.assertIn("distinct_lineups_per_contest (1 < 2)", thin["coverage"]["reason"])

    def test_no_governor_still_delivers_when_a_rerun_cannot_add_a_slice(self):
        """Session 15's rider: the Deadline is bound by the lock without any
        --deliver-by, and a re-run with less than the bank floor to spend is a
        request the clock cannot meet."""
        deadline = _build_deadline(60, external_s=3.0)
        code, brief, calls, err, _cap = self._thin(
            2, governed=False, deadline=deadline)
        self.assertEqual(code, 0, err[-800:])
        self.assertEqual(len(calls), 1)
        self.assertEqual(brief["thin_bank"]["triggers"], ["rerun_unaffordable"])
        self.assertLess(brief["thin_bank"]["rerun_spendable_s"], 5.0)
        self.assertEqual(brief["label"], "review_grade_bank_thin_delivered")
        self.assertNotIn("deadline", brief, "no governor, so no governor stamp")

    def test_a_held_sp_pair_cap_is_a_floor_the_thin_bank_must_meet(self):
        """`--never-relax max_sp_pair_repetition` reaches the coverage check: the
        bank holds one SP pair, so the cap it must keep needs more, and the
        build asks for the re-run even inside the window."""
        from mlb_engine.pipeline import deadline_governor as dg
        held = frozenset(dg.DEFAULT_NEVER_RELAX | {"max_sp_pair_repetition"})
        # Six entries against the posture's pair cap need more than the one pair
        # the bank holds (the cap is the posture's, so the count is not pinned).
        code, _brief, calls, _err, cap = self._thin(
            2, extra_args={"_never_relax": held, "entries": 6})
        self.assertEqual(code, 10)
        self.assertEqual(calls, [])
        thin = self._printed(cap)["thin_bank"]
        self.assertFalse(thin["covers"])
        self.assertRegex(thin["coverage"]["reason"],
                         r"max_sp_pair_repetition \(1 < [2-9]\)")
        # The same bank, the same clock, the cap not held: it is delivered.
        code, brief, _calls, _err, _cap = self._thin(2, extra_args={"entries": 6})
        self.assertEqual(code, 0)
        self.assertTrue(brief["thin_bank"]["covers"])

    def test_an_operator_reuse_cap_that_cannot_seat_the_entries_is_held(self):
        """The allocator holds a typed max_candidate_reuse verbatim, so the
        thin bank must reach the entry count under it: 3 lineups x cap 1 = 3
        seats 3 of 6 entries, and relaxing the operator's number is not the
        build's call."""
        code, _brief, calls, _err, cap = self._thin(
            2, overrides={"max_candidate_reuse": 1}, extra_args={"entries": 6})
        self.assertEqual(code, 10)
        self.assertEqual(calls, [])
        self.assertIn("max_candidate_reuse (3 < 6)",
                      self._printed(cap)["thin_bank"]["coverage"]["reason"])
        code, _brief, _calls, _err, _cap = self._thin(
            2, overrides={"max_candidate_reuse": 2}, extra_args={"entries": 6})
        self.assertEqual(code, 0, "3 x 2 = 6 seats every entry")

    def test_the_coverage_floors_are_arithmetic_over_what_is_held(self):
        bs = _load_build_slate_module()
        base = dict(distinct_lineups=6, largest_contest=5, n_entries=12,
                    pairs_have=2, pairs_want=4, held=(), reuse_cap=None)
        self.assertTrue(bs.thin_bank_coverage(**base)["covers"],
                        "an un-held SP-pair cap is not a floor")
        held = bs.thin_bank_coverage(**{**base, "held": ("max_sp_pair_repetition",)})
        self.assertFalse(held["covers"])
        self.assertIn("max_sp_pair_repetition (2 < 4)", held["reason"])
        typed = bs.thin_bank_coverage(**{**base, "reuse_cap": 1})
        self.assertFalse(typed["covers"], "6 x 1 < 12 entries")
        self.assertTrue(bs.thin_bank_coverage(**{**base, "reuse_cap": 2})["covers"])
        unknown = bs.thin_bank_coverage(**{**base, "distinct_lineups": None})
        self.assertFalse(unknown["covers"], "a bank that cannot be counted covers nothing")

    def test_the_decision_needs_coverage_and_a_reason_a_rerun_cannot_help(self):
        bs = _load_build_slate_module()
        covers, short = {"covers": True}, {"covers": False}
        self.assertTrue(bs.thin_bank_decision(covers, in_window=True,
                                              rerun_spendable_s=60)["deliver"])
        self.assertTrue(bs.thin_bank_decision(covers, in_window=False,
                                              rerun_spendable_s=4.9)["deliver"])
        self.assertFalse(bs.thin_bank_decision(covers, in_window=False,
                                               rerun_spendable_s=5.0)["deliver"],
                         "exactly the bank floor is enough for one more slice")
        self.assertFalse(bs.thin_bank_decision(short, in_window=True,
                                               rerun_spendable_s=0)["deliver"])

    def test_the_deadline_says_what_a_rerun_could_spend(self):
        from mlb_engine.pipeline.deadline import Deadline
        d = _build_deadline(60, reserve_s=10.0, external_s=25.0)
        self.assertAlmostEqual(d.external_remaining(), 25.0, delta=0.5)
        self.assertAlmostEqual(d.rerun_spendable(100.0), 15.0, delta=0.5,
                               msg="the lock clips the fresh window, then the reserve")
        self.assertAlmostEqual(d.rerun_spendable(12.0), 2.0, delta=0.5,
                               msg="a fresh window shorter than the lock binds")
        plain = _build_deadline(60, reserve_s=10.0)
        self.assertIsNone(plain.external_remaining())
        self.assertAlmostEqual(plain.rerun_spendable(100.0), 90.0, delta=0.1,
                               msg="--max-seconds is one call's budget, not a bound")
        self.assertEqual(_build_deadline(60, 10.0, external_s=4.0).rerun_spendable(100.0),
                         0.0)
        self.assertIsInstance(d, Deadline)


class R311BankLimitedTests(unittest.TestCase):
    """R311. An interaction refusal on a thin bank says BANK-LIMITED and points
    at the bank, and the bank-derived player-exposure ceiling is named.

    1310_9g (2026-09-15): 7 sampled SP pairs x a posture cap of 3 = 21 >= 21
    entries passed the count, so the refusal fell to "the interaction of the
    active controls is" with 144 viable pairs unsampled, and pointed at the
    exposure caps; one longer build certified with no cap moved."""

    ENTRIES = [{"entry_id": str(i), "contest_id": "c1", "contest_shape": "large_wta"}
               for i in (1, 2)]
    CONTROLS = {"max_shared_players": 3, "max_sp_pair_repetition": 2}

    @staticmethod
    def _cand(cid, roster, score, stack, sp=("p1", "p2")):
        return {"candidate_id": cid, "lineup_ids": roster, "player_ids": roster,
                "sp_ids": list(sp), "primary_stack": stack, "objective": score,
                "contest_fit_score": score}

    def _thin_bank(self):
        """Three lineups on ONE SP pair that share p1, p2 and three hitters, so
        two of them share five players against max_shared_players 3: proven
        infeasible, no counting row failing (1 pair x cap 2 = 2 >= 2 entries)."""
        shared = [f"h{i}" for i in range(3)]
        return [self._cand(cid, ["p1", "p2", *shared, *[f"{cid.lower()}{i}" for i in range(5)]],
                           100 - n, stack)
                for n, (cid, stack) in enumerate((("A", "S1"), ("B", "S1"), ("C", "S2")))]

    def _refuse(self, feasibility_inputs, bank_report):
        from mlb_engine.allocate import contest_allocator as ca
        return ca.select_and_assign_entries(
            self._thin_bank(), self.ENTRIES, dict(self.CONTROLS),
            bank_report=bank_report, feasibility_inputs=feasibility_inputs,
            interaction_probe_budget_s=5.0)

    def test_an_interaction_refusal_on_a_thin_bank_leads_with_bank_limited(self):
        out = self._refuse({"viable_sp_pairs": 50}, {"job_list_exhausted": False,
                                                     "jobs_attempted": 1, "jobs_total": 9})
        self.assertFalse(out["passed"])
        line = out["errors"][0]
        self.assertIn("the interaction of the active controls is", line,
                      "the sentence R207's pins read is kept")
        self.assertIn("BANK-LIMITED", line)
        self.assertIn("50 viable SP pairs", line)
        self.assertIn("sampled only 1", line)
        self.assertEqual(out["bank_limits"], [{
            "axis": "sp_pairs", "kind": "interaction", "sampled": 1, "viable": 50,
            "need": 2, "entries": 2}])
        self.assertNotIn("interaction_probe", out,
                         "the probe would name the cap that happens to restore a thin bank")

    def test_the_interaction_line_says_whether_bank_growth_can_help(self):
        exhausted = self._refuse({"viable_sp_pairs": 50}, {"job_list_exhausted": True})
        self.assertIn("bank growth cannot clear this", exhausted["errors"][0])
        self.assertNotIn("BANK-LIMITED", exhausted["errors"][0])
        self.assertNotIn("bank_limits", exhausted, "a finished search is not bank-limited")
        self.assertIn("interaction_probe", exhausted, "the probe still runs there")
        direct = self._refuse({"viable_sp_pairs": 50}, {
            "job_list_exhausted": None, "source": "build_diverse_candidate_bank"})
        self.assertIn("BANK-LIMITED", direct["errors"][0])
        self.assertNotIn("interaction_probe", direct,
                         "no job list to say the bank was complete, and it is thin")
        # No pair cap in play: the bank's pair count is not what is tight, so the
        # sentence is R207's and the probe still names the restoring control.
        from mlb_engine.allocate import contest_allocator as ca
        no_pair_cap = ca.select_and_assign_entries(
            self._thin_bank(), self.ENTRIES, {"max_shared_players": 3},
            bank_report={"job_list_exhausted": None,
                         "source": "build_diverse_candidate_bank"},
            feasibility_inputs={"viable_sp_pairs": 50}, interaction_probe_budget_s=5.0)
        self.assertNotIn("BANK-LIMITED", no_pair_cap["errors"][0])
        self.assertIn("interaction_probe", no_pair_cap)
        # No slate figure: nothing new is said, and the sentence is R207's.
        plain = self._refuse(None, None)
        self.assertNotIn("BANK-LIMITED", plain["errors"][0])
        self.assertNotIn("cannot clear", plain["errors"][0])
        self.assertTrue(plain["errors"][0].startswith(
            "entry-level joint MILP proven infeasible: no single control"))

    def test_the_bank_limit_is_data_with_its_own_arithmetic(self):
        from mlb_engine.allocate import contest_allocator as ca
        pairs = [("a", "b")] * 3 + [("c", "d")] * 4          # 2 distinct
        row = ca.interaction_bank_limits(pairs, {"viable_sp_pairs": 144}, 21, {}, pair_cap=3)
        self.assertEqual(row, [{"axis": "sp_pairs", "kind": "interaction", "sampled": 2,
                                "viable": 144, "need": 21, "entries": 21}])
        many = [(f"a{i}", f"b{i}") for i in range(21)]
        self.assertEqual(ca.interaction_bank_limits(many, {"viable_sp_pairs": 144}, 21, {}, pair_cap=3), [],
                         "one pair per entry is the most a cap could ask for")
        self.assertEqual(ca.interaction_bank_limits(pairs, {"viable_sp_pairs": 2}, 21, {}, pair_cap=3), [],
                         "a slate whose only viable pairs are the two the bank holds "
                         "is not bank-limited")
        self.assertEqual(len(ca.interaction_bank_limits(
            pairs, {"viable_sp_pairs": 3}, 21, {}, pair_cap=3)), 1, "one pair short of the slate is")
        self.assertEqual(ca.interaction_bank_limits(pairs, {}, 21, {}, pair_cap=3), [])
        self.assertEqual(ca.interaction_bank_limits(
            pairs, {"viable_sp_pairs": 144}, 21, {"job_list_exhausted": True},
            pair_cap=3), [])
        self.assertEqual(ca.interaction_bank_limits(
            pairs, {"viable_sp_pairs": 144}, 21, {}), [],
            "no pair cap in play: pair coverage is not what the caps are tight against")

    def test_a_player_in_every_lineup_names_the_cap_the_bank_requires(self):
        """1940_6g: a player in every candidate needs max_player_exposure_pct at
        1.0 however the other caps are set, which a hand bisection took five
        builds to find. Now it is one counting line and one typed row."""
        from mlb_engine.allocate import contest_allocator as ca
        sigs = [tuple(sorted(["star", "p1", "p2", f"x{i}", f"y{i}"])) for i in range(4)]
        limits = []
        found = ca._diagnose_binding_constraints(
            entries_count=10, stacks=["S"] * 4, sp_pairs=[("p1", "p2")] * 4,
            signatures=sigs, largest_contest_entries=4,
            controls={"max_player_exposure_pct": 0.9}, bank_limits_out=limits)
        self.assertTrue(any(f.startswith("max_player_exposure_pct: player") for f in found), found)
        self.assertTrue([f for f in found if "cannot satisfy a cap below 10/10 = 1.000" in f],
                        "the floor reads as a floor, not as a ceiling")
        self.assertFalse([f for f in found if "at most 10/10" in f])
        # With fixed rows in the solve the caps count against rows this function
        # does not see, so it makes no claim.
        limits_fixed = []
        fixed = ca._diagnose_binding_constraints(
            entries_count=10, stacks=["S"] * 4, sp_pairs=[("p1", "p2")] * 4,
            signatures=sigs, largest_contest_entries=4,
            controls={"max_player_exposure_pct": 0.9}, bank_limits_out=limits_fixed,
            fixed_rows=True)
        self.assertFalse([f for f in fixed if f.startswith("max_player_exposure_pct")])
        self.assertFalse([b for b in limits_fixed if b["kind"] == "player_floor"])
        row = [b for b in limits if b["kind"] == "player_floor"][0]
        # star, p1 and p2 are all in 4 of 4; sorted order names the first.
        self.assertEqual(row["player_id"], "p1")
        self.assertEqual((row["lineups_with_player"], row["distinct_lineups"]), (4, 4))
        self.assertEqual(row["required_cap_pct"], 1.0)
        self.assertEqual(row["cap_count"], 9)
        # A lineup without the player, and no reuse cap: nothing to say.
        with_spare = sigs + [("z1", "z2", "z3", "z4", "z5", "z6", "z7", "z8", "z9", "z0")]
        limits = []
        found = ca._diagnose_binding_constraints(
            entries_count=10, stacks=["S"] * 5, sp_pairs=[("p1", "p2")] * 5,
            signatures=with_spare, largest_contest_entries=4,
            controls={"max_player_exposure_pct": 0.9}, bank_limits_out=limits)
        self.assertFalse([f for f in found if f.startswith("max_player_exposure_pct")])
        # With a reuse cap the spare lineup seats reuse x 1 entries: 1 < 1 fails
        # for a cap needing 1 without... need is 10 - 9 = 1, capacity 1 x 1 = 1.
        limits = []
        found = ca._diagnose_binding_constraints(
            entries_count=10, stacks=["S"] * 5, sp_pairs=[("p1", "p2")] * 5,
            signatures=[s for s in with_spare], largest_contest_entries=4,
            controls={"max_player_exposure_pct": 0.8, "max_candidate_reuse": 1},
            bank_limits_out=limits)
        row = [b for b in limits if b["kind"] == "player_floor"][0]
        self.assertEqual((row["avoid_capacity"], row["required_cap_count"]), (1, 9))
        self.assertEqual(row["required_cap_pct"], 0.9)

    def test_the_typed_remedies_carry_the_lever_for_the_door(self):
        bs = _load_build_slate_module("_bs_r311")
        limits = [{"axis": "sp_pairs", "kind": "interaction", "sampled": 1, "viable": 50,
                   "need": 2, "entries": 2},
                  {"axis": "player_exposure", "kind": "player_floor", "player_id": "p1",
                   "lineups_with_player": 4, "distinct_lineups": 4, "required_cap_pct": 1.0}]
        direct = bs.typed_refusal_remedy({}, None, None, bank_limits=limits, strategy="direct")
        by_kind = {r["kind"]: r for r in direct}
        self.assertEqual(by_kind["bank_limited"]["lever"], "take_sliced_door")
        self.assertEqual(by_kind["bank_floor"]["to"], 1.0)
        self.assertEqual(by_kind["bank_floor"]["control"], "max_player_exposure_pct")
        sliced = bs.typed_refusal_remedy(
            {}, None, {"job_list_exhausted": False, "jobs_attempted": 1, "jobs_total": 9},
            bank_limits=limits, strategy="sliced_bank")
        self.assertEqual([r["kind"] for r in sliced][:2], ["grow_bank", "bank_limited"])
        self.assertEqual({r["kind"]: r for r in sliced}["bank_limited"]["lever"], "grow_bank")
        for remedy in direct + sliced:
            self.assertTrue(bs.format_typed_remedy(remedy))


class R285BankFactsTests(unittest.TestCase):
    """R285. The bank's job facts have one reader over a brief, both doors write
    them, the supervisor branches on a typed block, and a stop keeps what the
    child said."""

    def test_one_extractor_reads_every_place_a_brief_keeps_the_bank(self):
        from mlb_engine.optimize.bank_cache import bank_job_facts
        block = {"job_list_exhausted": False, "jobs_attempted": 5, "jobs_total": 50}
        self.assertEqual(bank_job_facts({"solve": {"bank": block}})["source"], "solve.bank")
        self.assertEqual(bank_job_facts({"bank_exploration": block})["source"],
                         "bank_exploration")
        self.assertEqual(bank_job_facts({"bank_diagnostics": block})["source"],
                         "bank_diagnostics")
        self.assertEqual(bank_job_facts(block)["source"], "report")
        both = bank_job_facts({"solve": {"bank": dict(block, jobs_attempted=1)},
                               "bank_exploration": block})
        self.assertEqual((both["source"], both["jobs_attempted"]), ("solve.bank", 1))
        # solve.bank is None on the direct door; the next place answers.
        self.assertEqual(bank_job_facts({"solve": {"bank": None},
                                         "bank_diagnostics": block})["source"],
                         "bank_diagnostics")
        nothing = bank_job_facts({"solve": {"bank": None}})
        self.assertEqual((nothing["source"], nothing["job_list_exhausted"]), (None, None))
        # "This door has no job list" is an answer, and not the same as absent.
        direct = bank_job_facts({"bank_exploration": {
            "job_list_exhausted": None, "jobs_attempted": None, "jobs_total": None,
            "note": "no job list on this door"}})
        self.assertEqual(direct["source"], "bank_exploration")

    def test_the_remedy_enum_is_search_effort_only(self):
        from mlb_engine.optimize.bank_cache import bank_remedy
        cap = {"job_list_exhausted": False, "bank_stop_reason": "candidate_cap"}
        self.assertEqual(bank_remedy({"job_list_exhausted": False,
                                      "bank_stop_reason": "time_budget"}), "grow_bank")
        self.assertEqual(bank_remedy(cap), "raise_bank_cap")
        self.assertEqual(bank_remedy(dict(cap, bank_cap={"at_ceiling": True})), "at_ceiling")
        self.assertEqual(bank_remedy({"job_list_exhausted": None}, door="direct",
                                     bank_limited=True), "take_sliced_door")
        self.assertEqual(bank_remedy({"job_list_exhausted": None}, door="direct"), "none")
        self.assertEqual(bank_remedy({"job_list_exhausted": True}, door="direct",
                                     bank_limited=True), "none",
                         "a finished search is not grown")

    def test_the_direct_door_block_says_it_has_no_job_list(self):
        bs = _load_build_slate_module("_bs_r285")
        direct = bs.bank_exploration_block(None, "direct")
        self.assertEqual(direct["door"], "direct")
        self.assertIsNone(direct["job_list_exhausted"])
        self.assertIn("no job list on this door", direct["note"])
        sliced = bs.bank_exploration_block(
            {"jobs_attempted": 12, "jobs_total": 96, "job_list_exhausted": False,
             "bank_stop_reason": "time_budget", "total_candidates": 3}, "sliced_bank")
        self.assertEqual((sliced["jobs_attempted"], sliced["jobs_total"],
                          sliced["job_list_exhausted"]), (12, 96, False))
        self.assertNotIn("note", sliced)

    def test_a_direct_door_refusal_writes_the_facts_the_supervisor_reads(self):
        """Through run_classic: the allocator's typed BANK-LIMITED finding on a
        direct-door refusal becomes `refusal_facts.remedy == take_sliced_door`
        with `bank_exploration` present, on the door that has no job list."""
        harness = DeadlineGovernorWiringTests
        case = types.SimpleNamespace(
            _SALARY=harness._SALARY, _SLOTS=harness._SLOTS, _REFUSAL=harness._REFUSAL)
        case.root = Path(tempfile.mkdtemp())
        self.addCleanup(shutil.rmtree, case.root, True)
        for name in ("_legal_ids", "_entries_csv", "_delivered_csv"):
            setattr(case, name, getattr(harness, name).__get__(case))
        case.fail = self.fail
        refusal = dict(harness._REFUSAL, bank_limits=[
            {"axis": "sp_pairs", "kind": "counting", "sampled": 3, "viable": 60,
             "cap": 1, "entries": 18}])
        code, brief, _calls, err = harness._run(case, 30, refusal=refusal)
        self.assertEqual(code, 3)
        self.assertIn("BANK-LIMITED on the direct door", err,
                      "the operator's line is off the typed finding, with no sentence in errors[]")
        self.assertEqual(brief["solve_strategy"], "direct")
        self.assertEqual(brief["bank_exploration"]["door"], "direct")
        self.assertIsNone(brief["bank_exploration"]["job_list_exhausted"])
        facts = brief["refusal_facts"]
        self.assertEqual(facts["remedy"], "take_sliced_door")
        self.assertTrue(facts["bank_limited"])
        self.assertEqual(facts["class"], brief["refusal_class"])
        self.assertEqual((facts["job_list_exhausted"], facts["jobs_total"]), (None, None))
        kinds = [r["kind"] for r in brief["refusal_remedy"]]
        self.assertIn("bank_limited", kinds)
        # And the same refusal without the allocator's finding names no remedy.
        code, brief, _calls, _err = harness._run(case, 30)
        self.assertEqual(brief["refusal_facts"]["remedy"], "none")
        self.assertFalse(brief["refusal_facts"]["bank_limited"])


    def test_run_slate_returns_the_allocators_bank_limits(self):
        """The wiring, through the real run_slate and execute_portfolio: only
        the allocator is faked. The typed findings ride the refusal result, the
        same way the interaction probe does, so build_slate can type them."""
        rows = [{"axis": "sp_pairs", "kind": "interaction", "sampled": 1, "viable": 50,
                 "need": 2, "entries": 2}]

        def fake(candidates, entries, controls, **kw):
            return {"passed": False, "assignments": [], "errors": ["refused"],
                    "selection_certified": False, "allocation_certified": False,
                    "bank_limits": rows}
        with tempfile.TemporaryDirectory() as tmp:
            root = Path(tmp)
            salary = root / "salary.csv"; ids = write_salary(salary)
            entries = root / "DKEntries.csv"; write_entries(entries)
            r1, r2 = legal_rosters(ids)
            with unittest.mock.patch.object(epi, "select_and_assign_entries", fake):
                out = run_slate(
                    runs_root=root / "runs", salary_csv=salary, entries_csv=entries,
                    projections_override=projection_frame(ids),
                    candidates_override=[candidate("A", r1, 100), candidate("B", r2, 99, "CCC")],
                    portfolio_controls_override=RunSlateFrontDoorTests.LOOSE,
                    assume_gates=RunSlateFrontDoorTests.UNEVIDENCED,
                    approve=True)
        self.assertFalse(out["passed"])
        self.assertEqual(out["bank_limits"], rows)


class R285SupervisorTests(unittest.TestCase):
    """R285 on the supervisor: it branches on the typed block through the one
    extractor, and every stop keeps the child's returncode, stdout, stderr and
    parsed brief beside the decision log."""

    setUp = AutobuildBankCapTests.setUp
    _run = AutobuildBankCapTests._run

    @staticmethod
    def _child(returncode, brief, stderr=""):
        return lambda n, cmd, kw: types.SimpleNamespace(
            returncode=returncode, stderr=stderr,
            stdout="noise before\n" + json.dumps(brief) + "\nnoise after")

    def _child_files(self):
        return sorted(Path(self.tmp.name).glob("outputs/*/autobuild_child_*.json"))

    def test_a_stop_keeps_what_the_child_said(self):
        brief = {"status": "not_certified", "date": "2026-07-29",
                 "errors": ["entry-level joint MILP proven infeasible: x"]}
        code, records, _cmds, _ = self._run(
            self._child(3, brief, stderr="the child's own stderr"),
            extra_argv=["--max-attempts", "1"])
        self.assertEqual(code, 3)
        stop = [r for r in records if r["action"] == "stop"][-1]
        self.assertEqual(stop["returncode"], 3)
        files = self._child_files()
        self.assertEqual([f.name for f in files], ["autobuild_child_1.json"])
        self.assertTrue(stop["child_record"].endswith("autobuild_child_1.json"))
        kept = json.loads(files[0].read_text(encoding="utf-8"))
        self.assertEqual(kept["returncode"], 3)
        self.assertEqual(kept["stderr"], "the child's own stderr")
        self.assertIn("noise before", kept["stdout"])
        self.assertEqual(kept["brief"]["status"], "not_certified")
        self.assertFalse(kept["killed"])

    def test_the_child_record_never_holds_a_key(self):
        secret = "ghp_S3cretValue0123456789"
        # The secret rides stderr AND the parsed brief (an error string a child
        # echoed), so redacting the raw streams alone would still write it.
        brief = {"status": "not_certified", "date": "2026-07-29",
                 "errors": [f"fetch failed with {secret}"]}
        with unittest.mock.patch.dict(os.environ, {"GH_PAT": secret}):
            self._run(self._child(3, brief, stderr=f"auth failed for {secret}"),
                      extra_argv=["--max-attempts", "1"])
        text = self._child_files()[0].read_text(encoding="utf-8")
        self.assertNotIn(secret, text)
        self.assertIn("<GH_PAT redacted>", text)
        kept = json.loads(text)
        self.assertIn("<GH_PAT redacted>", kept["brief"]["errors"][0])

    def test_the_exit_10_log_reads_the_partial_briefs_facts(self):
        partial = {"status": "partial", "date": "2026-07-29",
                   "bank_exploration": {"job_list_exhausted": False, "jobs_attempted": 12,
                                        "jobs_total": 96, "bank_stop_reason": "time_budget"}}
        _code, records, _cmds, _ = self._run(
            self._child(10, partial), extra_argv=["--max-attempts", "1"])
        grow = [r for r in records if r["action"] == "grow_bank"][0]
        self.assertEqual((grow["jobs"], grow["jobs_total"], grow["bank_stop_reason"]),
                         (12, 96, "time_budget"))

    def test_a_refusal_that_keeps_its_bank_under_bank_diagnostics_still_grows(self):
        refusal = {"status": "not_certified", "date": "2026-07-29",
                   "bank_diagnostics": {"job_list_exhausted": False, "jobs_attempted": 5,
                                        "jobs_total": 50, "bank_stop_reason": "time_budget"}}
        _code, records, cmds, _ = self._run(
            self._child(3, refusal), extra_argv=["--max-attempts", "2"])
        self.assertIn("grow_bank", [r["action"] for r in records])
        self.assertEqual(len(cmds), 2)

    def test_the_typed_block_is_what_the_supervisor_branches_on(self):
        """No bank facts anywhere on the brief, and a typed `grow_bank`: the
        remedy is taken from the block. And the reverse: bank facts that say
        `grow_bank` under a block that says `none` are not overruled by errors."""
        typed = {"status": "not_certified", "date": "2026-07-29",
                 "refusal_facts": {"remedy": "grow_bank"}}
        _c, records, cmds, _ = self._run(
            self._child(3, typed), extra_argv=["--max-attempts", "2"])
        self.assertIn("grow_bank", [r["action"] for r in records])
        self.assertEqual(len(cmds), 2)
        none = {"status": "not_certified", "date": "2026-07-29",
                "refusal_facts": {"remedy": "none"},
                "bank_exploration": {"job_list_exhausted": False, "jobs_attempted": 5,
                                     "jobs_total": 50, "bank_stop_reason": "time_budget"}}
        _c, records, cmds, _ = self._run(
            self._child(3, none), extra_argv=["--max-attempts", "2"])
        self.assertNotIn("grow_bank", [r["action"] for r in records])
        self.assertEqual(len(cmds), 1)


class LateSwapPreflightTests(unittest.TestCase):
    """R174 + R404(a). The locked-team introduction ban holds AFTER export, and a
    swap does not claim success before its referee has spoken.

    Before this: the ban lived only in the allocator's candidate filter
    (`_entry_candidate_compatible`), `validate_late_swap_delta` checked entry-level
    authorization only, and `late_swap.py` wrote, recorded and promoted the file,
    PRINTED the preflight command and returned 0. And a swap with no
    `lineups_feed.json` on disk exited 4 before reading the salary file, though DK's
    own `Starting` column covered every side (R143 ranks it above any feed).
    """

    LATE = "2026-07-25T19:45:00-04:00"   # every fixture game has started

    def setUp(self):
        from tests.test_upload_integrity import (
            CLASSIC_HEADER, classic_entry, write_three_game_salary,
            write_entries as write_rows)
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.salary = self.root / "DKSalaries.csv"
        self.ids = write_three_game_salary(self.salary)
        self.parent_lineup = [
            self.ids["AAA Aster"], self.ids["CCC Aster"],
            self.ids["AAA Boone"], self.ids["AAA Crane"], self.ids["AAA Dunne"],
            self.ids["AAA Ellis"], self.ids["AAA Frost"],
            self.ids["EEE Gable"], self.ids["EEE Hollis"], self.ids["EEE Ives"]]
        self._rows = (CLASSIC_HEADER, classic_entry, write_rows)
        self.parent = self.root / "parent.csv"
        write_rows(self.parent, CLASSIC_HEADER,
                   [classic_entry("900", "5", self.parent_lineup)])
        swapped = list(self.parent_lineup)
        swapped[9] = self.ids["FFF Ives"]
        self.child = self.root / "child.csv"
        write_rows(self.child, CLASSIC_HEADER, [classic_entry("900", "5", swapped)])
        self.team_of = {}
        with self.salary.open(encoding="utf-8-sig", newline="") as fh:
            for row in csv.DictReader(fh):
                self.team_of[row["ID"]] = row["TeamAbbrev"]
        self.all_teams = sorted(set(self.team_of.values()))

    # -- R174: the delta re-derives the ban from the file ---------------------- #

    def test_an_introduced_player_from_a_started_game_is_refused_post_export(self):
        from mlb_engine.swap.late_swap_manager import validate_late_swap_delta
        out = validate_late_swap_delta(
            self.parent, self.child, mutable_entry_ids=["900"],
            excluded_new_teams=self.all_teams, player_team_by_id=self.team_of)
        self.assertFalse(out["passed"])
        self.assertTrue(any("already-started game" in e and self.ids["FFF Ives"] in e
                            for e in out["errors"]), out["errors"])
        self.assertEqual(out["introduced_from_locked_teams"],
                         [{"entry_id": "900", "player_id": self.ids["FFF Ives"],
                           "team": "FFF"}])

    def test_the_same_swap_passes_when_that_players_game_is_open(self):
        from mlb_engine.swap.late_swap_manager import validate_late_swap_delta
        out = validate_late_swap_delta(
            self.parent, self.child, mutable_entry_ids=["900"],
            excluded_new_teams=["AAA", "BBB", "CCC", "DDD"],
            player_team_by_id=self.team_of)
        self.assertTrue(out["passed"], out["errors"])
        self.assertEqual(out["introduced_from_locked_teams"], [])

    def test_a_player_who_only_moved_slots_is_not_an_introduction(self):
        from mlb_engine.swap.late_swap_manager import validate_late_swap_delta
        header, classic_entry, write_rows = self._rows
        moved = list(self.parent_lineup)
        moved[7], moved[8] = moved[8], moved[7]      # two EEE outfielders trade slots
        path = self.root / "moved.csv"
        write_rows(path, header, [classic_entry("900", "5", moved)])
        out = validate_late_swap_delta(
            self.parent, path, mutable_entry_ids=["900"],
            excluded_new_teams=self.all_teams, player_team_by_id=self.team_of)
        self.assertTrue(out["passed"], out["errors"])
        self.assertEqual(out["changed_entry_ids"], ["900"])

    def test_an_introduced_player_with_no_team_fails_closed(self):
        from mlb_engine.swap.late_swap_manager import validate_late_swap_delta
        team_of = {k: v for k, v in self.team_of.items() if k != self.ids["FFF Ives"]}
        out = validate_late_swap_delta(
            self.parent, self.child, mutable_entry_ids=["900"],
            excluded_new_teams=["AAA"], player_team_by_id=team_of)
        self.assertFalse(out["passed"])
        self.assertTrue(any("no team in the lock map" in e for e in out["errors"]))

    def test_no_ban_expressed_means_no_team_check(self):
        """The two new inputs are optional: every existing caller passes neither,
        and None must stay 'the caller expressed no ban', as `mutable_entry_ids`
        does."""
        from mlb_engine.swap.late_swap_manager import validate_late_swap_delta
        out = validate_late_swap_delta(self.parent, self.child,
                                       mutable_entry_ids=["900"])
        self.assertTrue(out["passed"])
        self.assertEqual(out["excluded_new_teams_checked"], [])

    def test_the_pipeline_helper_takes_teams_from_the_salary_file_not_the_feed(self):
        """The wiring `execute_portfolio` uses: the union of the requirements'
        `excluded_new_teams`, and a team map read off the SALARY file, so a feed
        that mislabels a player's team (R325) cannot also hide him from the ban."""
        reqs = [{"entry_id": "900", "excluded_new_teams": ["FFF"],
                 "player_team_by_id": {self.ids["FFF Ives"]: "EEE"}}]   # the mislabel
        out = epi._late_swap_delta_with_lock_ban(
            self.parent, self.child, ["900"], reqs, self.salary)
        self.assertFalse(out["passed"], out)
        self.assertEqual(out["introduced_from_locked_teams"][0]["team"], "FFF")
        clean = epi._late_swap_delta_with_lock_ban(
            self.parent, self.child, ["900"],
            [{"entry_id": "900", "excluded_new_teams": ["AAA"]}], self.salary)
        self.assertTrue(clean["passed"], clean)
        self.assertEqual(epi._salary_team_by_player_id(self.salary), self.team_of)

    def test_the_salary_team_map_spells_teams_as_the_ban_does(self):
        """The ban's teams come from the status map, which normalizes with
        `to_dk_abbrev`; the map they are checked against must too, or a salary
        team spelled `AZ` never matches a banned `ARI` and the check fails open."""
        with self.salary.open(encoding="utf-8-sig", newline="") as fh:
            rows = list(csv.reader(fh))
        team_col = rows[0].index("TeamAbbrev")
        for row in rows[1:]:
            if row[team_col] == "AAA":
                row[team_col] = "AZ"
        with self.salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        team_of = epi._salary_team_by_player_id(self.salary)
        self.assertEqual(team_of[self.ids["AAA Aster"]], "ARI")

    def test_execute_portfolio_calls_that_helper_on_the_late_swap_branch(self):
        src = inspect.getsource(epi.execute_portfolio)
        branch = src[src.index('if mode == "late_swap":\n            # R174'):]
        branch = branch[:branch.index("else:")]
        self.assertIn("_late_swap_delta_with_lock_ban(", branch)

    # -- R174 rider: the swap runs the referee on its own bytes ----------------- #

    @staticmethod
    def _tool():
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "late_swap_r174", REPO / "tools" / "late_swap.py")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    class _Args:
        pass

    def _deliver(self, out_path, as_of, downgraded=None):
        from mlb_engine.entries import upload_manifest as um
        ls = self._tool()
        ls._build_slate_module()
        ls.REPO = self.root
        um_root = um.REPO_ROOT
        um.REPO_ROOT = self.root
        self.addCleanup(setattr, um, "REPO_ROOT", um_root)
        args = self._Args()
        args.date = "2026-07-25"
        args.parent_entries = str(self.parent)
        args.preflight_as_of = as_of
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = ls.deliver_swap(
                args, {"workflow_valid": True, "selection_certified": True,
                       "allocation_certified": True, "run_id": "RUN_SWAP",
                       "promoted": True},
                out_path, self.salary, None, {"5": "large_gpp"},
                {"900": []}, downgraded or [], {})
        return ls, code, out.getvalue(), err.getvalue()

    def test_a_clean_swap_reports_the_referee_verdict_before_it_claims_success(self):
        _header, classic_entry, write_rows = self._rows
        same = self.root / "same.csv"
        write_rows(same, self._rows[0], [classic_entry("900", "5", self.parent_lineup)])
        ls, code, out, err = self._deliver(same, self.LATE)
        self.assertEqual(code, 0, out + err)
        self.assertIn("referee: preflight_upload exit 0", out)
        self.assertLess(out.index("referee: preflight_upload exit 0"),
                        out.index("Upload by hand"))

    def test_a_swap_that_introduces_a_started_player_does_not_exit_0(self):
        """The rider's case, end to end: the swapped file rosters an FFF outfielder
        whose game started. Before, the tool wrote it, printed a command, exited 0."""
        ls, code, out, err = self._deliver(self.child, self.LATE)
        self.assertEqual(code, ls.POST_SWAP_REFEREE_FAILED, out + err)
        self.assertIn("REFEREE FAILED: preflight_upload exit 2", err)
        self.assertIn("FFF Ives", err)
        self.assertNotIn("Upload by hand", out)
        bs = ls._build_slate_module()
        self.assertEqual(bs._LAST_USABLE["referee"]["exit"], 2)
        self.assertTrue(Path(bs._LAST_USABLE["path"]).exists(),
                        "the file stays on disk: the referee reports, it does not delete")

    def test_exit_0_from_the_referee_is_not_called_upload_ready_on_a_review_grade_file(self):
        """Preflight exits 0 for `review_ready` as well as `upload_ready`. A swap
        that took a downgrade is labelled review-grade (R386), and the swap must
        say so rather than print the word CLAUDE.md reserves for a certified
        Classic export."""
        _header, classic_entry, write_rows = self._rows
        same = self.root / "same_dg.csv"
        write_rows(same, self._rows[0], [classic_entry("900", "5", self.parent_lineup)])
        ls, code, out, err = self._deliver(same, self.LATE,
                                           downgraded=[{"entry_id": "900"}])
        self.assertEqual(code, 0, out + err)
        self.assertIn("verdict review_ready", out)
        self.assertIn("NOT upload-ready", out)
        self.assertNotIn("verdict upload_ready", out)

    def test_a_clean_certified_swap_reports_verdict_upload_ready(self):
        _header, classic_entry, write_rows = self._rows
        same = self.root / "same_ok.csv"
        write_rows(same, self._rows[0], [classic_entry("900", "5", self.parent_lineup)])
        ls, code, out, err = self._deliver(same, self.LATE)
        self.assertIn("verdict upload_ready", out)
        self.assertNotIn("NOT upload-ready", out)

    def test_a_referee_that_exits_3_has_its_reason_printed_not_swallowed(self):
        _header, classic_entry, write_rows = self._rows
        same = self.root / "same3.csv"
        write_rows(same, self._rows[0], [classic_entry("900", "5", self.parent_lineup)])
        import preflight_upload

        def _refuse(argv):
            print("ERROR the salary file could not be parsed", file=sys.stderr)
            return 3
        with unittest.mock.patch.object(preflight_upload, "main", _refuse):
            ls, code, out, err = self._deliver(same, self.LATE)
        self.assertEqual(code, ls.POST_SWAP_REFEREE_FAILED)
        self.assertIn("preflight_upload exit 3", err)
        self.assertIn("preflight said: ERROR the salary file could not be parsed", err)

    def test_a_referee_that_cannot_run_is_not_a_pass(self):
        _header, classic_entry, write_rows = self._rows
        same = self.root / "same2.csv"
        write_rows(same, self._rows[0], [classic_entry("900", "5", self.parent_lineup)])
        import preflight_upload
        with unittest.mock.patch.object(
                preflight_upload, "main", side_effect=RuntimeError("boom")):
            ls, code, out, err = self._deliver(same, self.LATE)
        self.assertEqual(code, ls.POST_SWAP_REFEREE_FAILED)
        self.assertIn("REFEREE DID NOT RUN", err)
        self.assertIn("boom", err)

    def test_the_referee_is_called_with_the_arguments_claude_md_names(self):
        ls = self._tool()
        result = ls.run_post_swap_preflight(
            self.child, self.parent, self.salary, "abcdef1234567890",
            feed_path=self.root / "no_such_feed.json", as_of=self.LATE)
        argv = result["argv"]
        for flag in ("--entries", "--salary", "--parent", "--expect-sha256"):
            self.assertIn(flag, argv)
        self.assertEqual(argv[argv.index("--expect-sha256") + 1], "abcdef123456")
        self.assertNotIn("--feed", argv, "a feed that is not on disk is not passed")
        self.assertIn("--as-of", argv)

    def test_the_default_clock_is_the_wall_clock_and_none_is_forwarded(self):
        ls = self._tool()
        seen = {}
        import preflight_upload
        real = preflight_upload.main
        def spy(argv):
            seen["argv"] = list(argv)
            return real(argv)
        with unittest.mock.patch.object(preflight_upload, "main", spy):
            ls.run_post_swap_preflight(self.child, self.parent, self.salary, "0" * 12)
        self.assertNotIn("--as-of", seen["argv"])

    def test_a_failed_referee_writes_a_refusal_record_carrying_the_file(self):
        """`_main_recording_refusals` recorded the artifact for exit 7 only; exit 5
        also has a file in hand, and the record is where a later reader finds it."""
        ls = self._tool()
        ls._build_slate_module()
        captured = {}
        ls.main = lambda: self._deliver_for(ls)
        with unittest.mock.patch(
                "mlb_engine.entries.delivery_record.write_refusal_record",
                lambda **kw: captured.update(kw)):
            with contextlib.redirect_stdout(io.StringIO()), \
                 contextlib.redirect_stderr(io.StringIO()):
                code = ls._main_recording_refusals()
        self.assertEqual(code, ls.POST_SWAP_REFEREE_FAILED)
        artifact = captured["refusal"]["last_usable_artifact"]
        self.assertEqual(artifact["referee"]["exit"], 2)
        self.assertTrue(Path(artifact["path"]).exists())

    def _deliver_for(self, ls):
        from mlb_engine.entries import upload_manifest as um
        ls.REPO = self.root
        um_root = um.REPO_ROOT
        um.REPO_ROOT = self.root
        self.addCleanup(setattr, um, "REPO_ROOT", um_root)
        args = self._Args()
        args.date, args.parent_entries = "2026-07-25", str(self.parent)
        args.preflight_as_of = self.LATE
        return ls.deliver_swap(
            args, {"workflow_valid": True, "selection_certified": True,
                   "allocation_certified": True, "run_id": "RUN_SWAP",
                   "promoted": True},
            self.child, self.salary, None, {"5": "large_gpp"}, {"900": []}, [], {})

    # -- R404(a): no feed file, DK's Starting column covers every side ---------- #

    def _run_main(self, argv, stop_at_status=True):
        ls = self._tool()
        seen = {}

        class _Stop(Exception):
            pass

        def _capture(feed, salary, *a, **k):
            seen["feed"] = feed
            raise _Stop()
        if stop_at_status:
            ls.build_status_map_from_lineups_feed = _capture
        out, err = io.StringIO(), io.StringIO()
        old = sys.argv
        sys.argv = ["late_swap.py", "--date", "2099-01-01", "--dry-run",
                    "--postures", "5=large_gpp", *argv]
        try:
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                try:
                    code = ls.main()
                except _Stop:
                    code = "reached the status map"
        finally:
            sys.argv = old
        return code, seen.get("feed"), out.getvalue(), err.getvalue()

    def test_full_dk_coverage_replaces_a_missing_feed_file(self):
        code, feed, out, err = self._run_main(
            ["--salary", str(self.salary), "--parent-entries", str(self.parent)])
        self.assertEqual(code, "reached the status map", out + err)
        self.assertIn("DK's Starting column covers all 6 side(s)", out)
        self.assertIn("minutes ago", out)      # the salary file's age, stated
        self.assertNotIn("feed: ", err,
                         "the age warnings describe a disk feed; this one was built just now")
        self.assertEqual(len(feed["games"]), 3)
        for game in feed["games"]:
            self.assertTrue(game["game_date_utc"])
            for side in ("away", "home"):
                self.assertEqual(game[side]["lineup_status"], "confirmed")
                self.assertEqual(len(game[side]["lineup"]), 9)

    def test_the_synthesized_feed_gives_every_player_a_lock_time(self):
        """The reason this is not `build_slate`'s `{"games": []}`: the status map
        reads the feed raw, and a status map with no games fails every slot
        closed."""
        from mlb_engine.intake.live_data_adapters import (
            build_status_map_from_lineups_feed, dk_starting_only_feed)
        feed, note = dk_starting_only_feed(self.salary, "2026-07-25")
        self.assertIsNotNone(feed, note)
        status = build_status_map_from_lineups_feed(feed, str(self.salary))
        self.assertEqual(status["uncovered_salary_player_ids"], [])
        self.assertEqual(sorted(status["lock_time_by_game_id"]),
                         ["AAA@BBB", "CCC@DDD", "EEE@FFF"])
        self.assertEqual(len(status["confirmed_hitter_ids"]), 54)

    def test_one_uncovered_side_is_still_a_refusal_and_is_named(self):
        with self.salary.open(encoding="utf-8-sig", newline="") as fh:
            rows = list(csv.reader(fh))
        team_col, start_col = rows[0].index("TeamAbbrev"), rows[0].index("Starting")
        for row in rows[1:]:
            if row[team_col] == "FFF":
                row[start_col] = ""
        with self.salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        code, feed, out, err = self._run_main(
            ["--salary", str(self.salary), "--parent-entries", str(self.parent)])
        self.assertEqual(code, 4, out + err)
        self.assertIsNone(feed)
        self.assertIn("missing input", err)
        self.assertIn("FFF", err)

    def test_an_explicit_lineups_path_that_does_not_exist_is_still_a_refusal(self):
        code, feed, out, err = self._run_main(
            ["--salary", str(self.salary), "--parent-entries", str(self.parent),
             "--lineups", str(self.root / "typo.json")])
        self.assertEqual(code, 4, out + err)
        self.assertIn("typo.json", err)
        self.assertNotIn("DK's Starting", out)

    def test_an_explicit_feed_outranks_the_synthesized_one(self):
        from tests.test_upload_integrity import write_three_game_feed
        feed_path = write_three_game_feed(self.root / "explicit.json")
        code, feed, out, err = self._run_main(
            ["--salary", str(self.salary), "--parent-entries", str(self.parent),
             "--lineups", str(feed_path)])
        self.assertEqual(code, 3, out + err)     # its date is 2026-07-25, not 2099-01-01
        self.assertIn("lineups feed is for 2026-07-25", err)
        self.assertNotIn("DK's Starting column covers", out)


class RepairDkStartingTests(unittest.TestCase):
    """R404(b). `repair_entry` with no `--feed` printed "no team treated as locked",
    confirmed nobody, and returned no legal replacement for all five benched slots
    on 1905_10g, one minute after TB@NYY started, though DK's `Starting` column
    covered every side. Locks now come from `resolve_locked_teams` (the salary clock
    always, the feed's when there is one) and confirmation from DK's posted orders
    when they cover every side.
    """

    NOW = "2026-07-25T19:20:00-04:00"    # AAA@BBB and CCC@DDD started, EEE@FFF open

    def setUp(self):
        from tests.test_upload_integrity import (
            CLASSIC_HEADER, classic_entry, write_three_game_salary,
            write_entries as write_rows)
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.dir = Path(self.tmp.name)
        self.salary = self.dir / "DKSalaries.csv"
        self.ids = write_three_game_salary(self.salary)
        self.entries = self.dir / "DKEntries.csv"
        lineup = [self.ids["AAA Aster"], self.ids["CCC Aster"],
                  self.ids["AAA Boone"], self.ids["AAA Crane"], self.ids["AAA Dunne"],
                  self.ids["AAA Ellis"], self.ids["AAA Frost"],
                  self.ids["EEE Gable"], self.ids["EEE Hollis"], self.ids["EEE Ives"]]
        write_rows(self.entries, CLASSIC_HEADER, [classic_entry("900", "5", lineup)])
        # A started-game outfielder who would win on projection if locks were blind.
        self._set_points("AAA Jarrow", "99.0")

    def _set_points(self, name, points):
        with self.salary.open(encoding="utf-8-sig", newline="") as fh:
            rows = list(csv.reader(fh))
        name_col, pts_col = rows[0].index("Name"), rows[0].index("AvgPointsPerGame")
        for row in rows[1:]:
            if row[name_col] == name:
                row[pts_col] = points
        with self.salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)

    def _repair(self, *extra):
        sys.path.insert(0, str(REPO / "tools"))
        import repair_entry
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = repair_entry.main(
                ["--entries", str(self.entries), "--salary", str(self.salary),
                 "--as-of", self.NOW, "--mode", "repair", "--dry-run", "--json",
                 *extra])
        return code, json.loads(out.getvalue()), err.getvalue()

    def test_with_no_feed_the_salary_clock_still_locks_started_games(self):
        code, result, _err = self._repair("--dead", self.ids["EEE Ives"])
        self.assertEqual(result["locked_teams"], ["AAA", "BBB", "CCC", "DDD"])
        self.assertEqual(result["lock_source"], "salary Game Info")
        self.assertNotIn("no team treated as locked", result["lock_note"])

    def test_with_no_feed_dk_starting_confirms_and_a_legal_replacement_is_found(self):
        """The 1905_10g case. Before: exit 2, every candidate `not_confirmed`."""
        code, result, err = self._repair("--dead", self.ids["EEE Ives"])
        self.assertEqual(code, 4, result)        # 4 = clean and unwritten (--dry-run)
        self.assertEqual(result["confirmation_source"], "dk_starting")
        self.assertEqual(len(result["repairs"]), 1)
        repair = result["repairs"][0]
        # Never the started-game outfielder the projection prefers.
        self.assertNotIn(repair["in_name"].split()[0], ("AAA", "BBB", "CCC", "DDD"))
        self.assertTrue(repair["in_name"].startswith(("EEE ", "FFF ")), repair)
        census = result["refusals"] or []
        self.assertEqual(census, [])
        self.assertIn("confirmation from DK's Starting column", err)

    def test_a_started_games_player_is_counted_team_locked_not_offered(self):
        """Take the open-game outfielders out of contention so the census shows
        where the started-game candidate went."""
        for name in ("EEE Jarrow", "FFF Gable", "FFF Hollis", "FFF Ives", "FFF Jarrow"):
            self._set_salary(name, 20000)      # over the entry's cap headroom
        code, result, _err = self._repair("--dead", self.ids["EEE Ives"])
        self.assertEqual(code, 2, result)
        census = result["refusals"][0]["rejection_census"]
        self.assertGreater(census["team_locked"], 0, census)

    def _set_salary(self, name, salary):
        with self.salary.open(encoding="utf-8-sig", newline="") as fh:
            rows = list(csv.reader(fh))
        name_col, sal_col = rows[0].index("Name"), rows[0].index("Salary")
        for row in rows[1:]:
            if row[name_col] == name:
                row[sal_col] = str(salary)
        with self.salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)

    def test_partial_dk_coverage_confirms_nobody_and_says_which_side(self):
        with self.salary.open(encoding="utf-8-sig", newline="") as fh:
            rows = list(csv.reader(fh))
        team_col, start_col = rows[0].index("TeamAbbrev"), rows[0].index("Starting")
        for row in rows[1:]:
            if row[team_col] == "FFF":
                row[start_col] = ""
        with self.salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        code, result, err = self._repair("--dead", self.ids["EEE Ives"])
        self.assertEqual(code, 2, result)
        self.assertEqual(result["confirmation_source"], "none")
        self.assertIn("FFF", err)
        self.assertEqual(result["locked_teams"], ["AAA", "BBB", "CCC", "DDD"])

    def test_an_explicit_feed_is_the_confirmation_source_and_dk_is_not_consulted(self):
        from tests.test_upload_integrity import write_three_game_feed
        feed = write_three_game_feed(self.dir / "lineups_feed.json")
        code, result, err = self._repair("--dead", self.ids["EEE Ives"],
                                         "--feed", str(feed))
        self.assertEqual(result["confirmation_source"], "feed lineups_feed.json")
        self.assertNotIn("DK's Starting column", err)

    def test_dead_from_feed_reads_dk_starting_when_it_covers_every_side(self):
        """A scratched bat: DK's posted nine for EEE swaps Ives out for a bench
        bat, and with no feed on disk the repair still finds him dead."""
        with self.salary.open(encoding="utf-8-sig", newline="") as fh:
            rows = list(csv.reader(fh))
        name_col, start_col = rows[0].index("Name"), rows[0].index("Starting")
        ives_slot = 0
        for row in rows[1:]:
            if row[name_col] == "EEE Ives":
                ives_slot, row[start_col] = row[start_col], ""
        template = next(r for r in rows[1:] if r[name_col] == "EEE Jarrow")
        bench = list(template)
        bench[rows[0].index("ID")] = "7777"
        bench[name_col] = "EEE Bench"
        bench[rows[0].index("Name + ID")] = "EEE Bench (7777)"
        bench[start_col] = str(ives_slot)
        rows.append(bench)
        with self.salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        from mlb_engine.intake.live_data_adapters import dk_order_coverage
        covered, not_covered = dk_order_coverage(self.salary)
        self.assertEqual(not_covered, [], "fixture must keep DK's coverage complete")
        code, result, err = self._repair("--dead-from-feed")
        self.assertEqual([d["name"] for d in result["dead_derived_from_feed"]],
                         ["EEE Ives"], (result, err))
        self.assertEqual(result["confirmation_source"], "dk_starting")


class LateSwapDeclaredPitcherTests(unittest.TestCase):
    """R468 (roadmap Session 137). A late swap carries the declared pitchers
    of the build it refines.

    `late_swap.py` built its pool with no `declared_pitchers`, and the pool
    holds feed probables plus declared arms and nothing else, so a PLR or
    bulk arm the build declared was absent from the swap's frame. An entry
    holding him in a locked slot got `+0 targeted candidates` and the
    allocator refused `no compatible candidate`, which fails the whole swap:
    on 2026-09-29 (1400_4g) every 16:03 ET swap exited 3 on Painter, and the
    later windows ran by hand. The parent's declarations live in its build
    brief (R268(a) reads `runs/<id>/`, which records none), found by identity
    the way `retro.resolve_brief` finds any delivery's brief.

    The fixture is that slate's shape at test scale: four teams, T1@T2
    started (23:05Z) and T3@T4 not (01:05Z), a parent whose rosters include
    T1 Pen1 declared `viable_bulk_or_alt_sp`, and the clock between the two.
    """

    DATE = "2026-07-10"
    NOW = datetime(2026, 7, 10, 23, 30, tzinfo=timezone.utc)

    @staticmethod
    def _tool():
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "late_swap_r468", REPO / "tools" / "late_swap.py")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        slate = self.root / "data" / "slates" / self.DATE
        slate.mkdir(parents=True)
        self.salary = slate / "DKSalaries.csv"
        pool_salary_csv(self.salary)
        with self.salary.open(newline="", encoding="utf-8") as fh:
            rows = list(csv.reader(fh))
        for row in rows[1:]:
            if row[8] in ("T3", "T4"):
                row[6] = row[6].replace("07:05PM", "09:05PM")
        with self.salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        feed = pool_lineups_feed(t4_confirmed=True)
        feed["games"][1]["game_date_utc"] = "2026-07-11T01:05:00Z"
        feed["fetched_at"] = "2026-07-10T23:20:00Z"
        (slate / "lineups_feed.json").write_text(json.dumps(feed), encoding="utf-8")
        ids = {row[2]: row[3] for row in rows[1:]}
        self.pen = ids["T1 Pen1"]
        self.declared = {self.pen: "viable_bulk_or_alt_sp"}
        pool = lda.build_slate_pool(str(self.salary), feed,
                                    declared_pitchers=self.declared)
        frame, _ = epi._assemble_projection_frame(
            str(self.salary), pool["run_slate_kwargs"]["projection_rows"],
            "emergency_proxy", None, None, None)
        hitter = lambda team, i: ids[f"{team} Hitter{i}"]
        # P P C 1B 2B 3B SS OF OF OF; Hitter1-5 are C 1B 2B 3B SS, 6-8 OF.
        with_pen = [self.pen, ids["T3 Ace"], *(hitter("T1", i) for i in (1, 2, 3, 4)),
                    *(hitter("T3", i) for i in (5, 6, 7, 8))]
        second = [ids["T2 Ace"], ids["T4 Ace"], *(hitter("T2", i) for i in (1, 2, 3)),
                  *(hitter("T4", i) for i in (4, 5, 6, 7, 8))]
        third = [ids["T2 Ace"], ids["T3 Ace"], *(hitter("T3", i) for i in (1, 2, 3, 4)),
                 *(hitter("T2", i) for i in (5, 6, 7, 8))]
        template = self.root / "DKEntries_template.csv"
        with template.open("w", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow(HEADER)
            for i in range(3):
                writer.writerow([str(7001 + i), "MLB Test GPP", "800", "$1",
                                 *([""] * 10), "", ""])
        gates = {g: True for g in (
            "salary_gate_passed", "entry_grid_gate_passed", "lineup_gate_passed",
            "pitcher_audit_gate_passed", "weather_gate_passed", "odds_gate_passed",
            "projection_schema_gate_passed", "optimizer_gate_passed")}
        parent = run_initial_build(
            runs_root=self.root / "runs", salary_csv=self.salary, entries_csv=template,
            projections=frame,
            candidates=[candidate("A", with_pen, 100, "T3"), candidate("B", second, 99, "T4"),
                        candidate("C", third, 98, "T2")],
            entry_requirements=[{"entry_id": str(7001 + i), "contest_id": "800",
                                 "contest_name": "MLB Test GPP",
                                 "contest_shape": "large_wta"} for i in range(3)],
            workflow_gates=gates, portfolio_controls=pipeline_controls())
        self.assertTrue(parent["passed"], parent.get("errors"))
        self.parent = parent
        self.parent_file = Path(parent["output_path"])
        self.pen_entry = next(
            entry for entry, roster in _entry_rosters(self.parent_file).items()
            if self.pen in roster)
        self.ls = self._tool()
        self.ls._build_slate_module()
        self.ls.REPO = self.root
        from mlb_engine.entries import upload_manifest as um
        self._um_root = um.REPO_ROOT
        um.REPO_ROOT = self.root
        self.addCleanup(setattr, um, "REPO_ROOT", self._um_root)
        now = self.NOW

        class _Frozen(dtmod.datetime):
            @classmethod
            def now(cls, tz=None):
                return now if tz is not None else now.replace(tzinfo=None)

        self.ls.dt = types.SimpleNamespace(
            datetime=_Frozen, timezone=dtmod.timezone, timedelta=dtmod.timedelta,
            date=dtmod.date)
        self.referee_calls = []

        def _referee(*args, **kwargs):
            self.referee_calls.append((args, kwargs))
            return {"exit": 0, "ran": True, "failures": [], "warnings": [],
                    "error": None, "argv": [], "verdict": "upload_ready"}

        self.ls.run_post_swap_preflight = _referee

    def _brief(self, declared=None):
        out = self.root / "outputs" / self.DATE
        out.mkdir(parents=True, exist_ok=True)
        (out / "build_brief_test.json").write_text(json.dumps({
            "run_id": self.parent["run_id"],
            "delivered_sha256": sha256_file(self.parent_file),
            "declared_pitchers": self.declared if declared is None else declared,
        }), encoding="utf-8")

    def _run(self, *extra):
        argv = ["late_swap.py", "--date", self.DATE, "--parent-entries",
                str(self.parent_file), "--postures", "800=large_gpp",
                "--budget", "20", *extra]
        old = sys.argv
        sys.argv = argv
        out, err = io.StringIO(), io.StringIO()
        try:
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
                code = self.ls.main()
        finally:
            sys.argv = old
        return code, out.getvalue(), err.getvalue()

    def test_a_parent_with_a_locked_declared_arm_swaps_and_certifies(self):
        """The row's acceptance: the parent's brief declares the arm, the swap
        inherits it, the pinned entry gets candidates, and the whole file
        certifies."""
        self._brief()
        code, out, err = self._run()
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn("gates: workflow_valid=True selection=True allocation=True", out)
        self.assertNotIn("no compatible candidate", err)
        self.assertIn(f"declared pitchers: {self.pen}=viable_bulk_or_alt_sp", out)
        self.assertIn("from the parent build's brief", out)
        self.assertRegex(out, rf"entry {self.pen_entry}: pinned .*\+[1-9]\d* targeted")
        delivered = self.root / "outputs" / self.DATE
        swapped = [p for p in delivered.glob("DKEntries_*lateswap*.csv")]
        self.assertEqual(len(swapped), 1, sorted(p.name for p in delivered.iterdir()))
        self.assertIn(self.pen, _entry_rosters(swapped[0])[self.pen_entry],
                      "the locked declared arm must stay in his entry")

    def test_without_a_declaration_the_swap_refuses_as_it_did_on_1400_4g(self):
        """The failure this item closes, kept visible: no brief, no flag, the
        arm is absent, and the pinned entry has nothing to take."""
        code, out, err = self._run()
        self.assertEqual(code, 3)
        self.assertRegex(out, rf"entry {self.pen_entry}: pinned .*\+0 targeted")
        self.assertIn(f"no compatible candidate for Entry ID {self.pen_entry}", err)
        self.assertIn("declared pitchers: none", out)

    def test_an_explicit_declaration_carries_the_arm_without_a_brief(self):
        code, out, err = self._run("--declare-pitcher",
                                   f"{self.pen}=viable_bulk_or_alt_sp")
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn("from --declare-pitcher", out)

    def test_the_referee_and_the_printed_command_carry_the_declarations(self):
        """A swap writes no brief, so preflight cannot find the parent's
        declarations by the swapped file's sha: the swap hands them over."""
        self._brief()
        code, out, err = self._run()
        self.assertEqual(code, 0, err[-1500:])
        self.assertEqual(len(self.referee_calls), 1)
        self.assertEqual(self.referee_calls[0][1].get("declared_pitchers"), self.declared)
        verify = [line for line in out.splitlines() if line.startswith("verify at upload:")]
        self.assertEqual(len(verify), 1, out[-800:])
        self.assertIn(f"--declare-pitcher {self.pen}=viable_bulk_or_alt_sp", verify[0])

    def test_the_in_process_referee_receives_each_declaration(self):
        """`run_post_swap_preflight` builds preflight's argv; driven with a
        stand-in `preflight_upload` so the argv itself is what is checked."""
        seen = []
        fake = types.ModuleType("preflight_upload")
        fake.main = lambda argv: (seen.append(list(argv)), 0)[1]
        with unittest.mock.patch.dict(sys.modules, {"preflight_upload": fake}):
            ls = self._tool()
            ls.run_post_swap_preflight(
                self.parent_file, self.parent_file, self.salary, "a" * 64,
                declared_pitchers={"222": "declared_probable_sp", "111": "viable_bulk_or_alt_sp"})
        self.assertEqual(len(seen), 1)
        argv = seen[0]
        pairs = [argv[i + 1] for i, tok in enumerate(argv) if tok == "--declare-pitcher"]
        self.assertEqual(pairs, ["111=viable_bulk_or_alt_sp", "222=declared_probable_sp"])

    def test_explicit_values_merge_over_the_inherited_ones(self):
        self._brief(declared={self.pen: "viable_bulk_or_alt_sp", "999": "declared_probable_sp"})
        from mlb_engine.swap.late_swap_manager import resolve_parent_run
        parent = resolve_parent_run(self.root / "runs", self.parent_file)
        merged, source = self.ls.resolve_swap_declared_pitchers(
            self.root, self.DATE, parent, {"999": "viable_bulk_or_alt_sp", "777": "declared_probable_sp"})
        self.assertEqual(merged, {self.pen: "viable_bulk_or_alt_sp", "999": "viable_bulk_or_alt_sp",
                                  "777": "declared_probable_sp"})
        self.assertIn("parent build's brief", source)
        self.assertIn("--declare-pitcher", source)

    def test_a_mismatched_parent_lends_no_declarations(self):
        """Like R268(a)'s controls: only a parent whose export IS this file
        lends what it shipped."""
        self._brief()
        from mlb_engine.swap.late_swap_manager import resolve_parent_run
        parent = dict(resolve_parent_run(self.root / "runs", self.parent_file))
        parent["current_matches_parent_export"] = False
        merged, source = self.ls.resolve_swap_declared_pitchers(self.root, self.DATE, parent, {})
        self.assertEqual(merged, {})
        self.assertIn("not this file's parent", source)

    def test_a_malformed_declaration_is_exit_4_before_the_pool(self):
        code, out, err = self._run("--declare-pitcher", "=viable_bulk_or_alt_sp")
        self.assertEqual(code, 4)
        self.assertIn("--declare-pitcher", err)
        self.assertNotIn("bank after the general slice", out)

    def test_the_grammar_is_build_slates_own_parser(self):
        self.assertIs(self.ls._declared_pitcher_parser(),
                      self.ls._build_slate_module().parse_declared_pitchers)

    def test_a_swap_of_a_swap_keeps_the_declarations(self):
        """The later windows are where 1400_4g needed this. A swap writes no
        brief, so the second swap's parent (the first swap's run) has none:
        each swap run records what it carried, and the next one reads it."""
        self._brief()
        code, out, err = self._run()
        self.assertEqual(code, 0, err[-1500:])
        first = next((self.root / "outputs" / self.DATE).glob("DKEntries_*lateswap*.csv"))
        self.parent_file = first
        code, out, err = self._run()
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn(f"declared pitchers: {self.pen}=viable_bulk_or_alt_sp", out)
        self.assertIn("from the parent swap run", out)
        self.assertNotIn("no compatible candidate", err)

    def test_a_non_numeric_declaration_is_exit_4_before_the_pool(self):
        """build_slate's parser takes any non-empty id and the pool skips an
        unknown one with a warning; preflight's parser needs a DK id and raises,
        which after a written swap is a referee crash at exit 3. Refused here."""
        code, out, err = self._run("--declare-pitcher", "Painter=viable_bulk_or_alt_sp")
        self.assertEqual(code, 4)
        self.assertIn("Painter", err)
        self.assertNotIn("bank after the general slice", out)

    def test_a_non_numeric_id_in_the_parent_brief_is_dropped_by_name(self):
        self._brief(declared={**self.declared, "Painter": "viable_bulk_or_alt_sp"})
        from mlb_engine.swap.late_swap_manager import resolve_parent_run
        parent = resolve_parent_run(self.root / "runs", self.parent_file)
        merged, source = self.ls.resolve_swap_declared_pitchers(self.root, self.DATE, parent, {})
        self.assertEqual(merged, self.declared)
        self.assertIn("Painter", source)


def _entry_rosters(path) -> dict:
    from mlb_engine.entries.dk_entries_manager import parse_dk_entry_rows
    return {row.entry_id: list(row.roster_cells) for row in parse_dk_entry_rows(path)}


class LateSwapEnrichedFrameTests(unittest.TestCase):
    """R428 (roadmap Session 115). A late swap ranks candidates, and compares the
    incumbent with the chosen lineup, on the frame its PARENT RUN applied, not on
    AvgPointsPerGame x batting order.

    The parent brief records counts and file ages and `runs/<id>/inputs/` holds only
    the salary and entries files, so the register's "reuse the parent's inputs" had
    nothing to read. What a run does persist per player is its applied values, in
    `final/projections.csv`: Base after the xwOBA correction and the value guard,
    F1..F5 and the Ceiling_Multiplier. `late_swap.resolve_swap_carry` reads them,
    `_assemble_projection_frame(carried_by_player_id=)` overlays them (after the
    value guard, before the shared `build_projections`), and only the batting
    orders (F2) are the new feed's.

    Three layers, each driving the production function: the engine overlay (E*),
    the resolver over hand-written `runs/` skeletons (R*), and the real
    `late_swap.main()` over a real parent run and a real `run_late_swap` (S*, the
    R468 harness composed, never subclassed, so its tests do not run twice). The
    harness's own parent frame is NEUTRAL, so the swap-level parent is a SECOND
    `run_initial_build` in the same temp `runs/` whose frame was assembled through
    the real map path (F1/F4/F5) plus the new kwarg (Ceiling_Multiplier: a column
    set after assembly never reaches Ceiling, and synthetic Savant CSVs would need
    the DK-keyed name crosswalk to match the fixture's names).
    """

    DATE = LateSwapDeclaredPitcherTests.DATE

    # -- engine fixtures ---------------------------------------------------------- #

    def _eng(self, tmp):
        salary = Path(tmp) / "salary.csv"
        return salary, write_salary(salary)

    @staticmethod
    def _rows(overrides=None, extra=None):
        overrides = overrides or {}
        extra = extra or {}
        out = []
        for raw in salary_rows():
            row = {"Player_ID": raw[3], "AvgPointsPerGame": overrides.get(raw[2], 10.0)}
            row.update(extra.get(raw[2], {}))
            out.append(row)
        return out

    @staticmethod
    def _by_id(frame):
        return {str(r["Player_ID"]): r for r in frame.to_dict("records")}

    def _assemble(self, salary, rows, **kw):
        return epi._assemble_projection_frame(
            str(salary), rows, "emergency_proxy", None, None, None, **kw)

    # -- E: the engine overlay ---------------------------------------------------- #

    def test_E1_the_overlay_lands_and_f2_and_the_order_are_the_pools(self):
        with tempfile.TemporaryDirectory() as tmp:
            salary, ids = self._eng(tmp)
            rows = self._rows(extra={"AAA SS": {"Batting_Order": 3, "F2": 1.07}})
            carried = {
                ids["AAA SS"]: {"Base": 12.0, "F1": 1.10, "F3": 1.02, "F4": 0.95, "F5": 1.05,
                                "Ceiling_Multiplier": 1.30,
                                # never read: F2 and the order are the pool's
                                "F2": 9.9, "Batting_Order": 9},
                ids["Pitcher C"]: {"F1": 1.04, "Ceiling_Multiplier": 1.60},
            }
            frame, enrich = self._assemble(salary, rows, carried_by_player_id=carried)
            by = self._by_id(frame)
            ss = by[ids["AAA SS"]]
            self.assertEqual((float(ss["Base"]), float(ss["F1"]), float(ss["F2"]), float(ss["F3"]),
                              float(ss["F4"]), float(ss["F5"])),
                             (12.0, 1.10, 1.07, 1.02, 0.95, 1.05))
            self.assertEqual(int(ss["Batting_Order"]), 3)
            bp = 12.0 * 1.10 * 1.07 * 1.02 * 0.95 * 1.05
            self.assertAlmostEqual(float(ss["Base_Projection"]), bp, places=9)
            self.assertAlmostEqual(float(ss["Ceiling"]), bp * 1.30, places=9)
            self.assertAlmostEqual(float(ss["Floor"]), bp * 0.58, places=9)
            self.assertIn("carried_from_parent", str(ss["Notes"]))
            arm = by[ids["Pitcher C"]]
            self.assertEqual((float(arm["Base"]), float(arm["F1"])), (10.0, 1.04))
            self.assertAlmostEqual(float(arm["Ceiling"]) / float(arm["Base_Projection"]), 1.60, places=9)
            other = by[ids["AAA C"]]
            self.assertEqual((float(other["Base"]), float(other["F1"]), float(other["F4"])), (10.0, 1.0, 1.0))
            self.assertAlmostEqual(float(other["Ceiling"]) / float(other["Base_Projection"]), 1.42, places=9)
            self.assertNotIn("carried_from_parent", str(other["Notes"]))
            block = enrich["carried"]
            self.assertEqual((block["requested"], block["applied_count"]), (2, 2))
            self.assertEqual(block["non_neutral"], {"f1": 2, "f3": 1, "f4": 1, "f5": 1,
                                                    "ceiling_multiplier": 2})
            self.assertEqual(block["base_restated"], 1)
            self.assertEqual(block["f1_games_priced"], 2)
            self.assertEqual(block["by_side"]["pitchers"], {"pool": 2, "carried": 1})
            self.assertEqual(block["by_side"]["hitters"], {"pool": 16, "carried": 1})

    def test_E1_without_the_kwarg_the_frame_and_the_record_are_byte_identical(self):
        """Negative control: the default, None and {} are today's call exactly, and no
        other caller's enrichment record gains a key."""
        with tempfile.TemporaryDirectory() as tmp:
            salary, ids = self._eng(tmp)
            rows = self._rows(extra={"AAA SS": {"Batting_Order": 3, "F2": 1.07}})
            base, base_enrich = self._assemble(salary, rows)
            for kw in ({"carried_by_player_id": None}, {"carried_by_player_id": {}}):
                again, enrich = self._assemble(salary, rows, **kw)
                pd.testing.assert_frame_equal(base, again)
                self.assertNotIn("carried", enrich)
            self.assertNotIn("carried", base_enrich)
            self.assertEqual(sorted(base_enrich), sorted(enrich))

    def test_E2_the_value_guard_does_not_reclip_a_carried_base(self):
        with tempfile.TemporaryDirectory() as tmp:
            salary, ids = self._eng(tmp)
            rows = self._rows(overrides={"AAA SS": 30.0, "CCC SS": 30.0})
            plain, _ = self._assemble(salary, rows)
            cap = float(self._by_id(plain)[ids["CCC SS"]]["Base"])
            self.assertLess(cap, 25.0, "the guard must clip a 30.0 APPG below the carried 25.0 "
                                       "for this test to mean anything")
            frame, _ = self._assemble(salary, rows,
                                      carried_by_player_id={ids["AAA SS"]: {"Base": 25.0}})
            by = self._by_id(frame)
            self.assertEqual(float(by[ids["AAA SS"]]["Base"]), 25.0,
                             "a Base the parent already capped is not capped again")
            self.assertAlmostEqual(float(by[ids["CCC SS"]]["Base"]), cap, places=9,
                                   msg="a row that was not carried is still capped")

    def test_E3_a_workload_row_keeps_its_own_base_and_takes_the_factors(self):
        with tempfile.TemporaryDirectory() as tmp:
            salary, ids = self._eng(tmp)
            rows = self._rows(extra={"Pitcher C": {"Workload_Factor": 0.5}})
            frame, enrich = self._assemble(
                salary, rows, carried_by_player_id={
                    ids["Pitcher C"]: {"Base": 20.0, "F1": 1.05},
                    ids["AAA C"]: {"F4": 1.10}})
            by = self._by_id(frame)
            self.assertEqual(float(by[ids["Pitcher C"]]["Base"]), 5.0,
                             "APPG 10 x the swap's own 0.5 prior, never the carried 20 scaled twice")
            self.assertEqual(float(by[ids["Pitcher C"]]["F1"]), 1.05)
            self.assertEqual(enrich["carried"]["base_kept_workload_prior_ids"], [ids["Pitcher C"]])
            self.assertEqual(float(by[ids["AAA C"]]["Base"]), 10.0, "a record with no Base leaves Base")
            self.assertEqual(float(by[ids["AAA C"]]["F4"]), 1.10)

    def test_E4_the_pool_is_the_callers_never_trimmed_or_widened(self):
        with tempfile.TemporaryDirectory() as tmp:
            salary, ids = self._eng(tmp)
            rows = self._rows()
            plain, _ = self._assemble(salary, rows)
            frame, enrich = self._assemble(
                salary, rows, carried_by_player_id={
                    ids["AAA SS"]: {"F1": 1.1}, "99999": {"F1": 1.2}})
            self.assertEqual(list(frame["Player_ID"]), list(plain["Player_ID"]))
            block = enrich["carried"]
            self.assertEqual((block["requested"], block["applied_count"]), (2, 1))
            self.assertNotIn("99999", [str(p) for p in frame["Player_ID"]])
            self.assertIn(ids["AAA C"], block["not_carried_player_ids"])
            self.assertEqual(len(block["not_carried_player_ids"]), len(plain) - 1)
            row = self._by_id(frame)[ids["AAA C"]]
            self.assertEqual((float(row["F1"]), float(row["Base"])), (1.0, 10.0))

    def test_E5_a_value_the_engine_refuses_raises_naming_the_player(self):
        with tempfile.TemporaryDirectory() as tmp:
            salary, ids = self._eng(tmp)
            rows = self._rows()
            with self.assertRaisesRegex(ValueError, "Ceiling below Floor"):
                self._assemble(salary, rows, carried_by_player_id={
                    ids["AAA SS"]: {"Ceiling_Multiplier": 0.3}})
            for bad in (float("nan"), float("inf"), -1.0, "abc"):
                with self.assertRaisesRegex(ValueError, ids["AAA SS"]):
                    self._assemble(salary, rows, carried_by_player_id={
                        ids["AAA SS"]: {"F1": bad}})
            # a record that is not a mapping is the same refusal, so `main()`'s fallback
            # catches it (a TypeError would escape as a traceback)
            for bad_record in (None, [1.1], "1.1"):
                with self.assertRaisesRegex(ValueError, "not a mapping"):
                    self._assemble(salary, rows, carried_by_player_id={ids["AAA SS"]: bad_record})

    # -- R: the resolver over hand-written runs/ skeletons ------------------------ #

    def _skeleton(self, root, run_id, *, mode="initial_build", parent=None, frame=None,
                  salary_ids=None, metadata=None):
        """One run directory with only what `resolve_swap_carry` reads."""
        run = Path(root) / "runs" / run_id
        (run / "final").mkdir(parents=True)
        (run / "inputs").mkdir()
        (run / "manifest.json").write_text(json.dumps({
            "run_id": run_id, "mode": mode, "parent_run_id": parent,
            "metadata": metadata or {}}), encoding="utf-8")
        if frame is not None:
            cols = sorted({c for row in frame for c in row})
            with (run / "final" / "projections.csv").open("w", newline="", encoding="utf-8") as fh:
                writer = csv.DictWriter(fh, fieldnames=cols)
                writer.writeheader()
                writer.writerows(frame)
        ids = salary_ids if salary_ids is not None else ["1", "2", "3"]
        with (run / "inputs" / "DKSalaries.csv").open("w", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow(["Position", "Name", "ID"])
            writer.writerows([["OF", f"p{i}", i] for i in ids])
        return run

    @staticmethod
    def _neutral(ids=("1", "2", "3")):
        return [{"Player_ID": i, "Base": "10.0", "F1": "1.0", "F3": "1.0", "F4": "1.0", "F5": "1.0"}
                for i in ids]

    @staticmethod
    def _rich(ids=("1", "2", "3")):
        return [{"Player_ID": i, "Base": "11.0", "F1": "1.08", "F3": "1.0", "F4": "0.97",
                 "F5": "1.02", "Ceiling_Multiplier": "1.31"} for i in ids]

    def _resolve(self, root, run_id, *, matched=True, salary_ids=None, verify=True):
        ls = LateSwapDeclaredPitcherTests._tool()
        sal = Path(root) / "swap_salary.csv"
        with sal.open("w", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow(["Position", "Name", "ID"])
            writer.writerows([["OF", f"p{i}", i] for i in (salary_ids or ["1", "2", "3"])])
        manifest = json.loads((Path(root) / "runs" / run_id / "manifest.json").read_text())
        parent = {"run_dir": str(Path(root) / "runs" / run_id), "manifest": manifest,
                  "current_matches_parent_export": matched, "parent_export_sha256": "abc"}

        def stub(run_dir):
            ok = verify(Path(run_dir).name) if callable(verify) else bool(verify)
            return {"passed": ok, "errors": [] if ok else ["hash mismatch: final/projections.csv"]}

        with unittest.mock.patch.object(ls, "verify_run_bundle", side_effect=stub):
            return ls.resolve_swap_carry(Path(root) / "runs", parent, sal)

    def test_R1_one_hop_carries_every_row_and_records_the_bytes_it_read(self):
        with tempfile.TemporaryDirectory() as tmp:
            run = self._skeleton(tmp, "B1", frame=self._rich())
            carried, info = self._resolve(tmp, "B1")
            self.assertEqual(sorted(carried), ["1", "2", "3"])
            self.assertEqual(carried["1"], {"Base": 11.0, "F1": 1.08, "F3": 1.0, "F4": 0.97,
                                            "F5": 1.02, "Ceiling_Multiplier": 1.31})
            src = info["source"]
            self.assertEqual((src["run_id"], src["hops"], src["origin_run_id"]), ("B1", 0, "B1"))
            self.assertEqual(src["frame_sha256"],
                             hashlib.sha256((run / "final" / "projections.csv").read_bytes()).hexdigest())
            self.assertTrue(src["parent_matches_file"])

    def test_R2_a_neutral_swap_intermediate_walks_to_the_root_build(self):
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "ROOT", frame=self._rich())
            self._skeleton(tmp, "SW1", mode="late_swap", parent="ROOT", frame=self._neutral())
            self._skeleton(tmp, "SW2", mode="late_swap", parent="SW1", frame=self._neutral())
            carried, info = self._resolve(tmp, "SW2")
            self.assertEqual(info["source"]["run_id"], "ROOT")
            self.assertEqual(info["source"]["hops"], 2)
            self.assertEqual([s["run_id"] for s in info["chain"]], ["SW2", "SW1", "ROOT"])
            self.assertEqual(info["chain"][0]["verdict"], "frame carries no factor or multiplier off neutral")
            self.assertEqual(carried["2"]["F1"], 1.08)

    def test_R2_an_enriched_swap_run_with_no_root_on_disk_is_used_and_names_its_origin(self):
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "SW1", mode="late_swap", parent="ROOT", frame=self._rich(),
                           metadata={"projection_carry": {"source": {"origin_run_id": "ROOT"}}})
            carried, info = self._resolve(tmp, "SW1")
            self.assertEqual((info["source"]["run_id"], info["source"]["hops"],
                              info["source"]["origin_run_id"]), ("SW1", 0, "ROOT"))
            self.assertIn("absent or unreadable", info["chain"][-1]["verdict"])

    def test_R2_a_swap_run_does_not_lend_the_rows_it_never_carried(self):
        """Player 3 sits in the swap run's frame at neutral because ITS parent never carried
        him: that row is a placeholder, so he is not lent (and the label names him)."""
        with tempfile.TemporaryDirectory() as tmp:
            frame = self._rich(("1", "2")) + self._neutral(("3",))
            self._skeleton(tmp, "SW1", mode="late_swap", parent="GONE", frame=frame,
                           metadata={"projection_carry": {"not_carried_player_ids": ["3"],
                                                          "source": {"origin_run_id": "ROOT"}}})
            carried, info = self._resolve(tmp, "SW1")
            self.assertEqual(sorted(carried), ["1", "2"])
            self.assertEqual(info["chain"][0]["placeholders_not_lent"], 1)
        with tempfile.TemporaryDirectory() as tmp:    # neg. control: no record, the row is lent
            frame = self._rich(("1", "2")) + self._neutral(("3",))
            self._skeleton(tmp, "SW1", mode="late_swap", parent="GONE", frame=frame)
            self.assertEqual(sorted(self._resolve(tmp, "SW1")[0]), ["1", "2", "3"])

    def test_R2_the_root_most_frame_wins_and_keeps_a_player_the_intermediate_lacks(self):
        """A swap's own frame holds the root's values only for ITS pool's players, and a
        later swap's pool is not the earlier one's (a side confirmed since is why there is
        a later swap): stopping at the nearest enriched swap run would drop player 3."""
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "ROOT", frame=self._rich(("1", "2", "3")))
            self._skeleton(tmp, "SW1", mode="late_swap", parent="ROOT", frame=self._rich(("1", "2")),
                           metadata={"projection_carry": {"source": {"origin_run_id": "ROOT"}}})
            carried, info = self._resolve(tmp, "SW1")
            self.assertEqual(sorted(carried), ["1", "2", "3"])
            self.assertEqual((info["source"]["run_id"], info["source"]["hops"]), ("ROOT", 1))
            sw1 = next(s for s in info["chain"] if s["run_id"] == "SW1")
            self.assertTrue(sw1["verdict"].startswith("enriched; the root-most usable frame"))

    def test_R3_every_ancestor_neutral_is_unenriched_with_the_chain_named(self):
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "ROOT", frame=self._neutral())
            self._skeleton(tmp, "SW1", mode="late_swap", parent="ROOT", frame=self._neutral())
            carried, info = self._resolve(tmp, "SW1")
            self.assertEqual(carried, {})
            self.assertFalse(info["carried"])
            self.assertIn("no run in the parent chain", info["reason"])
            self.assertEqual([s["run_id"] for s in info["chain"]], ["SW1", "ROOT"])

    def test_R3_a_cycle_and_a_missing_ancestor_stop_the_walk_and_say_so(self):
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "A", mode="late_swap", parent="B", frame=self._neutral())
            self._skeleton(tmp, "B", mode="late_swap", parent="A", frame=self._neutral())
            carried, info = self._resolve(tmp, "A")
            self.assertEqual(carried, {})
            self.assertEqual(info["chain"][-1]["verdict"], "already examined (a cycle in parent_run_id)")
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "C", mode="late_swap", parent="GONE", frame=self._neutral())
            carried, info = self._resolve(tmp, "C")
            self.assertEqual(carried, {})
            self.assertIn("absent or unreadable", info["chain"][-1]["verdict"])

    def test_R4_a_bad_row_is_rejected_by_id_and_its_neighbours_still_carry(self):
        with tempfile.TemporaryDirectory() as tmp:
            frame = self._rich(("1", "2", "3", "4"))
            frame[0]["F1"] = "nan"
            frame[1]["Ceiling_Multiplier"] = "-1"
            frame[2]["Base"] = "-5"
            self._skeleton(tmp, "B1", frame=frame, salary_ids=["1", "2", "3", "4"])
            carried, info = self._resolve(tmp, "B1", salary_ids=["1", "2", "3", "4"])
            self.assertEqual(sorted(carried), ["4"])
            self.assertEqual(sorted(r["id"] for r in info["rejected_rows"]), ["1", "2", "3"])
            self.assertEqual(info["rejected_rows_n"], 3)

    def test_R4_an_unreadable_frame_and_one_with_no_player_id_never_raise(self):
        with tempfile.TemporaryDirectory() as tmp:
            run = self._skeleton(tmp, "B1", frame=self._rich())
            (run / "final" / "projections.csv").write_bytes(b"\xff\xfe\x00 not a csv")
            carried, info = self._resolve(tmp, "B1")
            self.assertEqual(carried, {})
            self.assertIn("frame unreadable", info["chain"][0]["verdict"])
        with tempfile.TemporaryDirectory() as tmp:
            run = self._skeleton(tmp, "B1", frame=self._rich())
            (run / "final" / "projections.csv").write_text("Base,F1\n11,1.1\n", encoding="utf-8")
            carried, info = self._resolve(tmp, "B1")
            self.assertEqual(carried, {})
            self.assertIn("no Player_ID column", info["chain"][0]["verdict"])

    def test_R5_a_parent_row_with_a_workload_prior_lends_its_factors_but_not_its_base(self):
        with tempfile.TemporaryDirectory() as tmp:
            frame = self._rich()
            frame[0]["Workload_Factor"] = "0.5"
            self._skeleton(tmp, "B1", frame=frame)
            carried, _ = self._resolve(tmp, "B1")
            self.assertNotIn("Base", carried["1"])
            self.assertEqual(carried["1"]["F1"], 1.08)
            self.assertEqual(carried["2"]["Base"], 11.0)

    def test_R6_an_ancestor_that_fails_bundle_verification_is_skipped_by_name(self):
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "ROOT", frame=self._rich())
            self._skeleton(tmp, "MID", mode="late_swap", parent="ROOT", frame=self._rich())
            self._skeleton(tmp, "SW", mode="late_swap", parent="MID", frame=self._neutral())
            carried, info = self._resolve(tmp, "SW", verify=lambda run: run != "ROOT")
            self.assertEqual(info["source"]["run_id"], "MID", "ROOT's bytes were never trusted")
            root = next(s for s in info["chain"] if s["run_id"] == "ROOT")
            self.assertIn("failed bundle verification", root["verdict"])
            # the direct parent was verified by resolve_parent_run, not again here
            self.assertEqual(self._resolve(tmp, "ROOT", verify=lambda run: False)[1]["source"]["hops"], 0)

    def test_R7_a_parent_that_is_not_this_files_lineage_lends_only_for_the_same_slate(self):
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "B1", frame=self._rich())
            same, info = self._resolve(tmp, "B1", matched=False)
            self.assertEqual(sorted(same), ["1", "2", "3"])
            self.assertFalse(info["source"]["parent_matches_file"])
            self.assertEqual(len(info["source"]["slate_pool_signature"]), 10)
            other, info = self._resolve(tmp, "B1", matched=False, salary_ids=["1", "2", "9"])
            self.assertEqual(other, {})
            self.assertIn("another slate", info["chain"][0]["verdict"])
            # a matched parent needs no slate check on itself
            self.assertEqual(sorted(self._resolve(tmp, "B1", matched=True,
                                                  salary_ids=["1", "2", "9"])[0]), ["1", "2", "3"])

    def test_R7_a_stale_parent_run_id_cannot_cross_slates(self):
        with tempfile.TemporaryDirectory() as tmp:
            self._skeleton(tmp, "OTHER", frame=self._rich(), salary_ids=["7", "8", "9"])
            self._skeleton(tmp, "SW", mode="late_swap", parent="OTHER", frame=self._neutral())
            carried, info = self._resolve(tmp, "SW")
            self.assertEqual(carried, {})
            self.assertIn("another slate", info["chain"][-1]["verdict"])

    def test_R8_no_parent_and_no_salary_snapshot_are_named_not_raised(self):
        ls = LateSwapDeclaredPitcherTests._tool()
        with tempfile.TemporaryDirectory() as tmp:
            sal = Path(tmp) / "s.csv"
            sal.write_text("Position,Name,ID\nOF,p1,1\n", encoding="utf-8")
            carried, info = ls.resolve_swap_carry(Path(tmp) / "runs", None, sal)
            self.assertEqual((carried, info["reason"]), ({}, "no parent run resolved"))
            run = self._skeleton(tmp, "B1", frame=self._rich())
            (run / "inputs" / "DKSalaries.csv").unlink()
            carried, info = self._resolve(tmp, "B1", matched=False)
            self.assertEqual(carried, {})
            self.assertIn("no salary snapshot", info["chain"][0]["verdict"])

    # -- S: the real late_swap.main() --------------------------------------------- #

    @staticmethod
    def _team(name):
        return name.split(" ", 1)[0]

    def _world(self, *, enriched=True, drop=()):
        """The R468 harness plus, when ``enriched``, a SECOND parent build whose frame
        carries odds/matchup/park values and Ceiling_Multipliers, promoted last, with
        the declared-pitcher brief written for IT. ``drop`` names players the second
        parent's frame never carried."""
        h = LateSwapDeclaredPitcherTests("test_the_grammar_is_build_slates_own_parser")
        h.setUp()
        self.addCleanup(h.doCleanups)
        with h.salary.open(newline="", encoding="utf-8") as fh:
            sal_rows = list(csv.reader(fh))[1:]
        id_by_name = {r[2]: r[3] for r in sal_rows}
        name_by_id = {v: k for k, v in id_by_name.items()}
        feed = json.loads((h.root / "data" / "slates" / h.DATE / "lineups_feed.json").read_text(
            encoding="utf-8"))
        pool = lda.build_slate_pool(str(h.salary), feed, declared_pitchers=h.declared)
        pool_rows = [dict(r) for r in pool["run_slate_kwargs"]["projection_rows"]]
        fx = {"h": h, "ids": id_by_name, "names": name_by_id, "pool_rows": pool_rows}
        if not enriched:
            return fx
        orig = {str(r["Player_ID"]): dict(r) for r in pool_rows}
        trap = next(pid for pid in sorted(orig)
                    if orig[pid].get("Batting_Order") and "Hitter" in name_by_id[pid]
                    and self._team(name_by_id[pid]) == "T3"
                    and int(orig[pid]["Batting_Order"]) > 4)
        fx["trap"], fx["trap_orig"] = trap, orig[trap]
        parent_rows = []
        for row in pool_rows:
            row = dict(row)
            if name_by_id[str(row["Player_ID"])] in drop:
                continue
            if str(row["Player_ID"]) == trap:
                row["Batting_Order"], row["F2"] = 1, 1.10     # the parent's lineup led him off
            parent_rows.append(row)
        f1, f4, f5, cm = {}, {}, {}, {}
        for name, pid in id_by_name.items():
            team = self._team(name)
            hitter = "Hitter" in name or "Bench" in name
            if hitter:
                f1[pid] = 1.08 if team in ("T1", "T2") else 0.95
                f4[pid] = 0.98 if team in ("T1", "T2") else 1.03
                if team in ("T3", "T4"):
                    f5[pid] = 0.94
                    cm[pid] = {"Ceiling_Multiplier": 1.30}
            elif name.endswith("Ace"):
                f1[pid] = {"T1": 1.04, "T3": 0.97}.get(team, 1.0)
        parent_frame, _ = epi._assemble_projection_frame(
            str(h.salary), parent_rows, "emergency_proxy", None, None, None,
            f4_by_player_id=f4, f1_by_player_id=f1, f5_by_player_id=f5,
            carried_by_player_id=cm)
        ids = id_by_name
        hit = lambda team, i: ids[f"{team} Hitter{i}"]
        with_pen = [h.pen, ids["T3 Ace"], *(hit("T1", i) for i in (1, 2, 3, 4)),
                    *(hit("T3", i) for i in (5, 6, 7, 8))]
        second = [ids["T2 Ace"], ids["T4 Ace"], *(hit("T2", i) for i in (1, 2, 3)),
                  *(hit("T4", i) for i in (4, 5, 6, 7, 8))]
        third = [ids["T2 Ace"], ids["T3 Ace"], *(hit("T3", i) for i in (1, 2, 3, 4)),
                 *(hit("T2", i) for i in (5, 6, 7, 8))]
        gates = {g: True for g in (
            "salary_gate_passed", "entry_grid_gate_passed", "lineup_gate_passed",
            "pitcher_audit_gate_passed", "weather_gate_passed", "odds_gate_passed",
            "projection_schema_gate_passed", "optimizer_gate_passed")}
        parent = run_initial_build(
            runs_root=h.root / "runs", salary_csv=h.salary,
            entries_csv=h.root / "DKEntries_template.csv", projections=parent_frame,
            candidates=[candidate("A", with_pen, 100, "T3"), candidate("B", second, 99, "T4"),
                        candidate("C", third, 98, "T2")],
            entry_requirements=[{"entry_id": str(7001 + i), "contest_id": "800",
                                 "contest_name": "MLB Test GPP",
                                 "contest_shape": "large_wta"} for i in range(3)],
            workflow_gates=gates, portfolio_controls=pipeline_controls())
        self.assertTrue(parent["passed"], parent.get("errors"))
        h.parent, h.parent_file = parent, Path(parent["output_path"])
        fx.update(parent=parent, parent_frame=parent_frame)
        h._brief()
        return fx

    def _frame_of(self, root, run_id):
        with (Path(root) / "runs" / run_id / "final" / "projections.csv").open(
                encoding="utf-8-sig", newline="") as fh:
            return {r["Player_ID"]: r for r in csv.DictReader(fh)}

    def _swap_runs(self, root):
        out = []
        for path in sorted((Path(root) / "runs").glob("*/manifest.json")):
            manifest = json.loads(path.read_text(encoding="utf-8"))
            if manifest.get("mode") == "late_swap":
                out.append(manifest)
        return out

    def _record(self, h):
        records = sorted((h.root / "data" / "deliveries" / h.DATE).glob("*.json"))
        self.assertEqual(len(records), 1, [p.name for p in records])
        return json.loads(records[0].read_text(encoding="utf-8"))

    def test_S1_an_enriched_parent_is_carried_and_the_label_prints_f1_games_priced(self):
        fx = self._world()
        h = fx["h"]
        code, out, err = h._run()
        self.assertEqual(code, 0, err[-1500:])
        parent_id = fx["parent"]["run_id"]
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        self.assertIn(f"ENRICHED by carry from run {parent_id}", line)
        self.assertIn("f1_games_priced=2 (games with a non-neutral F1 row", line)
        self.assertIn("Every pool player was carried", line)
        self.assertNotIn("uniform neutral", out + err, "the pre-carry neutral-default text is not echoed")
        swap = self._swap_runs(h.root)
        self.assertEqual(len(swap), 1)
        swap_frame = self._frame_of(h.root, swap[0]["run_id"])
        parent_frame = self._frame_of(h.root, parent_id)
        carried_ids = [p for p in swap_frame if p in parent_frame]
        self.assertGreater(len(carried_ids), 30)
        for pid in carried_ids:
            for col in ("Base", "F1", "F3", "F4", "F5", "Ceiling_Multiplier"):
                a, b = swap_frame[pid].get(col), parent_frame[pid].get(col)
                self.assertAlmostEqual(float(a), float(b), places=9, msg=f"{pid} {col}")
        # F2 and the order are the FEED's: the parent led this hitter off.
        trap = fx["trap"]
        self.assertEqual(int(float(parent_frame[trap]["Batting_Order"])), 1)
        self.assertEqual(int(float(swap_frame[trap]["Batting_Order"])),
                         int(fx["trap_orig"]["Batting_Order"]))
        from mlb_engine.projections.projection_builder import batting_order_factor
        self.assertAlmostEqual(float(swap_frame[trap]["F2"]),
                               batting_order_factor(int(fx["trap_orig"]["Batting_Order"])), places=9)
        self.assertNotAlmostEqual(float(swap_frame[trap]["F2"]), 1.10, places=3)
        meta = swap[0]["metadata"]["projection_carry"]
        self.assertTrue(meta["carried"])
        self.assertEqual(meta["tier"], "enriched")
        self.assertEqual(meta["source"]["run_id"], parent_id)
        self.assertEqual(meta["source"]["frame_sha256"], sha256_file(
            h.root / "runs" / parent_id / "final" / "projections.csv"))
        self.assertEqual(meta["counts"]["f1_games_priced"], 2)
        record = self._record(h)
        self.assertEqual(record["manifest_row"]["projection_tier"], "enriched")
        self.assertIn(f"frame carried from run {parent_id}", json.dumps(record))

    def test_S2_a_neutral_parent_is_labelled_unenriched_and_still_swaps(self):
        """Negative control for S1: the R468 harness's own parent frame carries nothing."""
        fx = self._world(enriched=False)
        h = fx["h"]
        h._brief()
        code, out, err = h._run()
        self.assertEqual(code, 0, err[-1500:])
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        self.assertIn("UNENRICHED (no run in the parent chain lends an enriched frame", line)
        self.assertIn("AvgPointsPerGame x batting order only", line)
        self.assertNotIn("f1_games_priced", line)
        swap = self._swap_runs(h.root)
        self.assertFalse(swap[0]["metadata"]["projection_carry"]["carried"])
        self.assertEqual(swap[0]["metadata"]["projection_carry"]["tier"], "proxy")
        self.assertEqual(self._record(h)["manifest_row"]["projection_tier"], "proxy")

    def test_S3_a_mismatched_parent_lends_only_when_it_is_the_same_slate(self):
        fx = self._world()
        h = fx["h"]
        # A hand-edited copy: one harmless cell (the Instructions column) differs, so
        # its bytes match no run's export while every entry and roster is unchanged.
        hand_edited = h.root / "DKEntries_hand_edited.csv"
        with Path(h.parent_file).open(newline="", encoding="utf-8") as fh:
            table = list(csv.reader(fh))
        table[1][-1] = "hand edited"
        with hand_edited.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(table)
        h.parent_file = hand_edited
        pen = f"{h.pen}=viable_bulk_or_alt_sp"
        # `--accept-downgrade`: with no parent controls to inherit, the re-derived
        # controls pick a lineup that scores below the incumbent on the parent's own
        # model (the F16 refusal reading the carried frame, R428's point). This test is
        # about the frame and its label, not the refusal.
        # S3b: same salary file, so the same pool signature: the frame is carried.
        code, out, err = h._run("--allow-parent-mismatch", "--accept-downgrade",
                                "--declare-pitcher", pen)
        self.assertEqual(code, 0, err[-1500:])
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        self.assertIn("ENRICHED by carry", line)
        self.assertIn("NOT this file's lineage; same slate by pool signature", line)
        s3b_run = self._swap_runs(h.root)[-1]
        self.assertEqual(s3b_run["metadata"]["projection_carry"]["tier"], "enriched")
        # S3a: the swap's salary file has another player-ID universe: another slate.
        other = h.root / "DKSalaries_other.csv"
        lines = h.salary.read_text(encoding="utf-8").splitlines()
        drop = f",{fx['ids']['T1 Bench4']},"
        kept = [l for l in lines if drop not in l]
        self.assertEqual(len(kept), len(lines) - 1)
        other.write_text("\n".join(kept) + "\n", encoding="utf-8")
        code, out, err = h._run("--allow-parent-mismatch", "--accept-downgrade",
                                "--declare-pitcher", pen, "--salary", str(other))
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        self.assertIn("UNENRICHED", line)
        self.assertIn("another slate", line)
        # By identity, not by sort order (S6's fix; R487): run ids are `<second>_<random
        # suffix>`, so S3b and S3a minted in one second sort by the suffix and `[-1]` can
        # be S3b, whose tier is "enriched" (a CI flake on fast runners).
        s3a_run = next(r for r in self._swap_runs(h.root) if r["run_id"] != s3b_run["run_id"])
        self.assertEqual(s3a_run["metadata"]["projection_carry"]["tier"], "proxy")

    def test_S4_a_value_the_engine_refuses_builds_unenriched_and_never_refuses(self):
        fx = self._world()
        h = fx["h"]
        ls = h.ls
        bad = {pid: {"Ceiling_Multiplier": 0.3} for pid in fx["ids"].values()}
        info = {"carried": True, "reason": None, "chain": [], "rejected_rows": [],
                "rejected_rows_n": 0,
                "source": {"run_id": "X", "mode": "initial_build", "origin_run_id": "X", "hops": 0,
                           "frame_sha256": "0" * 64, "parent_matches_file": True,
                           "slate_pool_signature": None}}
        with unittest.mock.patch.object(ls, "resolve_swap_carry", return_value=(bad, info)):
            code, out, err = h._run()
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn("ENRICHMENT CARRY FAILED, building unenriched", err)
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        self.assertIn("carry REJECTED (the engine refused a carried value", line)
        self.assertEqual(self._swap_runs(h.root)[-1]["metadata"]["projection_carry"]["tier"], "proxy")
        self.assertEqual(self._record(h)["manifest_row"]["projection_tier"], "proxy")

    def test_S5_the_legal_pool_is_not_trimmed_and_a_player_the_parent_never_carried_stays(self):
        fx = self._world(drop=("T4 Hitter1",))
        h = fx["h"]
        never = fx["ids"]["T4 Hitter1"]
        code, out, err = h._run()
        self.assertEqual(code, 0, err[-1500:])
        swap_frame = self._frame_of(h.root, self._swap_runs(h.root)[-1]["run_id"])
        parent_frame = self._frame_of(h.root, fx["parent"]["run_id"])
        self.assertNotIn(never, parent_frame)
        pool_ids = {str(r["Player_ID"]) for r in fx["pool_rows"]}
        self.assertEqual(set(swap_frame), pool_ids, "the swap's frame is exactly the swap's pool")
        row = swap_frame[never]
        self.assertEqual((float(row["F1"]), float(row["F4"]), float(row["F5"])), (1.0, 1.0, 1.0))
        self.assertAlmostEqual(float(row["Ceiling_Multiplier"]), 1.42, places=9,
                               msg="the uniform default, not another player's multiplier")
        meta =self._swap_runs(h.root)[-1]["metadata"]["projection_carry"]
        self.assertIn(never, meta["not_carried_player_ids"])
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        self.assertIn("T4 Hitter1 [", line)
        self.assertIn("ranked neutral", line)

    def test_S6_a_swap_of_a_swap_carries_the_root_builds_values(self):
        fx = self._world()
        h = fx["h"]
        code, out, err = h._run()
        self.assertEqual(code, 0, err[-1500:])
        first = next((h.root / "outputs" / h.DATE).glob("DKEntries_*lateswap*.csv"))
        first_run = self._swap_runs(h.root)[-1]["run_id"]
        h.parent_file = first
        code, out, err = h._run()
        self.assertEqual(code, 0, err[-1500:])
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        root_id = fx["parent"]["run_id"]
        self.assertIn(f"ENRICHED by carry from run {root_id} (initial_build, 1 hop(s) from the parent",
                      line, "the root-most frame wins over the first swap's own")
        self.assertIn(f"origin {root_id}", line)
        # By identity, not by sort order: run ids are `<second>_<random suffix>`, so two
        # swap runs minted in the same second sort by the random suffix and `[-1]` can
        # be the FIRST swap (a CI flake: chain read [root] instead of [first, root]).
        second = next(r for r in self._swap_runs(h.root) if r["run_id"] != first_run)
        chain = second["metadata"]["projection_carry"]["chain"]
        self.assertEqual([c["run_id"] for c in chain], [first_run, root_id])
        self.assertNotEqual(second["run_id"], first_run)
        self.assertEqual(second["metadata"]["projection_carry"]["source"]["origin_run_id"],
                         fx["parent"]["run_id"])
        root_frame = self._frame_of(h.root, fx["parent"]["run_id"])
        second_frame = self._frame_of(h.root, second["run_id"])
        for pid in (p for p in second_frame if p in root_frame):
            for col in ("Base", "F1", "F4", "F5"):
                self.assertAlmostEqual(float(second_frame[pid][col]), float(root_frame[pid][col]),
                                       places=9, msg=f"{pid} {col}")

    def test_S7_the_tier_is_truthful_both_ways(self):
        ls = LateSwapDeclaredPitcherTests._tool()
        self.assertEqual(ls.swap_projection_tier(None), "proxy")
        self.assertEqual(ls.swap_projection_tier({"applied_count": 0, "non_neutral": {"f1": 3}}), "proxy")
        self.assertEqual(ls.swap_projection_tier(
            {"applied_count": 5, "non_neutral": {"f1": 0, "f4": 0}, "base_restated": 0}), "proxy")
        self.assertEqual(ls.swap_projection_tier(
            {"applied_count": 5, "non_neutral": {"f1": 0, "f4": 1}, "base_restated": 0}), "enriched")
        self.assertEqual(ls.swap_projection_tier(
            {"applied_count": 5, "non_neutral": {}, "base_restated": 2}), "enriched")
        # end to end: a carry that reached rows and moved nothing reads proxy, and says so
        fx = self._world(enriched=False)
        h = fx["h"]
        h._brief()
        flat = {pid: {"F1": 1.0} for pid in fx["ids"].values()}
        info = {"carried": True, "reason": None, "chain": [], "rejected_rows": [],
                "rejected_rows_n": 0,
                "source": {"run_id": "X", "mode": "initial_build", "origin_run_id": "X", "hops": 0,
                           "frame_sha256": "0" * 64, "parent_matches_file": True,
                           "slate_pool_signature": None}}
        with unittest.mock.patch.object(h.ls, "resolve_swap_carry", return_value=(flat, info)):
            code, out, err = h._run()
        self.assertEqual(code, 0, err[-1500:])
        line = next(l for l in out.splitlines() if l.startswith("projection frame:"))
        self.assertIn("UNENRICHED (the carry from run X reached", line)
        self.assertIn("moved none off neutral", line)
        self.assertEqual(self._record(h)["manifest_row"]["projection_tier"], "proxy")

    def test_S8_a_dry_run_prints_the_label_too(self):
        fx = self._world()
        h = fx["h"]
        code, out, err = h._run("--dry-run")
        self.assertEqual(code, 0, err[-1500:])
        self.assertTrue(any(l.startswith("projection frame: ENRICHED") for l in out.splitlines()), out[-800:])

    def test_S9_the_label_reads_only_the_carried_block(self):
        ls = LateSwapDeclaredPitcherTests._tool()
        info = {"carried": False, "reason": "no parent run resolved", "chain": [],
                "source": None, "rejected_rows": [], "rejected_rows_n": 0}
        text = ls.carry_label(info, None)
        self.assertIn("UNENRICHED (no parent run resolved)", text)
        self.assertNotIn("neutral", text.replace("off neutral", ""))
        record = ls.carry_record(info, None, text)
        self.assertEqual((record["carried"], record["tier"]), (False, "proxy"))
        self.assertEqual(ls.carry_notes_clause(None), "")
        self.assertIn("frame unenriched (no parent run resolved)", ls.carry_notes_clause(record))


class ConsensusPairSeatTests(unittest.TestCase):
    """R469 (roadmap Session 138), Ben's rule of 2026-09-30: every Classic
    contest with two or more entries seats at least one lineup on the
    projection's consensus SP pair, differentiated through its bats.

    On 2026-09-29 (1400_4g) the Opener held no Sale + Schlittler lineup: at a
    0.43 pitcher cap on 9 entries both arms sat at the cap of 3, and another
    build under the same caps seated two in the Opener, so the zero was the
    objective's choice, not a cap's. No control asked for the pair. The
    control is a count, resolved per contest from each entry's posture (the
    posture merge is one portfolio dict, so a posture default would let a
    cash contest switch the seat off for everyone), typed through the units
    gate, floored into the pitcher and pair caps on the existing floor path,
    seated by one allocator row per contest, and relaxed and counted rather
    than refused when it cannot be met: an S control never costs the file.
    """

    # -- the pair ------------------------------------------------------------ #

    @staticmethod
    def _arms(*rows):
        return pd.DataFrame([
            {"Player_ID": pid, "Name": pid, "Team": team, "Opponent": "", "Position": "P",
             "Salary": 9000.0, "Game_ID": game, "Base_Projection": base,
             "Ceiling": ceil, "Floor": 5.0, "Excluded": excl, "Locked": False}
            for pid, team, game, base, ceil, excl in rows])

    def test_the_pair_is_the_top_two_arms_by_projection_that_are_not_opponents(self):
        frame = self._arms(("A", "T1", "g1", 20.0, 30.0, False),
                           ("C", "T3", "g2", 19.0, 28.0, False),
                           ("D", "T4", "g2", 10.0, 20.0, False))
        out = ca.consensus_sp_pair(frame)
        self.assertEqual(out["pair"], ["A", "C"])
        self.assertEqual(out["basis"], "Base_Projection")

    def test_opposing_top_two_pair_the_first_with_the_next_non_opponent(self):
        frame = self._arms(("A", "T1", "g1", 20.0, 30.0, False),
                           ("B", "T2", "g1", 19.0, 29.0, False),
                           ("C", "T3", "g2", 18.0, 28.0, False))
        out = ca.consensus_sp_pair(frame)
        self.assertEqual(out["pair"], ["A", "C"])
        self.assertEqual(out["skipped_opponent"], "B")

    def test_an_excluded_arm_is_never_the_pair_and_ties_break_by_ceiling(self):
        frame = self._arms(("A", "T1", "g1", 25.0, 30.0, True),
                           ("X", "T5", "g3", 20.0, 31.0, False),
                           ("C", "T3", "g2", 20.0, 28.0, False))
        self.assertEqual(ca.consensus_sp_pair(frame)["pair"], ["X", "C"])

    def test_fewer_than_two_legal_arms_is_no_pair(self):
        out = ca.consensus_sp_pair(self._arms(("A", "T1", "g1", 20.0, 30.0, False)))
        self.assertIsNone(out["pair"])

    # -- the value, per contest ------------------------------------------------ #

    @staticmethod
    def _reqs(spec):
        out = []
        for contest, posture, n in spec:
            for i in range(n):
                out.append({"entry_id": f"{contest}{i + 1}", "contest_id": contest,
                            "contest_shape": "large_wta", "posture": posture})
        return out

    def test_each_contest_takes_its_own_postures_value(self):
        reqs = self._reqs([("A", "large_gpp", 3), ("B", "cash", 2), ("C", "mme", 1),
                           ("D", "wta_satellite", 2), ("E", "single_entry", 2)])
        self.assertEqual(ca.consensus_pair_seat_demand(reqs),
                         {"A": 1, "B": 0, "C": 0, "D": 1, "E": 0})

    def test_an_override_sets_every_multi_entry_contest_and_fixed_rows_count(self):
        reqs = self._reqs([("A", "large_gpp", 3), ("B", "cash", 2), ("C", "mme", 1)])
        self.assertEqual(
            ca.consensus_pair_seat_demand(
                reqs, {"min_consensus_pair_entries_per_contest": 2},
                fixed_rows_by_contest={"C": 1}),
            {"A": 2, "B": 2, "C": 2})
        self.assertEqual(ca.consensus_pair_seat_demand(reqs, fixed_rows_by_contest={"C": 1})["C"], 1,
                         "a contest's untouched rows count toward the two-entry threshold")

    def test_the_count_is_typed_through_the_units_gate(self):
        for bad in (1.5, True, -1, "2", float("nan")):
            with self.assertRaises(ValueError, msg=repr(bad)):
                ca.assert_count_control(bad, key="min_consensus_pair_entries_per_contest")
        self.assertEqual(ca.assert_count_control(2.0), 2)
        postures = {"900": {"posture": "large_gpp", "contest_shape": "large_wta",
                            "posture_source": "test"}}
        with self.assertRaisesRegex(ValueError, "min_consensus_pair_entries_per_contest"):
            epi._merged_controls_for_build(
                postures, {"min_consensus_pair_entries_per_contest": 0.5})
        merged = epi._merged_controls_for_build(
            postures, {"min_consensus_pair_entries_per_contest": 2.0})
        self.assertEqual(merged["min_consensus_pair_entries_per_contest"], 2)

    def test_build_slate_refuses_a_fractional_count_at_exit_4(self):
        runner = LostWindowFlagValueTests("test_an_unknown_posture_refuses_before_the_pool_build")
        runner.setUp()
        self.addCleanup(runner.tmp.cleanup)
        code, payload, reached = runner._run(
            ["--controls-override", '{"min_consensus_pair_entries_per_contest": 0.5}'])
        self.assertEqual(code, 4)
        self.assertFalse(reached)
        self.assertEqual(payload.get("status"), "controls_override_bad_units")
        self.assertEqual(payload["controls"][0]["control"],
                         "min_consensus_pair_entries_per_contest")

    # -- the allocator row ---------------------------------------------------- #

    @staticmethod
    def _bank(pair_lineups=3, pair=("PA", "PB")):
        out = []
        for i in range(8):
            roster = [f"S{i}a", f"S{i}b"] + [f"H{i}_{j}" for j in range(8)]
            out.append(candidate(f"top{i}", roster, 100 - i))
        for i in range(pair_lineups):
            roster = [pair[0], pair[1]] + [f"Q{i}_{j}" for j in range(8)]
            out.append(candidate(f"pair{i}", roster, 50 - i))
        return out

    @staticmethod
    def _seated(result, pair=("PA", "PB")):
        by_contest = defaultdict(int)
        for row in result["assignments"]:
            if set(pair) <= set(row["lineup_ids"]):
                by_contest[row["contest_id"]] += 1
        return dict(by_contest)

    def test_the_row_seats_one_pair_lineup_in_each_multi_entry_contest(self):
        reqs = self._reqs([("A", "large_gpp", 3), ("B", "cash", 2), ("C", "mme", 1)])
        plain = select_and_assign_entries(self._bank(), reqs, {})
        self.assertTrue(plain["passed"], plain.get("errors"))
        self.assertEqual(self._seated(plain), {}, "the objective alone never picks the pair here")
        seated = select_and_assign_entries(self._bank(), reqs, {"consensus_sp_pair": ["PA", "PB"]})
        self.assertTrue(seated["passed"], seated.get("errors"))
        self.assertEqual(self._seated(seated), {"A": 1})
        report = seated["consensus_pair_seats"]
        self.assertEqual(report["status"], "applied")
        self.assertEqual(report["required_by_contest"], {"A": 1, "B": 0, "C": 0})
        self.assertEqual(report["seated_by_contest"], {"A": 1, "B": 0, "C": 0})
        self.assertEqual(report["relaxations"], 0)

    def test_a_contest_whose_untouched_row_holds_the_pair_needs_no_new_seat(self):
        reqs = self._reqs([("A", "large_gpp", 2)])
        fixed = {"row_count": 1, "entry_ids": ["A9"], "rosters": [],
                 "player_counts": {}, "pitcher_counts": {}, "primary_stack_counts": {},
                 "sp_pair_counts": {}, "game_counts": {}, "team_counts": {},
                 "signatures_by_contest": {"A": [sorted(["PA", "PB"] + [f"Z{j}" for j in range(8)])]},
                 "stacks_derived": False}
        out = select_and_assign_entries(self._bank(), reqs, {"consensus_sp_pair": ["PA", "PB"]},
                                        fixed_exposure=fixed)
        self.assertTrue(out["passed"], out.get("errors"))
        self.assertEqual(self._seated(out), {})
        self.assertEqual(out["consensus_pair_seats"]["fixed_on_pair_by_contest"], {"A": 1})

    def test_no_pair_lineup_in_the_bank_relaxes_and_counts_and_still_delivers(self):
        reqs = self._reqs([("A", "large_gpp", 3)])
        out = select_and_assign_entries(self._bank(pair_lineups=0), reqs,
                                        {"consensus_sp_pair": ["PA", "PB"]})
        self.assertTrue(out["passed"], out.get("errors"))
        report = out["consensus_pair_seats"]
        self.assertEqual(report["relaxations"], 1)
        self.assertEqual(report["relaxed"][0]["contest_id"], "A")
        self.assertIn("no compatible candidate on the pair", report["relaxed"][0]["reason"])

    def test_a_proven_infeasible_seat_steps_the_ladder_and_is_counted(self):
        """Two contests each need a seat and the bank holds one pair lineup that
        an operator's reuse cap lets be used once: the joint MILP is proven
        infeasible, the seat steps (after the five-stack quota, before the
        primary-stack floor) and the file still delivers."""
        reqs = self._reqs([("A", "large_gpp", 2), ("B", "large_gpp", 2)])
        out = select_and_assign_entries(self._bank(pair_lineups=1), reqs,
                                        {"consensus_sp_pair": ["PA", "PB"],
                                         "max_candidate_reuse": 1})
        self.assertTrue(out["passed"], out.get("errors"))
        report = out["consensus_pair_seats"]
        self.assertEqual(report["status"], "relaxed_by_ladder")
        self.assertEqual(report["relaxations"], 1)
        self.assertEqual(report["relaxation_steps"][0]["trigger"],
                         "proven_infeasible_with_consensus_pair_seats")

    def test_the_seat_goes_to_the_contests_projection_sleeve_entries(self):
        entries = [{"entry_id": eid, "contest_id": "A"} for eid in ("a1", "a2", "a3")]
        applied = {"status": "applied",
                   "sleeve_by_entry": {"a1": "salary_only", "a2": "projection",
                                       "a3": "chalk_fails"}}
        self.assertEqual(ca._consensus_pair_eligible_entries([0, 1, 2], entries, applied), [1])
        self.assertEqual(ca._consensus_pair_eligible_entries([0, 1, 2], entries, {"status": "off"}),
                         [0, 1, 2])
        none_in_projection = {"status": "applied",
                              "sleeve_by_entry": {"a1": "salary_only", "a2": "chalk_fails",
                                                  "a3": "environment"}}
        self.assertEqual(ca._consensus_pair_eligible_entries([0, 1, 2], entries,
                                                             none_in_projection), [0, 1, 2])

    def test_the_prefilter_keeps_the_pair_lineups_the_objective_ranks_last(self):
        """A bank past the prefilter's keep target (max(6E, 40)) is cut by score,
        and a seat exists because the pair's lineups do not win on score: the
        reserve keeps them, or the seat would relax on a lineup the caller
        handed in."""
        bank = []
        for i in range(60):
            roster = [f"S{i}a", f"S{i}b"] + [f"H{i}_{j}" for j in range(8)]
            bank.append(candidate(f"top{i}", roster, 200 - i))
        for i in range(2):
            bank.append(candidate(f"pair{i}", ["PA", "PB"] + [f"Q{i}_{j}" for j in range(8)], 1 - i))
        # Two seats in one contest need two DISTINCT pair lineups (the
        # same-contest duplicate ban), and the prefilter's own coverage loop
        # keeps only one representative per SP pair: the reserve is the rest.
        reqs = self._reqs([("A", "large_gpp", 3)])
        out = select_and_assign_entries(bank, reqs, {"consensus_sp_pair": ["PA", "PB"],
                                                     "min_consensus_pair_entries_per_contest": 2})
        self.assertTrue(out["passed"], out.get("errors"))
        self.assertTrue(out["allocation_solver_report"]["candidate_prefilter"]["applied"])
        self.assertEqual(self._seated(out), {"A": 2})
        self.assertEqual(out["consensus_pair_seats"]["relaxations"], 0)

    def test_the_seat_steps_after_the_quota_and_before_the_floor(self):
        src = Path(ca.__file__).read_text(encoding="utf-8")
        q = src.index("proven_infeasible_with_five_stack_quota")
        s = src.index("proven_infeasible_with_consensus_pair_seats")
        f = src.index("proven_infeasible_with_floor")
        self.assertLess(q, s)
        self.assertLess(s, f)

    def test_the_seat_is_ladder_relaxed_and_a_never_relax_on_it_is_refused(self):
        self.assertIn("min_consensus_pair_entries_per_contest", ca.LADDER_RELAXED_CONTROLS)
        from mlb_engine.pipeline import deadline_governor as dg
        self.assertIn("min_consensus_pair_entries_per_contest", dg.NEVER_RELAX_NOT_HONOURED)

    # -- feasibility: the pair, the demand, the cap floors ---------------------- #

    @staticmethod
    def _slate():
        rows = []
        pid = 70000
        for g in range(5):
            for side, team in enumerate((f"T{2 * g + 1}", f"T{2 * g + 2}")):
                opp = f"T{2 * g + 2 - side}"
                game = f"T{2 * g + 1}@T{2 * g + 2}"
                pid += 1
                rows.append({"Player_ID": str(pid), "Name": f"P_{team}", "Team": team,
                             "Opponent": opp, "Position": "P", "Salary": 9000.0,
                             "Game_ID": game, "Base_Projection": 30.0 - pid % 100,
                             "Floor": 10.0, "Ceiling": 40.0 - pid % 100,
                             "Excluded": False, "Locked": False})
                for pos in ("C", "1B", "2B", "3B", "SS", "OF", "OF", "OF"):
                    pid += 1
                    rows.append({"Player_ID": str(pid), "Name": f"{team}_{pos}_{pid}",
                                 "Team": team, "Opponent": opp, "Position": pos,
                                 "Salary": 3500.0, "Game_ID": game,
                                 "Base_Projection": 8.0, "Floor": 4.0, "Ceiling": 12.0,
                                 "Excluded": False, "Locked": False})
        return pd.DataFrame(rows)

    def _feasibility(self, spec):
        reqs = self._reqs(spec)
        postures = {c: {"posture": p, "contest_shape": "large_wta", "posture_source": "test"}
                    for c, p, _ in spec}
        return postures, reqs, epi._slate_feasibility(postures, reqs, self._slate())

    def test_slate_feasibility_names_the_pair_and_floors_both_caps_to_the_seats(self):
        _, _, info = self._feasibility([(c, "large_gpp", 2) for c in "ABCD"])
        self.assertTrue(info["available"], info.get("note"))
        self.assertEqual(info["consensus_sp_pair"], ["70001", "70019"])
        self.assertEqual(info["consensus_pair_seats_required"], 4)
        self.assertEqual(info["floor_sp_pair_repetition"], 4, "ceil(8/40)=1 raised to the 4 seats")
        self.assertEqual(info["floor_pitcher_exposure_count"], 4, "ceil(16/10)=2 raised to 4")
        _, _, cash = self._feasibility([(c, "cash", 2) for c in "ABCD"])
        self.assertEqual(cash["consensus_pair_seats_required"], 0)
        self.assertEqual(cash["floor_sp_pair_repetition"], 1)

    def test_the_merge_floors_the_caps_and_never_relax_holds_them(self):
        postures, _, info = self._feasibility([(c, "large_gpp", 2) for c in "ABCD"])
        floors = epi.feasibility_floors_from(info)
        prov: dict = {}
        merged = epi._merged_controls_for_build(
            postures, None, feasibility_floors=floors, provenance_out=prov)
        self.assertGreaterEqual(merged["max_sp_pair_repetition"], 4)
        self.assertEqual(prov["max_sp_pair_repetition"], "derived_floor")
        held = epi._merged_controls_for_build(
            postures, None, feasibility_floors=floors,
            never_relax=frozenset({"max_sp_pair_repetition"}))
        self.assertLess(held["max_sp_pair_repetition"], 4)
        report = epi._feasibility_report(info, {**held, "consensus_sp_pair": info["consensus_sp_pair"]})
        check = next(c for c in report["checks"] if c["name"] == "consensus_pair_seat_capacity")
        self.assertTrue(check["passed"], "advisory: never a slate impossibility")
        self.assertIsNone(check["remedy"])
        self.assertNotIn("remedy_typed", check)
        self.assertEqual([s["control"] for s in check["seat_shortfall"]],
                         ["max_sp_pair_repetition"])
        self.assertIn("relaxes the seat", check["note"])
        self.assertEqual(ca.failing_feasibility_checks(report["checks"]),
                         [c for c in report["checks"] if c.get("passed") is False
                          and c["name"] != "consensus_pair_seat_capacity"])
        report_ok = epi._feasibility_report(info, {**merged, "consensus_sp_pair": info["consensus_sp_pair"]})
        ok = next(c for c in report_ok["checks"] if c["name"] == "consensus_pair_seat_capacity")
        self.assertEqual(ok["seat_shortfall"], [])

    def test_an_operator_pair_is_the_pair_the_sliced_bank_builds_and_a_bad_one_is_ignored(self):
        bs = LostWindowFlagValueTests._module()
        frame = self._slate()
        self.assertEqual(bs.sliced_door_consensus_pair({"consensus_sp_pair": ["70010", "70028"]}, frame),
                         ["70010", "70028"])
        self.assertEqual(bs.sliced_door_consensus_pair({"consensus_sp_pair": "7001070028"}, frame),
                         ca.consensus_sp_pair(frame)["pair"])
        out = select_and_assign_entries(self._bank(), self._reqs([("A", "large_gpp", 2)]),
                                        {"consensus_sp_pair": "PAPB"})
        self.assertTrue(out["passed"], out.get("errors"))
        self.assertNotIn("consensus_pair_seats", out, "a malformed pair seats nothing")

    def test_the_pair_rides_the_controls_and_survives_the_run_record(self):
        _, _, info = self._feasibility([("A", "large_gpp", 2)])
        controls = epi.attach_consensus_pair({"max_sp_pair_repetition": 2}, info)
        self.assertEqual(controls["consensus_sp_pair"], info["consensus_sp_pair"])
        self.assertEqual(epi.recorded_controls(controls)["consensus_sp_pair"],
                         info["consensus_sp_pair"])
        kept = epi.attach_consensus_pair({"consensus_sp_pair": ["X", "Y"]}, info)
        self.assertEqual(kept["consensus_sp_pair"], ["X", "Y"], "an explicit pair wins")

    # -- the bank ------------------------------------------------------------- #

    def test_the_pair_bank_slice_pins_both_arms_and_differs_in_the_bats(self):
        frame = diverse_projection_frame()
        arms = frame[frame["Position"] == "P"].set_index("Team")["Player_ID"]
        pair = [str(arms["T1"]), str(arms["T3"])]
        with tempfile.TemporaryDirectory() as tmp:
            cache = bank_cache.BankCache(Path(tmp) / "bank.json")
            report = epi.build_consensus_pair_jobs(cache, frame, pair=pair, seats=2,
                                                   time_budget_s=20.0)
            self.assertGreaterEqual(report["built"], 2, report)
            cands = cache.as_candidates(frame, requested_n=4)
        on_pair = [c for c in cands if set(pair) <= {str(x) for x in (c.get("sp_ids") or [])}]
        self.assertGreaterEqual(len(on_pair), 2)
        self.assertGreater(len({tuple(sorted(c["player_ids"])) for c in on_pair}), 1)
        self.assertEqual(epi.build_consensus_pair_jobs(None, frame, pair=None, seats=2,
                                                       time_budget_s=1.0)["attempted"], False)

    # -- the brief -------------------------------------------------------------- #

    def test_the_brief_exposure_block_names_the_pair_and_the_seats(self):
        bs = LostWindowFlagValueTests._module()
        block = bs.consensus_pair_exposure({"consensus_pair_seats": {
            "status": "applied", "pair": ["PA", "PB"], "basis": "Base_Projection",
            "required_by_contest": {"A": 1, "B": 0}, "seated_by_contest": {"A": 1, "B": 0},
            "relaxed": [], "relaxations": 0}}, names={"PA": "Sale", "PB": "Schlittler"})
        self.assertEqual(block["pair_names"], ["Sale", "Schlittler"])
        self.assertIn("construction rule", block["label"])
        line = bs.format_consensus_pair_line(block)
        self.assertIn("Sale + Schlittler", line)
        self.assertIn("A 1/1", line)
        self.assertIn("UNAVAILABLE", bs.format_consensus_pair_line(None))


class LateSwapConsensusPairGuardTests(unittest.TestCase):
    """R469, the swap's half of Ben's rule: a late swap never removes the last
    consensus-pair lineup in a contest without `--accept-downgrade`.

    The allocator's seat row does not run inside a swap (`run_late_swap`
    builds requirements that carry no posture), so the guard is the post-solve
    comparison of the parent's file against the swapped one, over the pair the
    PARENT recorded in its controls. The 1400_4g removal was a hand edit that
    never passed through here; R472's printed verdict covers that path.
    """

    PAIR = ["P1", "P2"]

    @staticmethod
    def _tool():
        return LateSwapDeclaredPitcherTests._tool()

    def _rosters(self):
        on = self.PAIR + [f"H{j}" for j in range(8)]
        off = ["P3", "P4"] + [f"H{j}" for j in range(8)]
        parent = {"e1": on, "e2": off, "e3": on, "e4": off}
        contest = {"e1": "A", "e2": "A", "e3": "B", "e4": "B"}
        return parent, contest, on, off

    def test_a_contest_that_loses_its_last_pair_lineup_is_named(self):
        ls = self._tool()
        parent, contest, on, off = self._rosters()
        after = {**parent, "e1": off}
        self.assertEqual(ls.consensus_pair_seats_lost(parent, after, contest, self.PAIR),
                         [{"contest_id": "A", "entries": ["e1"]}])
        self.assertEqual(ls.consensus_pair_seats_lost(parent, parent, contest, self.PAIR), [])
        moved = {**parent, "e1": off, "e2": on}
        self.assertEqual(ls.consensus_pair_seats_lost(parent, moved, contest, self.PAIR), [],
                         "the contest still holds one: the seat moved, it was not lost")
        self.assertEqual(ls.consensus_pair_seats_lost(parent, after, contest, None), [])

    def _guard(self, accept, pair=PAIR):
        ls = self._tool()
        parent, contest, on, off = self._rosters()
        after = {**parent, "e1": off}
        downgraded: list = []
        args = types.SimpleNamespace(accept_downgrade=accept)
        out, err = io.StringIO(), io.StringIO()
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            code = ls.consensus_pair_guard(args, pair, parent, after, contest, downgraded)
        return code, downgraded, out.getvalue(), err.getvalue()

    def test_the_guard_refuses_at_exit_3_naming_the_entry(self):
        code, downgraded, out, err = self._guard(accept=False)
        self.assertEqual(code, 3)
        self.assertIn("contest A: parent entries e1", err)
        self.assertIn("--accept-downgrade", err)
        self.assertEqual(downgraded, [])

    def test_accept_downgrade_takes_it_and_labels_the_file_review_grade(self):
        code, downgraded, out, err = self._guard(accept=True)
        self.assertIsNone(code)
        self.assertEqual(len(downgraded), 1)
        self.assertIn("last consensus-pair lineup removed", downgraded[0])
        ls = self._tool()
        self.assertEqual(ls.swap_certification({"workflow_valid": True}, downgraded),
                         ls.DOWNGRADE_LABEL)

    def test_a_parent_with_no_recorded_pair_says_so_and_never_refuses(self):
        code, downgraded, out, err = self._guard(accept=False, pair=None)
        self.assertIsNone(code)
        self.assertIn("the parent recorded no consensus pair", out)

    def test_main_runs_the_guard_on_every_swap(self):
        """R468's harness: a real swap reaches the guard and prints its line."""
        harness = LateSwapDeclaredPitcherTests("test_the_grammar_is_build_slates_own_parser")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        harness._brief()
        code, out, err = harness._run()
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn("chalk-core seat: the parent recorded no consensus pair", out)
        # And main honours what the guard decides: a refusal is the swap's exit.
        seen = []
        harness.ls.consensus_pair_guard = lambda *a, **k: (seen.append(a[1]), 3)[1]
        code, out, err = harness._run()
        self.assertEqual(code, 3)
        self.assertEqual(len(seen), 1)


class DeclaredArmWorkloadTests(unittest.TestCase):
    """R470 (roadmap Session 139). A declared bulk or opener arm is projected
    on a starter's workload no longer.

    Every pitcher, whatever his role, was projected off season APPG (Base =
    APPG, restated by xwOBA, times F1 and F5), so a declared
    `viable_bulk_or_alt_sp` arm carried a starter's workload into the
    objective. On 2026-09-29 (1400_4g) the certified file held four P slots on
    declared bulk arms (Painter x2, Fedde, Imai), and the retro records 0 from
    each; Imai's APPG included his July starts. A labeled workload prior now
    scales the arm's Base by expected innings over a starter's reference,
    before `build_projections`, so Floor and Ceiling move together. Never an
    exclusion: the arm stays in the legal pool.
    """

    @staticmethod
    def _bs():
        return LostWindowFlagValueTests._module()

    # -- the grammar ---------------------------------------------------------- #

    def test_the_options_grammar_and_the_role_contract(self):
        bs = self._bs()
        values = ["1=viable_bulk_or_alt_sp:ip=2.5", "2", '3=declared_probable_sp:ip="4"']
        self.assertEqual(bs.parse_declared_pitchers(values),
                         {"1": "viable_bulk_or_alt_sp", "2": "declared_probable_sp",
                          "3": "declared_probable_sp"},
                         "the {id: role} contract every reader relies on is unchanged")
        options = bs.parse_declared_pitcher_options(values)
        self.assertEqual(options["1"], {"role": "viable_bulk_or_alt_sp", "ip": 2.5,
                                        "evidence": None})
        self.assertEqual(options["3"]["ip"], 4.0)
        self.assertEqual(bs.declared_pitcher_workload(values), {"1": 2.5, "3": 4.0})
        for bad in ("1=viable_bulk_or_alt_sp:ip=abc", "1=viable_bulk_or_alt_sp:ip=0",
                    "1=viable_bulk_or_alt_sp:ip=inf", "1=viable_bulk_or_alt_sp:ip=nan",
                    "1=viable_bulk_or_alt_sp:ip=2:ip=4", "1=viable_bulk_or_alt_sp:foo=1",
                    '1=viable_bulk_or_alt_sp:ip="2', "1:ip=3"):
            with self.assertRaises(bs.CliValueError, msg=bad):
                bs.parse_declared_pitcher_options([bad])
        # R471 added the evidence note (DeclaredPitcherEvidenceTests).
        self.assertEqual(
            bs.parse_declared_pitcher_options(['1=declared_probable_sp:evidence="K line"'])["1"],
            {"role": "declared_probable_sp", "ip": None, "evidence": "K line"})

    def test_an_option_before_the_role_refuses_at_exit_4_before_staging(self):
        """`ID:ip=3` would read as the id `ID:ip`, skipped off the salary file,
        so the arm would not be declared at all. Refused through the one
        `validate_cli_values` site, like every other bad flag value."""
        harness = LostWindowFlagValueTests(
            "test_a_declared_pitcher_with_no_id_refuses_before_the_pool_build")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        harness._assert_refused(["--declare-pitcher", "43706740:ip=3"],
                                "--declare-pitcher", "options follow the role")

    def test_preflight_reads_the_role_without_the_suffix(self):
        sys.path.insert(0, str(REPO / "tools"))
        import preflight_upload
        self.assertEqual(
            preflight_upload.parse_declared_pitcher_args(
                ["43321370=viable_bulk_or_alt_sp:ip=3", '44321112=declared_probable_sp:ip="2.5"']),
            {"43321370": "viable_bulk_or_alt_sp", "44321112": "declared_probable_sp"})
        with self.assertRaises(ValueError, msg="read as role '3' before this fix"):
            preflight_upload.parse_declared_pitcher_args(["43321370:ip=3"])

    # -- the prior ----------------------------------------------------------- #

    def _pool(self, declared, workload=None):
        with tempfile.TemporaryDirectory() as tmp:
            salary = Path(tmp) / "salary.csv"
            pool_salary_csv(salary)
            with salary.open(newline="", encoding="utf-8") as fh:
                ids = {row[2]: row[3] for row in list(csv.reader(fh))[1:]}
            pool = lda.build_slate_pool(str(salary), pool_lineups_feed(),
                                        declared_pitchers={ids[k]: v for k, v in declared.items()},
                                        declared_workload=({ids[k]: v for k, v in workload.items()}
                                                           if workload else None))
            frame, _ = epi._assemble_projection_frame(
                str(salary), pool["run_slate_kwargs"]["projection_rows"],
                "emergency_proxy", None, None, None)
        return ids, pool, frame

    def test_a_declared_bulk_arm_is_scaled_to_the_bulk_prior(self):
        ids, pool, frame = self._pool({"T1 Pen1": "viable_bulk_or_alt_sp"})
        _ids, _pool0, plain = self._pool({"T1 Pen1": "declared_probable_sp"})
        pen = ids["T1 Pen1"]
        row = frame.set_index("Player_ID").loc[pen]
        base = plain.set_index("Player_ID").loc[pen]
        factor = lda.BULK_ARM_EXPECTED_IP / lda.STARTER_REFERENCE_IP
        self.assertAlmostEqual(row["Workload_Factor"], factor)
        for col in ("Base", "Floor", "Ceiling"):
            self.assertAlmostEqual(row[col], base[col] * factor, places=6, msg=col)
        self.assertGreaterEqual(row["Ceiling"], row["Floor"])
        self.assertIn(pen, set(frame["Player_ID"]), "a prior, never an exclusion")
        self.assertIn("workload_prior: 0.545", row["Notes"], "the row says why Base moved")
        self.assertNotIn("workload_prior", base["Notes"])
        listed = {a["player_id"]: a for a in pool["pool_report"]["declared_arm_workload"]}
        self.assertEqual(listed[pen]["ip_source"], "bulk_default")
        self.assertAlmostEqual(listed[pen]["factor"], factor)

    def test_an_explicit_ip_overrides_any_role_and_is_capped_at_a_starter(self):
        ids, pool, frame = self._pool({"T1 Pen1": "declared_probable_sp", "T2 Pen1": "viable_bulk_or_alt_sp"},
                                      workload={"T1 Pen1": 4.0, "T2 Pen1": 9.0})
        rows = frame.set_index("Player_ID")
        self.assertAlmostEqual(rows.loc[ids["T1 Pen1"], "Workload_Factor"],
                               4.0 / lda.STARTER_REFERENCE_IP)
        self.assertAlmostEqual(rows.loc[ids["T2 Pen1"], "Workload_Factor"], 1.0,
                               msg="an ip above a starter's never inflates an arm")
        listed = {a["player_id"]: a for a in pool["pool_report"]["declared_arm_workload"]}
        self.assertEqual(listed[ids["T1 Pen1"]]["ip_source"], "--declare-pitcher ip=")
        self.assertEqual((listed[ids["T2 Pen1"]]["ip"], listed[ids["T2 Pen1"]]["factor"]), (9.0, 1.0),
                         "the brief records the typed innings and the capped factor")

    def test_a_bare_declaration_and_every_undeclared_row_are_untouched(self):
        ids, pool, frame = self._pool({"T1 Pen1": "declared_probable_sp"})
        self.assertNotIn("Workload_Factor", frame.columns,
                         "no declared arm owes a factor, so the frame is byte-identical")
        self.assertEqual(pool["pool_report"]["declared_arm_workload"][0]["factor"], 1.0)

    def test_a_declared_id_that_is_not_p_eligible_is_never_scaled(self):
        """A hitter's id pasted as a bulk arm must not cut his hitting Base;
        typed innings for an id nothing declared reach no row. Both named."""
        ids, pool, frame = self._pool({"T1 Hitter1": "viable_bulk_or_alt_sp"},
                                      workload={"T3 Pen2": 2.0})
        _ids, _p, plain = self._pool({})
        hitter = ids["T1 Hitter1"]
        self.assertNotIn("Workload_Factor", frame.columns)
        self.assertAlmostEqual(frame.set_index("Player_ID").loc[hitter, "Base"],
                               plain.set_index("Player_ID").loc[hitter, "Base"])
        listed = {a["player_id"]: a for a in pool["pool_report"]["declared_arm_workload"]}
        self.assertEqual((listed[hitter]["factor"], listed[hitter]["ip_source"]),
                         (1.0, "not_p_eligible"))
        warnings = " | ".join(pool["pool_report"]["warnings"])
        self.assertIn(f"({hitter}): declared as viable_bulk_or_alt_sp, but not P-eligible", warnings)
        self.assertIn(f"ip= for {ids['T3 Pen2']}, which is not a declared pitcher", warnings)

    def test_the_printed_line_names_each_factored_arm(self):
        ids, pool, _frame = self._pool({"T1 Pen1": "viable_bulk_or_alt_sp", "T2 Pen1": "declared_probable_sp"})
        lines = lda.workload_prior_lines(pool["pool_report"])
        self.assertEqual(lines, [f"workload prior: T1 Pen1 ({ids['T1 Pen1']}, viable_bulk_or_alt_sp) "
                                 f"ip 3 of 5.5 -> x0.545 (bulk_default; a labeled prior)"],
                         "a starter's workload prints nothing")

    def test_the_baseline_brief_records_the_typed_innings(self):
        """A swap of a delivered baseline reads that brief (R468's resolver),
        so the typed innings ride it as they ride the enhanced brief."""
        bs = self._bs()
        with tempfile.TemporaryDirectory() as tmp:
            out = Path(tmp) / "outputs" / "2026-07-29"
            out.mkdir(parents=True)
            delivered = out / "DKEntries_1910_6g_BASELINE_r1.csv"
            delivered.write_text("x\n", encoding="utf-8")
            args = types.SimpleNamespace(date="2026-07-29", declare_pitcher=[
                "43706740=viable_bulk_or_alt_sp:ip=2.5"])
            got = bs._write_baseline_brief(
                args, REPO / "tests" / "fixtures" / "slates" / "DKSalaries_frozen_2026-07-29.csv",
                {"path": str(delivered), "sha256": "ab", "run_id": "r1"})
            self.assertTrue(got["written"], got)
            brief = json.loads(Path(got["path"]).read_text(encoding="utf-8"))
        self.assertEqual(brief["declared_pitcher_workload"], {"43706740": 2.5})
        self.assertEqual(brief["declared_pitchers"], {"43706740": "viable_bulk_or_alt_sp"})

    def test_run_classic_records_the_factors_and_hands_them_to_the_solve(self):
        """Through `run_classic` with the real pool build (only `run_slate` is
        faked): the prior reaches the rows the solve is handed, and the
        payload lists every declared arm with its factor."""
        harness = DeadlineGovernorWiringTests("test_the_anti_correlation_flag_reaches_the_controls_the_validator_grades")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        bulk, typed = "43706740", "43706750"
        code, payload, _calls, _err = harness._run(30, args_overrides={"declare_pitcher": [
            f"{bulk}=viable_bulk_or_alt_sp", f"{typed}=declared_probable_sp:ip=2.75"]})
        self.assertEqual(code, 3)
        listed = {a["player_id"]: a for a in payload["declared_arm_workload"]}
        self.assertEqual((listed[bulk]["ip"], listed[bulk]["ip_source"]),
                         (lda.BULK_ARM_EXPECTED_IP, "bulk_default"))
        self.assertAlmostEqual(listed[typed]["factor"], 2.75 / lda.STARTER_REFERENCE_IP)
        self.assertEqual(payload["declared_pitcher_workload"], {typed: 2.75})
        self.assertEqual(payload["declared_pitchers"],
                         {bulk: "viable_bulk_or_alt_sp", typed: "declared_probable_sp"})
        rows = {str(r.get("Player_ID") or r.get("ID")): r
                for r in harness.solve_kwargs[0]["projection_rows"]}
        self.assertAlmostEqual(rows[bulk]["Workload_Factor"],
                               lda.BULK_ARM_EXPECTED_IP / lda.STARTER_REFERENCE_IP)
        self.assertAlmostEqual(rows[typed]["Workload_Factor"], 2.75 / lda.STARTER_REFERENCE_IP)

    # -- late swap carries the typed innings (R468's record) ------------------ #

    def test_a_late_swap_inherits_the_parents_typed_innings(self):
        harness = LateSwapDeclaredPitcherTests("test_the_grammar_is_build_slates_own_parser")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        out_dir = harness.root / "outputs" / harness.DATE
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / "build_brief_test.json").write_text(json.dumps({
            "run_id": harness.parent["run_id"],
            "delivered_sha256": sha256_file(harness.parent_file),
            "declared_pitchers": harness.declared,
            "declared_pitcher_workload": {harness.pen: 2.0},
        }), encoding="utf-8")
        code, out, err = harness._run()
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn(f"declared workload: {harness.pen} ip=2.0", out)
        self.assertIn(f"{harness.pen}, {harness.declared[harness.pen]}) ip 2 of 5.5 -> x0.364 "
                      f"(--declare-pitcher ip=; a labeled prior)", out,
                      "the swap prints the prior where its pool is reviewed")
        manifests = [json.loads(p.read_text()) for p in (harness.root / "runs").glob("*/manifest.json")]
        swap = next(m for m in manifests if m.get("mode") == "late_swap")
        self.assertEqual(swap["metadata"]["declared_pitcher_workload"], {harness.pen: 2.0})
        frame = pd.read_csv(harness.root / "runs" / swap["run_id"] / "final" / "projections.csv",
                            dtype={"Player_ID": str})
        self.assertAlmostEqual(
            float(frame.set_index("Player_ID").loc[harness.pen, "Workload_Factor"]),
            2.0 / lda.STARTER_REFERENCE_IP, msg="the swap's pool applied the typed innings")

    def test_a_swap_that_re_declares_an_arm_drops_the_parents_innings(self):
        """The parent typed ip=2 on a bulk arm; the operator re-declares him a
        starter on the swap with no ip. His new role's prior applies (a
        starter's workload), never the parent's 2 innings."""
        harness = LateSwapDeclaredPitcherTests("test_the_grammar_is_build_slates_own_parser")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        out_dir = harness.root / "outputs" / harness.DATE
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / "build_brief_test.json").write_text(json.dumps({
            "run_id": harness.parent["run_id"],
            "delivered_sha256": sha256_file(harness.parent_file),
            "declared_pitchers": harness.declared,
            "declared_pitcher_workload": {harness.pen: 2.0},
        }), encoding="utf-8")
        code, out, err = harness._run("--declare-pitcher", f"{harness.pen}=declared_probable_sp")
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn("declared workload: none typed", out)
        self.assertIn(f"re-declared here without ip, so the role's own prior: {harness.pen}", out)
        manifests = [json.loads(p.read_text()) for p in (harness.root / "runs").glob("*/manifest.json")]
        swap = next(m for m in manifests if m.get("mode") == "late_swap")
        self.assertEqual(swap["metadata"]["declared_pitcher_workload"], {})
        frame = pd.read_csv(harness.root / "runs" / swap["run_id"] / "final" / "projections.csv",
                            dtype={"Player_ID": str})
        self.assertNotIn("Workload_Factor", frame.columns, "a starter's workload stamps nothing")

    def test_the_swap_workload_resolver_merges_and_drops_bad_values(self):
        harness = LateSwapDeclaredPitcherTests("test_the_grammar_is_build_slates_own_parser")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        harness._brief()
        from mlb_engine.swap.late_swap_manager import resolve_parent_run
        parent = dict(resolve_parent_run(harness.root / "runs", harness.parent_file))
        parent["manifest"] = {**parent["manifest"], "metadata": {
            **(parent["manifest"].get("metadata") or {}),
            "declared_pitchers": {}, "declared_pitcher_workload": {"111": 2.5, "abc": 3.0, "222": -1}}}
        merged, note = harness.ls.resolve_swap_declared_workload(
            harness.root, harness.DATE, parent, {"333": 4.0})
        self.assertEqual(merged, {"111": 2.5, "333": 4.0})
        self.assertIn("parent swap run", note)
        self.assertIn("dropped, not a DK player id with positive innings: 222, abc", note)
        parent["manifest"]["metadata"]["declared_pitcher_workload"] = {"111": 2.5, "444": 2.0}
        merged, note = harness.ls.resolve_swap_declared_workload(
            harness.root, harness.DATE, parent, {"333": 4.0},
            redeclared={"111": "declared_probable_sp", "333": "viable_bulk_or_alt_sp"})
        self.assertEqual(merged, {"333": 4.0, "444": 2.0},
                         "an arm re-declared without ip takes its new role's prior, not the parent's number")
        self.assertIn("re-declared here without ip, so the role's own prior: 111", note)


class DeclaredPitcherEvidenceTests(unittest.TestCase):
    """R471 (roadmap Session 140). A declaration over DK's `PO` tag carries
    the operator's evidence.

    R104 bars a DK `Starting=PO` arm from pitcher slots and names a
    declaration as the way past, so the operator's word alone overrode DK's
    opener tag. On 2026-09-29 (1400_4g) Luzardo was `PO`; the feed probables
    and the headlines named him the starter, the session declared him, the
    certified file rostered him in 3 of 9, and he opened (a strikeout line of
    2.5 against Sale's 7.5). On Classic a declaration whose salary `Starting`
    is `PO` now carries `:evidence="..."`, or `validate_cli_values` refuses at
    exit 4 `cli_value_invalid` naming the arm. A validity wall: no flag skips
    it. The note is the operator's assertion, recorded in the brief, never a
    correction of DK's tag.

    The fixture is the vendored 1910_6g salary file, where Yohan Ramirez
    (43711655, PIT) is `PO`, Nolan McLean (43711180) `SP` and Hunter Barco
    (43711603) `PLR`.
    """

    SALARY = REPO / "tests" / "fixtures" / "slates" / "DKSalaries_1910_6g_frozen_2026-07-30.csv"
    PO_ARM, SP_ARM, PLR_ARM = "43711655", "43711180", "43711603"

    @staticmethod
    def _bs():
        return LostWindowFlagValueTests._module()

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)

    def _salary_with(self, starting: dict, source=None) -> Path:
        """A copy of ``source`` (default the 1910_6g file) with the named
        ids' `Starting` cells set."""
        with (source or self.SALARY).open(newline="", encoding="utf-8-sig") as fh:
            rows = list(csv.reader(fh))
        col, idc = rows[0].index("Starting"), rows[0].index("ID")
        for row in rows[1:]:
            if row[idc] in starting:
                row[col] = starting[row[idc]]
        path = self.root / f"salary_{len(list(self.root.glob('salary_*')))}.csv"
        with path.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        return path

    def _run(self, declared, salary=None):
        """build_slate.main(), run_classic and run_showdown patched to record
        (LostWindowFlagValueTests' harness on this file)."""
        import contextlib
        import io
        mod = self._bs()
        reached = {"build": False}

        def fake(*_a, **_k):
            reached["build"] = True
            return 3, {}

        salary = salary or self.SALARY
        argv = ["build_slate.py", "--salary", str(salary), "--entries", str(salary),
                "--past-slate-replay"]
        for value in declared:
            argv += ["--declare-pitcher", value]
        out = io.StringIO()
        work = self.root / "repo"
        work.mkdir(exist_ok=True)
        with unittest.mock.patch.object(mod, "REPO", work), \
                unittest.mock.patch.object(mod, "run_classic", fake), \
                unittest.mock.patch.object(mod, "run_showdown", fake), \
                unittest.mock.patch.object(sys, "argv", argv):
            with contextlib.redirect_stdout(out), contextlib.redirect_stderr(io.StringIO()):
                code = mod.main()
        try:
            payload = json.loads(out.getvalue())
        except ValueError:
            payload = {}
        staged = list(work.glob("data/slates/*/DKSalaries*.csv"))
        return code, payload, reached["build"], staged

    # -- the grammar ---------------------------------------------------------- #

    def test_the_evidence_option_and_the_role_contract(self):
        bs = self._bs()
        values = ['1=declared_probable_sp:evidence="K line 2.5: an opener\'s, vs 6.1"',
                  "2=viable_bulk_or_alt_sp:ip=3:evidence=K line 4.5 vs season 4.8",
                  "3=declared_probable_sp:ip=5"]
        self.assertEqual(bs.parse_declared_pitchers(values),
                         {"1": "declared_probable_sp", "2": "viable_bulk_or_alt_sp",
                          "3": "declared_probable_sp"},
                         "the {id: role} contract every reader relies on is unchanged")
        self.assertEqual(bs.declared_pitcher_evidence(values),
                         {"1": "K line 2.5: an opener's, vs 6.1",
                          "2": "K line 4.5 vs season 4.8"},
                         "a quoted note may hold a colon; a bare one may hold spaces")
        self.assertEqual(bs.declared_pitcher_workload(values), {"2": 3.0, "3": 5.0})
        for bad, needle in (('1=declared_probable_sp:evidence=""', "evidence is empty"),
                            ("1=declared_probable_sp:evidence=", "evidence is empty"),
                            ('1=declared_probable_sp:evidence="  "', "evidence is empty"),
                            ("1=declared_probable_sp:evidence=a:evidence=b", "given twice"),
                            ("1=declared_probable_sp:evidence=at 12:30", "double-quoted"),
                            ('1=declared_probable_sp:evidence="K line', "cannot read")):
            with self.assertRaises(bs.CliValueError, msg=bad) as ctx:
                bs.parse_declared_pitcher_options([bad])
            self.assertIn(needle, str(ctx.exception), bad)

    def test_preflight_reads_the_role_without_the_evidence(self):
        sys.path.insert(0, str(REPO / "tools"))
        import preflight_upload
        self.assertEqual(
            preflight_upload.parse_declared_pitcher_args(
                [f'{self.PO_ARM}=declared_probable_sp:evidence="K 5.5: a starter\'s line"']),
            {self.PO_ARM: "declared_probable_sp"})

    # -- the build's door ------------------------------------------------------ #

    def test_a_po_arm_declared_without_evidence_refuses_at_exit_4(self):
        """The reproduction: before R471 this reached the build."""
        for value in (self.PO_ARM, f"{self.PO_ARM}=viable_bulk_or_alt_sp:ip=2"):
            code, payload, reached, staged = self._run([value])
            self.assertEqual(code, 4, value)
            self.assertFalse(reached, f"{value}: the build was reached")
            self.assertEqual(staged, [], f"{value}: the salary file was staged")
            self.assertEqual(payload["status"], "cli_value_invalid")
            self.assertEqual(payload["flag"], "--declare-pitcher")
            self.assertEqual(payload["po_arms_without_evidence"], [
                {"player_id": self.PO_ARM, "name": "Yohan Ramirez", "team": "PIT",
                 "dk_starting": "PO"}])
            for needle in ("Yohan Ramirez (43711655, PIT) Starting=PO", ':evidence="',
                           "strikeout prop"):
                self.assertIn(needle, payload["error"], value)

    def test_every_po_arm_is_named_in_id_order(self):
        salary = self._salary_with({self.SP_ARM: "PO"})
        code, payload, reached, _staged = self._run(
            [self.PO_ARM, self.SP_ARM, self.PLR_ARM], salary=salary)
        self.assertEqual((code, reached), (4, False))
        self.assertEqual([a["player_id"] for a in payload["po_arms_without_evidence"]],
                         [self.SP_ARM, self.PO_ARM], "one refusal names both, sorted by id")

    def test_evidence_on_one_po_arm_does_not_cover_another(self):
        salary = self._salary_with({self.SP_ARM: "PO"})
        code, payload, reached, _staged = self._run(
            [f'{self.PO_ARM}=declared_probable_sp:evidence="K 5.5 vs 5.0"', self.SP_ARM],
            salary=salary)
        self.assertEqual((code, reached), (4, False))
        self.assertEqual([a["player_id"] for a in payload["po_arms_without_evidence"]],
                         [self.SP_ARM])

    def test_a_po_arm_with_evidence_reaches_the_build(self):
        """The positive control: without it, refusing every PO declaration
        passes every test above and retires the documented way past R104."""
        code, payload, reached, _staged = self._run(
            [f'{self.PO_ARM}=declared_probable_sp:evidence="K line 4.5 vs season 4.8"'])
        self.assertTrue(reached, payload)
        self.assertEqual(code, 3, "the patched build's own exit")

    def test_a_non_po_arm_declared_bare_reaches_the_build(self):
        # R489: the PLR arm now types its role; a bare PLR id is refused
        # (PlrBareDeclarationTests), and the SP arm still reaches it bare.
        code, payload, reached, _staged = self._run(
            [self.SP_ARM, f"{self.PLR_ARM}=viable_bulk_or_alt_sp"])
        self.assertTrue(reached, payload)
        self.assertEqual(code, 3)

    def test_showdown_is_not_checked(self):
        """R347: a Showdown pool takes no declaration and keeps a PO arm as
        `declared_opener`, so the wall is Classic's."""
        bs = self._bs()
        source = REPO / "tests" / "fixtures" / "showdown" / "DKSalaries_showdown_MIN_CHC.csv"
        salary = self._salary_with({"43628708": "PO"}, source=source)
        self.assertEqual(bs.detect_contest_type(salary, salary), "showdown")
        args = types.SimpleNamespace(
            date="2026-07-18", salary=str(salary), entries_csv=str(salary),
            declare_pitcher=["43628708"], controls_override=None, leverage=None,
            postures=None, assume_gates=None, captain_sleeve=None)
        self.assertIsNone(bs.validate_cli_values(args))
        self.assertEqual([a["player_id"] for a in bs.po_declarations_without_evidence(
            salary, {"43628708": "declared_probable_sp"}, {})], ["43628708"],
            "the arm IS PO on this file; only the Classic guard lets it through")

    def test_no_salary_file_defers_to_missing_inputs(self):
        bs = self._bs()
        args = types.SimpleNamespace(
            date="2026-07-30", salary=str(self.root / "absent.csv"),
            entries_csv=str(self.SALARY), declare_pitcher=[self.PO_ARM],
            controls_override=None, leverage=None, postures=None, assume_gates=None,
            captain_sleeve=None)
        self.assertIsNone(bs.validate_cli_values(args))

    def test_an_unreadable_salary_file_defers_to_the_pool_build(self):
        """A file the engine's parser refuses builds nothing: the pool reads it
        with the same parser and refuses it by name, so the check steps aside
        rather than crash main() at exit 1 before any refusal is printed."""
        bs = self._bs()
        bad = self.root / "bad.csv"
        bad.write_text("Name,Salary\nX,1\n", encoding="utf-8")
        from mlb_engine.intake.slate_intake_manager import parse_dk_salary_csv
        with self.assertRaises(ValueError):
            parse_dk_salary_csv(str(bad))
        args = types.SimpleNamespace(
            date="2026-07-30", salary=str(bad), entries_csv=str(bad),
            declare_pitcher=[self.PO_ARM], controls_override=None, leverage=None,
            postures=None, assume_gates=None, captain_sleeve=None)
        self.assertIsNone(bs.validate_cli_values(args))

    def test_one_token_set_serves_the_bar_and_the_check(self):
        from mlb_engine.intake import slate_intake_manager as sim
        self.assertIs(lda.DK_STARTING_OPENER_TOKENS, sim.DK_STARTING_OPENER_TOKENS)
        src = (REPO / "mlb_engine" / "intake" / "live_data_adapters.py").read_text(encoding="utf-8")
        self.assertNotIn("DK_STARTING_OPENER_TOKENS = ", src, "a second definition")

    # -- the brief ------------------------------------------------------------ #

    def test_every_brief_site_that_records_the_roles_records_the_notes(self):
        """Five sites record `declared_pitchers` (the baseline brief, Classic's
        refusal and delivered briefs, Showdown's refusal and delivered
        briefs); each records `declared_pitcher_evidence` beside it."""
        import re as _re
        src = (REPO / "skills" / "generate-lineups" / "scripts" / "build_slate.py").read_text(encoding="utf-8")
        roles = _re.findall(r'"declared_pitchers"\]?\s*[:=]\s*parse_declared_pitchers\(', src)
        notes = _re.findall(r'"declared_pitcher_evidence"\]?\s*[:=]\s*declared_pitcher_evidence\(', src)
        self.assertEqual(len(roles), 5)
        self.assertEqual(len(notes), len(roles))

    def test_the_baseline_brief_records_the_note(self):
        bs = self._bs()
        out = self.root / "outputs" / "2026-07-30"
        out.mkdir(parents=True)
        delivered = out / "DKEntries_1910_6g_BASELINE_r1.csv"
        delivered.write_text("x\n", encoding="utf-8")
        args = types.SimpleNamespace(date="2026-07-30", declare_pitcher=[
            f'{self.PO_ARM}=declared_probable_sp:evidence="K line 4.5 vs season 4.8"',
            self.SP_ARM])
        got = bs._write_baseline_brief(args, self.SALARY,
                                       {"path": str(delivered), "sha256": "ab", "run_id": "r1"})
        self.assertTrue(got["written"], got)
        brief = json.loads(Path(got["path"]).read_text(encoding="utf-8"))
        self.assertEqual(brief["declared_pitcher_evidence"],
                         {self.PO_ARM: "K line 4.5 vs season 4.8"})
        self.assertEqual(brief["declared_pitchers"],
                         {self.PO_ARM: "declared_probable_sp", self.SP_ARM: "declared_probable_sp"})

    def test_run_classic_records_the_note_on_its_payload(self):
        harness = DeadlineGovernorWiringTests(
            "test_the_anti_correlation_flag_reaches_the_controls_the_validator_grades")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        code, payload, _calls, _err = harness._run(30, args_overrides={"declare_pitcher": [
            '43706740=viable_bulk_or_alt_sp:evidence="bulk behind an opener"']})
        self.assertEqual(code, 3)
        self.assertEqual(payload["declared_pitcher_evidence"],
                         {"43706740": "bulk behind an opener"})

    # -- late swap's door ----------------------------------------------------- #

    def _swap(self):
        harness = LateSwapDeclaredPitcherTests("test_the_grammar_is_build_slates_own_parser")
        harness.setUp()
        self.addCleanup(harness.doCleanups)
        with harness.salary.open(newline="", encoding="utf-8") as fh:
            rows = list(csv.reader(fh))
        ids = {row[2]: row[3] for row in rows[1:]}
        harness.po_arm = ids["T4 Pen1"]
        rows[0].append("Starting")
        for row in rows[1:]:
            row.append("PO" if row[3] == harness.po_arm else "")
        harness.po_salary = harness.root / "DKSalaries_po.csv"
        with harness.po_salary.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        return harness

    @staticmethod
    def _swap_manifests(harness):
        manifests = [json.loads(p.read_text()) for p in (harness.root / "runs").glob("*/manifest.json")]
        return [m for m in manifests if m.get("mode") == "late_swap"]

    def test_a_swap_refuses_an_explicit_po_declaration_without_evidence(self):
        harness = self._swap()
        harness._brief()
        code, _out, err = harness._run("--salary", str(harness.po_salary),
                                       "--declare-pitcher", harness.po_arm)
        self.assertEqual(code, 4, err[-1500:])
        self.assertIn(f"T4 Pen1 ({harness.po_arm}, T4) Starting=PO", err)
        self.assertIn("Nothing was swapped", err)
        self.assertEqual(self._swap_manifests(harness), [], "a swap run was written")

    def test_a_swap_carries_the_parents_note_and_it_covers_a_re_declaration(self):
        """The parent build declared the PO arm with evidence; the swap
        re-declares him with a new role and no note. The parent's note
        covers him, and the swap's manifest carries it so a swap of this
        swap does too."""
        harness = self._swap()
        out_dir = harness.root / "outputs" / harness.DATE
        out_dir.mkdir(parents=True, exist_ok=True)
        (out_dir / "build_brief_test.json").write_text(json.dumps({
            "run_id": harness.parent["run_id"],
            "delivered_sha256": sha256_file(harness.parent_file),
            "declared_pitchers": {**harness.declared, harness.po_arm: "declared_probable_sp"},
            "declared_pitcher_evidence": {harness.po_arm: "K line 5.5 vs season 5.2"},
        }), encoding="utf-8")
        code, out, err = harness._run("--salary", str(harness.po_salary), "--declare-pitcher",
                                      f"{harness.po_arm}=viable_bulk_or_alt_sp")
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn(f"declared evidence: {harness.po_arm}: K line 5.5 vs season 5.2", out)
        swaps = self._swap_manifests(harness)
        self.assertEqual(len(swaps), 1)
        self.assertEqual(swaps[0]["metadata"]["declared_pitcher_evidence"],
                         {harness.po_arm: "K line 5.5 vs season 5.2"})

    def test_an_inherited_po_declaration_is_not_re_judged(self):
        """A parent that declared a PO arm with no note (a pre-R471 build)
        still swaps: the swap adds no fact, and blocking it blocks a repair.
        The swap also declares a non-PO arm of its own, so the check runs and
        must read only what this command line declared."""
        harness = self._swap()
        harness._brief(declared={**harness.declared, harness.po_arm: "declared_probable_sp"})
        with harness.po_salary.open(newline="", encoding="utf-8") as fh:
            ids = {row[2]: row[3] for row in list(csv.reader(fh))[1:]}
        code, out, err = harness._run("--salary", str(harness.po_salary),
                                      "--declare-pitcher", ids["T3 Pen1"])
        self.assertEqual(code, 0, err[-1500:])
        self.assertIn(f"{harness.po_arm}=declared_probable_sp", out, "the PO arm was inherited")
        self.assertIn(f"WARN declared arm T4 Pen1 ({harness.po_arm}, T4) is inherited from "
                      f"the parent and DK tags him Starting=PO", out, "named, not silent")
        self.assertEqual(out.count("WARN declared arm"), 1, "only the inherited PO arm")

    def test_the_swap_evidence_resolver_merges_and_keeps_declared_arms(self):
        ls = LateSwapDeclaredPitcherTests._tool()
        record = {"declared_pitcher_evidence": {"111": "a", "222": "b", "333": "  "}}
        self.assertEqual(
            ls.resolve_swap_declared_evidence(record, {"222": "typed"},
                                              {"111": "r", "222": "r", "333": "r"}),
            {"111": "a", "222": "typed"}, "explicit over inherited; a blank note is no note")
        self.assertEqual(ls.resolve_swap_declared_evidence(record, {}, {"111": "r"}), {"111": "a"},
                         "a note for an arm no longer declared is dropped")
        self.assertEqual(ls.resolve_swap_declared_evidence(None, {}, {"111": "r"}), {})
        # A swap of a swap reads the parent swap run's manifest record.
        parent = {"current_matches_parent_export": True, "manifest": {
            "run_id": "swap1", "metadata": {"declared_pitchers": {"111": "r"},
                                            "declared_pitcher_evidence": {"111": "a"}}}}
        got, where = ls._parent_declaration_record(Path("."), "2026-07-10", parent)
        self.assertEqual(got["declared_pitcher_evidence"], {"111": "a"})
        self.assertIn("swap1", where)

class StandingsReadTests(unittest.TestCase):
    """R472 (roadmap Session 141). `tools/standings_read.py` reads a live DK
    standings export for the late-swap decision.

    SYNTHETIC FIXTURES, stated here because it is the load-bearing caveat: 0 of
    the 516,804 archived standings rows carry a nonzero TimeRemaining, so the
    LIVE format (its unit, how a hidden or open slot appears in a Lineup cell) has
    never been seen. Every export below is written by this class in the archived
    column layout; it checks the tool's arithmetic and its refusals, never that
    DraftKings' live file looks like this.

    The slate is the four-team pool fixture: T1@T2 started (23:05Z) and T3@T4 not
    (01:05Z next day), the clock at 23:30Z, so T1/T2 players are locked and T3/T4
    players are open. Ceilings: pitchers 20.0, hitters 10.0 unless a test says.
    """

    DATE = "2026-07-10"
    AS_OF = datetime(2026, 7, 10, 23, 30, tzinfo=timezone.utc)
    HEADER = ["Rank", "EntryId", "EntryName", "TimeRemaining", "Points", "Lineup", "",
              "Player", "Roster Position", "%Drafted", "FPTS"]
    LABEL_FRAGMENT = "Never a win rate, cash rate, ROI, edge or probability"

    LOCKED_ALL = ["T1 Ace", "T2 Ace", "T1 Hitter1", "T1 Hitter2", "T1 Hitter3",
                  "T1 Hitter4", "T1 Hitter5", "T2 Hitter6", "T2 Hitter7", "T2 Hitter8"]
    # P1 locked (T1), P2 open (T3 Ace), C..SS locked (T1), the three OF open (T3).
    OPEN4 = ["T1 Ace", "T3 Ace", "T1 Hitter1", "T1 Hitter2", "T1 Hitter3",
             "T1 Hitter4", "T1 Hitter5", "T3 Hitter6", "T3 Hitter7", "T3 Hitter8"]

    @staticmethod
    def _tool():
        import importlib.util
        spec = importlib.util.spec_from_file_location(
            "standings_read_r472", REPO / "tools" / "standings_read.py")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.sr = self._tool()
        self.salary, self.ids = self._salary_file()
        self.slate = self._slate(self.salary)

    # -- fixtures ------------------------------------------------------------ #

    def _salary_file(self, salary_by_name=None, rename=None, name="DKSalaries.csv"):
        path = self.root / name
        pool_salary_csv(path)
        with path.open(newline="", encoding="utf-8") as fh:
            rows = list(csv.reader(fh))
        for row in rows[1:]:
            if row[8] in ("T3", "T4"):
                row[6] = row[6].replace("07:05PM", "09:05PM")
            if rename and row[2] in rename:
                row[1] = row[1].replace(row[2], rename[row[2]])
                row[2] = rename[row[2]]
            if salary_by_name and row[2] in salary_by_name:
                row[5] = str(salary_by_name[row[2]])
        with path.open("w", newline="", encoding="utf-8") as fh:
            csv.writer(fh).writerows(rows)
        return path, {row[2]: row[3] for row in rows[1:]}

    def _slate(self, salary, as_of=None):
        feed = pool_lineups_feed(t4_confirmed=True)
        feed["games"][1]["game_date_utc"] = "2026-07-11T01:05:00Z"
        status = build_status_map_from_lineups_feed(feed, str(salary))
        players = {p.player_id: p for p in parse_dk_salary_csv(str(salary))}
        return self.sr.Slate(players, status["status_by_player_id"], as_of or self.AS_OF)

    def _frame_csv(self, ceilings=None, drop=(), name="projections.csv"):
        path = self.root / name
        ceilings = dict(ceilings or {})
        with path.open("w", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow(["Player_ID", "Name", "Salary", "Floor", "Ceiling"])
            for player_name, pid in sorted(self.ids.items(), key=lambda kv: int(kv[1])):
                if player_name in drop:
                    continue
                default = 20.0 if "Ace" in player_name or "Pen" in player_name else 10.0
                writer.writerow([pid, player_name, 3500, 1.0, ceilings.get(player_name, default)])
        return path

    def _cell(self, names):
        slots = list(self.sr.SLOT_TYPES)
        return " ".join(f"{slot} {n}" for slot, n in zip(slots, names))

    def _write_standings(self, rows, name="contest-standings-900.csv", players=()):
        """rows: (rank, entry_id, time_remaining, points, names_or_cell)."""
        path = self.root / name
        body = []
        for i in range(max(len(rows), len(players))):
            left = ["", "", "", "", "", ""]
            if i < len(rows):
                rank, eid, tr, pts, lineup = rows[i]
                cell = lineup if isinstance(lineup, str) else self._cell(lineup)
                left = [str(rank), str(eid), f"user{eid}", str(tr), str(pts), cell]
            right = ["", "", "", ""]
            if i < len(players):
                pname, pos, pct, fpts = players[i]
                right = [pname, pos, pct, str(fpts)]
            body.append(left + [""] + right)
        with path.open("w", newline="", encoding="utf-8-sig") as fh:
            writer = csv.writer(fh)
            writer.writerow(self.HEADER)
            writer.writerows(body)
        return path

    def _field(self, extra=(), tr="0"):
        rows = [(1, "9001", tr, 100.0, self.LOCKED_ALL), (2, "9002", tr, 95.0, self.LOCKED_ALL),
                (3, "9003", tr, 85.0, self.LOCKED_ALL), (4, "9004", tr, 80.0, self.LOCKED_ALL),
                (5, "7001", tr, 70.0, self.OPEN4), (6, "7002", tr, 40.0, self.OPEN4),
                (7, "7003", tr, 10.0, self.OPEN4)]
        return rows + list(extra)

    def _seat(self, entry_id, names, contest_id="900"):
        return {"entry_id": entry_id, "contest_id": contest_id,
                "roster_ids": [self.ids[n] for n in names], "problem": ""}

    def _seats(self):
        return [self._seat("7001", self.OPEN4), self._seat("7002", self.OPEN4),
                self._seat("7003", self.OPEN4)]

    def _report(self, rows=None, seats=None, paid=4, k=1, ceilings=None, drop=(),
                slate=None, leaders=10, players=()):
        path = self._write_standings(rows if rows is not None else self._field(),
                                     players=players)
        standing = self.sr.read_standings(path)
        frame = self.sr.load_frame(self._frame_csv(ceilings, drop))
        return self.sr.build_report(
            standings={"900": standing}, seats=seats if seats is not None else self._seats(),
            slate=slate or self.slate, ceilings=self.sr.Ceilings([("parent", frame)]),
            target_rank=k, paid_places=({"900": paid} if paid else {}),
            leaders_n=leaders, root=self.root)

    # -- reading: csv and zip, the by-name refusals ---------------------------- #

    def test_a_csv_and_a_zip_read_identically_and_the_zip_is_never_extracted(self):
        import zipfile
        csv_path = self._write_standings(self._field())
        zip_path = self.root / "contest-standings-900.zip"
        with zipfile.ZipFile(zip_path, "w") as zf:
            zf.write(csv_path, "contest-standings-900.csv")
        before = sorted(p.name for p in self.root.iterdir())
        a, b = self.sr.read_standings(csv_path), self.sr.read_standings(zip_path)
        self.assertEqual(sorted(p.name for p in self.root.iterdir()), before,
                         "reading a zip must not extract anything beside it")
        self.assertEqual(a["contest_id"], "900")
        self.assertEqual(b["contest_id"], "900")
        self.assertEqual(a["entries"], b["entries"])
        self.assertEqual(a["player_table"], b["player_table"])
        self.assertEqual(len(a["entries"]), 7)
        # Negative controls, each refused by name.
        two = self.root / "two.zip"
        with zipfile.ZipFile(two, "w") as zf:
            zf.write(csv_path, "contest-standings-900.csv")
            zf.write(csv_path, "contest-standings-901.csv")
        none = self.root / "none.zip"
        with zipfile.ZipFile(none, "w") as zf:
            zf.writestr("readme.txt", "x")
        junk = self.root / "contest-standings-902.zip"
        junk.write_bytes(b"not a zip")
        txt = self.root / "contest-standings-903.txt"
        txt.write_text("x", encoding="utf-8")
        for path, needle in ((two, "2 CSV member"), (none, "0 CSV member"),
                             (junk, "not a readable zip"), (txt, "a .csv or a .zip")):
            with self.assertRaises(self.sr.StandingsFormatError, msg=path.name) as ctx:
                self.sr.read_standings(path)
